window.__LEX={"G4900":"<h1>sunelauno</h1>\n<p>Strong n° 4900 <i>Prononciation [soon-el-ow'-no]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>conduire ensemble, forcer, pousser ensemble, exciter</li>\n<li>contraindre par extorsion, presser</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>συν·αλλάσσω</b>, <i>att</i>. <b>-άττω</b>, <i>anc. att</i>. <b>ξυναλλάττω :<br>   I <i>tr</i>.<br>      1</b> mettre en relation, unir : τινά τινι, ESCHL. <i>Sept. 597,</i> une pers. à une autre ; <i>au pass</i>. avoir des relations avec, être uni <i>ou</i> s’unir avec, <i>dat</i>. SOPH. <i>Aj. 493 ;</i> EUR. <i>Andr. 1245 ;</i><br><b>      2</b> réconcilier, <i>acc</i>. XÉN. <i>Vect. 5, 8 ;</i> τινά τινι, THC. <i>1, 24,</i> une personne avec une autre ; <i>abs</i>. PLAT. <i>Leg. 930</i> a ; <i>au pass</i>. se réconcilier, THC. <i>4, 19 ; 5, 5 ;</i> πρός τινα, THC. <i>8, 90 ;</i> XÉN. <i>An. 1, 2, 1,</i> avec qqn ;<br><b>   II <i>intr.</i></b> avoir des relations avec, <i>dat</i>. DÉM. <i>760, 12 ;</i> ARSTT. <i>Nic. 10, 8, 7 ;</i> PLUT. <i>Dio. 8 ; abs</i>. SOPH. <i>O.R. 1110 ;</i> EUR. <i>Her. 4 ;</i> PLUT. <i>M. 12</i> e.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">συνελαυνω - συναλλάσσω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G4901":"<h1>sunepimartureo</h1>\n<p>Strong n° 4901 <i>Prononciation [soon-ep-ee-mar-too-reh'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>attester ensemble avec, confirmer</li>\n<li>se joindre en étant un témoin, s'unir dans l'addition de témoignage</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>συν·επιμαρτυρέω-ῶ</b> <span>[τῠ]</span><br><b>      1</b> ajouter son témoignage à celui d’un autre, appuyer de son témoignage, <i>dat</i>. ARSTT. <i>Mund. 6, 31 ;</i> POL. <i>26, 9, 4 ;</i> ATH. <i>595</i> e, <i>etc. ;</i><br><b>      2</b> donner un témoignage favorable à, approuver, recommander, PLUT. <i>M. 486</i> c, <i>539</i> d, <i>etc</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">συνεπιμαρτυρεω - συνεπιμαρτυρέω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Hébreux (1)</li>\n</ul>\n</td></tr>\n</table>","G4902":"<h1>sunepomai</h1>\n<p>Strong n° 4902 <i>Prononciation [soon-ep'-om-ahee]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>suivre avec, accompagner, être à la suite de</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>συν·έπομαι</b>, <i>anc. att</i>. <b>ξυν·έπομαι</b> <span>(<i>impf</i>. συνειπόμην, <i>f</i>. συνέψομαι, <i>ao.2</i> συνεσπόμην)</span><br><b>   I</b> suivre pas à pas, accompagner côte à côte, <i>dat</i>. HDT. <i>5, 47 ; 1, 60, etc. ; abs</i>. THC. <i>7, 39 ;</i> ESCHL. <i>Ag. 955 ;</i><br><b>   II</b> <i>fig. :</i><br><b>      1</b> suivre la marche de, saisir, comprendre (un argument, un raisonnement) <i>dat</i>. PLAT. <i>Leg. 695</i> c ; ARSTT. <i>Nic. 4, 12 ; abs</i>. PLAT. <i>Soph. 238</i> e, <i>Tim. 53</i> c ;<br><b>      2</b> s’accorder avec, être la conséquence de, <i>dat</i>. PLAT. <i>Leg. 679</i> e, <i>706</i> a, <i>Phil. 24</i> d, <i>etc. ; qqf. gén</i>. PLAT. <i>Leg. 899</i> c ;<br><b>      3</b> se laisser convaincre, <i>d’où</i> obéir à (la loi, <i>etc.) dat</i>. PLAT. <i>Leg. 916</i> d ; <i>abs</i>. THC. <i>3, 38</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Ao.2 sbj</i>. συνέσπωμαι, PLAT. <i>Leg. 706</i> a.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">συνεπομαι - συνέπομαι</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G4903":"<h1>sunergeo</h1>\n<p>Strong n° 4903 <i>Prononciation [soon-erg-eh'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>travailler ensemble, aider dans le travail, être associé dans le labeur, coopérer, collaborer</li>\n<li>faire concourir les choses, agir ensemble, assister</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>συνεργέω-ῶ</b>, <i>anc. att</i>. <b>ξυνεργέω</b> <span>(<i>impf</i>. συνήργουν, <i>f</i>. συνεργήσω, <i>ao</i>. συνήργησα, <i>etc</i>.)</span><br><b>      1</b> travailler avec, aider pour un travail, EUR. <i>Hel. 1427 ;</i><br><b>      2</b> aider, <i>en gén. :</i> τινι, XÉN. <i>Mem. 2, 3, 18, etc</i>. qqn ; σ. τινι συμφέροντα, XÉN. <i>Mem. 3, 5, 16,</i> être d’accord avec qqn pour les choses utiles ; τινί τι, HLD. <i>9, 11,</i> aider <i>ou</i> assister qqn en qqe ch. ; τινι ἔς τι, ARSTT. <i>Nic. 9, 11, 6 ;</i> τινι πρός τι, POL. <i>3, 97, 5,</i> qqn pour qqe ch. ; σ. πρός τι, ARSTT. <i>M. mor. 1, 4, 11, etc</i>. être utile pour qqe ch. ; <i>au pass</i>. être assisté, DH. <i>9, 23</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Dans une inscr. att. ao. 3 sg</i>. συνήργησεν, CIA. <i>2, 313, 11 (286 av. J.C.) ; v. Meisterh. p. 136, 12</i>.<br><span><b>Étym</b>. συνεργός.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">συνεργεω - συνεργέω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n5 fois dans 5 versets de 5 livres bibliques (NT)\n<ul>\n<li>Marc (1)</li>\n<li>Romains (1)</li>\n<li>1 Corinthiens (1)</li>\n<li>2 Corinthiens (1)</li>\n<li>Jacques (1)</li>\n</ul>\n</td></tr>\n</table>","G4904":"<h1>sunergos</h1>\n<p>Strong n° 4904 <i>Prononciation [soon-er-gos']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>un compagnon dans le travail, un compagnon d'œuvre, collaborateur, aide</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>συν·εργός</b>, <i>anc. att</i>. <b>ξυν·εργός, ός, όν :<br>      1</b> qui prête son aide <i>ou</i> son concours : τινι, THC. <i>3, 63 ;</i> XÉN. <i>Cyr. 8, 4, 17, etc. ; rar</i>. τινος, PLUT. <i>Per. 31,</i> à qqn ; <i>abs</i>. auxiliaire, THC. <i>8, 92, etc. ; d’où en mauv. part,</i> complice, EUR. <i>Or. 1446, Med. 395, etc. ; avec un rég. de chose :</i> τινος, EUR. <i>Hipp. 676, etc</i>. qui aide à faire qqe ch., qui aide à qqe ch. ; <i>avec double rég</i>. σ. τινί τινος, XÉN. <i>An. 1, 9, 21 ;</i> PLAT. <i>Conv. 180</i> e, qui aide qqn en qqe ch. ; <i>avec une prép. :</i> σ. πρός τι, XÉN. <i>Mem. 4, 3, 7 ;</i> εἴς τι, XÉN. <i>Mem. 4, 3, 10 ;</i> ἔν τινι, AR. <i>Eq. 588,</i> qui aide pour qqe ch., en vue de qqe ch. ; <i>avec un inf</i>. EUR. <i>Ion 48,</i> pour faire qqe ch. ;<br><b>      2</b> qui fait le même travail <i>ou</i> exerce la même profession, <i>d’où</i> collaborateur, collègue de, <i>gén</i>. DÉM. <i>385, 23</i>.<br><span><b>Étym</b>. σ. ἔργον.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">συνεργος - συνεργός</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n12 fois dans 12 versets de 7 livres bibliques (NT)\n<ul>\n<li>Romains (3)</li>\n<li>1 Corinthiens (1)</li>\n<li>2 Corinthiens (2)</li>\n<li>Philippiens (2)</li>\n<li>Colossiens (1)</li>\n<li>Philémon (2)</li>\n<li>3 Jean (1)</li>\n</ul>\n</td></tr>\n</table>","G4905":"<h1>sunerchomai</h1>\n<p>Strong n° 4905 <i>Prononciation [soon-er'-khom-ahee]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>venir ensemble\n<ol type=\"a\">\n<li>s'assembler</li>\n<li>d'une cohabitation conjugale</li>\n</ol>\n</li>\n<li>aller, partir ou venir avec quelqu'un, accompagner quelqu'un</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>συν·έρχομαι</b>, <i>anc. att</i>. <b>ξυν·έρχομαι</b> <span>(<i>f</i>. -ελεύσομαι, <i>ao.2</i> -ῆλθον, <i>etc</i>.)</span><br><b>   I</b> aller ensemble, se rencontrer, <i>càd. :</i><br><b>      1</b> se réunir, HDT. <i>1, 152, etc. ;</i> ATT. ; ἐς τωὐτό, HDT. <i>1, 202 ;</i> εἰς ταὐτό, XÉN. <i>Ath. 2, 2 ;</i> PLAT. <i>Rsp. 329</i> a, <i>etc</i>. dans le même lieu ; <i>avec l’acc. sans prép. :</i> στρατείαν ξ. THC. <i>1, 3,</i> se réunir pour une expédition ; σ. τὸ λέχος, SOPH. <i>Aj. 486,</i> partager la couche de qqn ; σ. ἐς λόγους τινί, HDT. <i>1, 82 ; ou</i> ἀλλήλοις εἰς λόγον, AR. <i>Eq. 1300,</i> se rencontrer avec qqn, les uns avec les autres pour un entretien ; <i>d’où abs</i>. σ. τινι, SOPH. <i>O.R. 572,</i> se concerter avec qqn ;<br><b>      2</b> s’unir : εἰς ἕν, EUR. <i>Tr. 1155, Ph. 462 ;</i> εἰς ταὐτόν, PLAT. <i>Tim. 32</i> c, <i>ou</i> εἰς ταὐτό, PLAT. <i>Charm. 157</i> e, en un tout, en une seule famille, en une communauté d’amitié, <i>etc. ; en parl. de villes, d’États,</i> s’unir, DÉM. <i>231, 18 ; particul</i>. avoir commerce avec : γυναικί, XÉN. <i>Mem. 2, 2, 4,</i> avec une femme ; <i>cf</i>. PLAT. <i>Conv. 192</i> e ; DS. <i>3, 58 ;</i> PLUT. <i>M. 752</i> e ; <i>abs</i>. PLUT. <i>Thes. 3, etc. ; en parl. d’animaux,</i> s’accoupler, ARSTT. <i>H.A. 5, 8, 1 ;</i><br><b>      3</b> se réunir, se réconcilier, PLUT. <i>M. 481</i> d ;<br><b>      4</b> se rencontrer, en venir aux mains avec, <i>dat</i>. HDT. <i>1, 80 ;</i> PLUT. <i>Eum. 7 ;</i> σ. εἰς μάχην, PLAT. <i>Theæt. 154</i> d, engager une lutte ; <i>en parl. de l’engagement lui-même :</i> μάχη ὑπὸ ἀξιολογωτάτων πόλεων ξυνελθοῦσα, THC. <i>5, 74,</i> combat où se rencontrèrent les forces des États les plus considérables ;<br><b>      5</b> se rencontrer, <i>en parl. de fleuves,</i> AR. <i>fr. 198, 12 Dind. ; d’astres en conjonction,</i> ARSTT. <i>Meteor. 1, 6, 15 ; fig. en parl. d’événements,</i> aboutir au même point, concorder, SOPH. <i>Tr. 619 ;</i> EUR. <i>Tr. 1155 ; d’où, avec idée de temps,</i> se produire dans le même temps, coïncider, HDT. <i>6, 77 ;</i><br><b>      6</b> <i>p. suite,</i> se réunir, se refermer, <i>en parl. d’une ouverture,</i> PLUT. <i>M. 306</i> e ;<br><b>      7</b> se réunir, s’ajouter, former un total, HDT. <i>3, 159</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">συνερχομαι - συνέρχομαι</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n31 fois dans 31 versets de 6 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Marc (2)</li>\n<li>Luc (2)</li>\n<li>Jean (2)</li>\n<li>Actes (16)</li>\n<li>1 Corinthiens (8)</li>\n</ul>\n</td></tr>\n</table>","G4906":"<h1>sunesthio</h1>\n<p>Strong n° 4906 <i>Prononciation [soon-es-thee'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>manger avec, prendre de la nourriture ensemble</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>συν·εσθίω</b> <span>(<i>f</i>. -έδομαι, <i>ao.2</i> συνέφαγον, <i>etc</i>.)</span> manger avec <i>ou</i> en même temps, <i>dat</i>. PLAT. <i>Leg. 881</i> d ; <i>abs</i>. ARSTT. <i>Eud. 7, 12, 9</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">συνεσθιω - συνεσθίω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n5 fois dans 5 versets de 4 livres bibliques (NT)\n<ul>\n<li>Luc (1)</li>\n<li>Actes (2)</li>\n<li>1 Corinthiens (1)</li>\n<li>Galates (1)</li>\n</ul>\n</td></tr>\n</table>","G4907":"<h1>sunesis</h1>\n<p>Strong n° 4907 <i>Prononciation [soon'-es-is]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>courir ensemble, couler, s'écouler ensemble</li>\n<li>connaissance\n<ol type=\"a\">\n<li>compréhension</li>\n<li>l'intelligence, c.à.d. l'esprit dans la limite où il comprend, perspicacité, sagesse</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>σύνεσις</b>, <i>anc. att</i>. <b>ξύνεσις, εως (ἡ) :<br>   I</b> rencontre, jonction (de deux fleuves) OD. <i>10, 515 ; d’où</i> réunion (de deux choses en une) JAMBL. <i>Nicom. ar. 133</i> b ; <i>cf</i>. CLÉM. <i>674 ;</i><br><b>   II</b> <i>fig. :</i><br><b>      1</b> compréhension, intelligence, THC. <i>2, 62 ; 3, 82, etc. ; p. opp. à</i> μάθησις, THC. <i>1, 138 ; cf</i>. PLAT. <i>Crat. 412</i> a, <i>etc. ; joint à</i> σοφία, EUR. <i>H.f. 655 ; à</i> φρόνησις, PLAT. <i>Crat. 411</i> a ; σύνεσιν ἔχειν, HDT. <i>2, 5,</i> avoir de l’intelligence, <i>en parl. d’animaux,</i> PLAT. <i>Menex. 237</i> d ; <i>cf</i>. ARSTT. <i>H.A. 8, 1, 2, etc. ;</i><br><b>      2</b> connaissance intime, conscience, EUR. <i>Or. 396 ;</i> POL. <i>18, 26, 13, etc. ;</i><br><b>      3</b> connaissance, <i>en gén., p. opp. à</i> ἄγνοια, ARSTT. <i>An. 1, 5, 13 ;</i><br><b>      4</b> <i>p. ext</i>. objet de la connaissance, science, art, ARSTT. <i>Pol. 8, 7, 11</i>.<br><span><b>Étym</b>. συνίημι.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">συνεσις - σύνεσις</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Synonymes</big></td></tr>\n<tr><td>Comparer : , \n<br><br> indique la connaissance par elle-même,  la sagesse qui est montrée dans l'action,  s'applique principalement à l'appréhension des vérités,  ajoute la puissance du raisonnement et renforce leurs parentés.\n<br><br>Comparer : , , \n<br><br> – dénote une « excellence mentale du plus haut niveau »\n<br><br> – critique, incluant le maintien des choses\n<br><br> – pratique, suggérant des lignes d'action</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n7 fois dans 7 versets de 6 livres bibliques (NT)\n<ul>\n<li>Marc (1)</li>\n<li>Luc (1)</li>\n<li>1 Corinthiens (1)</li>\n<li>Ephésiens (1)</li>\n<li>Colossiens (2)</li>\n<li>2 Timothée (1)</li>\n</ul>\n</td></tr>\n</table>","G4908":"<h1>sunetos</h1>\n<p>Strong n° 4908 <i>Prononciation [soon-et'-os]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>intelligent, ayant de la compréhension, sage, instruit, perspicace</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>συνετός</b>, <i>anc. att</i>. <b>ξυνετός, ή, όν :<br>      1</b> <i>act</i>. intelligent, avisé, prudent, <i>en parl. de pers</i>. PD. <i>O. 2, 152 ; P. 5, 144 ;</i> HDT. <i>1, 185 ;</i> THC. <i>3, 82, etc. ; particul</i>. intelligent de nature, <i>p. opp. à</i> μαθών, THC. <i>1, 84, etc. ; en part. d’animaux,</i> ARSTT. <i>H.A. 8, 110, etc. ; de choses (esprit, etc</i>. AR. <i>Ran. 876, etc.) ; avec le gén. :</i> σ. τινος, EUR. <i>Or. 1406,</i> qui a l’intelligence <i>ou</i> la connaissance de qqe ch. ; τὸ συνετόν, THC. <i>2, 15 ;</i> EUR. <i>Or. 1180, etc</i>. l’intelligence ;<br><b>      2</b> <i>pass</i>. facile à comprendre, intelligible, THGN. <i>1078 ;</i> HDT. <i>2, 57 ;</i> EUR. <i>Ph. 498, etc</i>.<br><span>•<i> Cp</i>. -ώτερος, THC. <i>3, 37 ;</i> ARSTT. <i>H.A. 8, 1 ;</i> LUC. <i>D. mort. 6, 3</i>. <i>• Sup</i>. -ώτατος, THC. <i>1, 74</i>.<br><span><b>Étym</b>. συνίημι.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">συνετος - συνετός</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Synonymes</big></td></tr>\n<tr><td> – dénote le sage, celui qui est habile, un expert\n<br><br> – « intelligent », celui qui peut assembler des choses, qui a perspicacité et compréhension\n<br><br> – « prudent », celui qui a d'abord des perceptions rapides et correctes, de là, « discret, circonspect »</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n4 fois dans 4 versets de 4 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Luc (1)</li>\n<li>Actes (1)</li>\n<li>1 Corinthiens (1)</li>\n</ul>\n</td></tr>\n</table>","G4909":"<h1>suneudokeo</h1>\n<p>Strong n° 4909 <i>Prononciation [soon-yoo-dok-eh'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>se plaire avec les autres, donner son approbation pour être ensemble</li>\n<li>être bien au même moment avec, consentir, être d'accord\n<ol type=\"a\">\n<li>applaudir</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>συν·ευδοκέω-ῶ :<br>      1</b> donner son assentiment à, consentir à, <i>dat</i>. SPT. <i>1Macc. 1, 57 ;</i> NT. <i>Luc. 8, 1 ; 11, 48 ; abs</i>. DÉMAD. <i>p. 180 fin ;</i> POL. <i>7, 1, 3 ;</i> DS. <i>4, 24, etc. ; au pass</i>. être consenti <i>ou</i> approuvé, THÉAGÈS (STOB. <i>Fl. 1, 67</i>) ;<br><b>      2</b> s’accorder avec qqn, <i>gén</i>. NT. <i>Rom. 1, 32 ;</i><br><b><i>Moy.</i></b> <span>(<i>ao</i>. συνευδοκήθην)</span> <i>c. à l’act</i>. DS. <i>18, 49</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">συνευδοκεω - συνευδοκέω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n6 fois dans 6 versets de 4 livres bibliques (NT)\n<ul>\n<li>Luc (1)</li>\n<li>Actes (2)</li>\n<li>Romains (1)</li>\n<li>1 Corinthiens (2)</li>\n</ul>\n</td></tr>\n</table>","G4910":"<h1>suneuocheo</h1>\n<p>Strong n° 4910 <i>Prononciation [soon-yoo-o-kheh'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>s'amuser ensemble, recevoir</li>\n<li>festoyer, faire un festin somptueux avec</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>συν·ευωχέομαι-οῦμαι</b>, se régaler ensemble <i>ou</i> avec, <i>dat</i>. LUC. <i>V.H. 2, 15 ; Ep. sat. 36 ; Philopatr. 4 ;</i> JOS. <i>A.J. 1, 3, 5 ; 4, 8, 7 ; abs</i>. ARSTT. <i>Eud. 7, 12, 14 ;</i> LUC. <i>Ic. 28 ;</i> POSIDON. (ATH. <i>152</i> b).\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">συνευωχεω - συνευωχέομαι</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>2 Pierre (1)</li>\n<li>Jude (1)</li>\n</ul>\n</td></tr>\n</table>","G4911":"<h1>sunephistemi</h1>\n<p>Strong n° 4911 <i>Prononciation [soon-ef-is'-tay-mee]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>placer par dessus ou désigner ensemble</li>\n<li>s'élever ensemble\n<ol type=\"a\">\n<li>contre quelqu'un</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>συν·εφίστημι</b> <span>(<i>f</i>. -επιστήσω, <i>ao</i>. -επέστησα, <i>etc</i>.)</span><br><b>   I <i>tr. :</i><br>      1</b> mettre en avant un groupe (d’hommes), un corps (d’éclaireurs) <i>acc</i>. DS. <i>17, 84 ;</i><br><b>      2</b> <i>fig</i>. fixer ensemble l’attention de, rendre également attentif : τινά, POL. <i>10, 41, 6,</i> qqn ; τινὰ ἐπί τι, POL. <i>11, 19, 2 ; ou</i> περί τινος, POL. <i>3, 59, 6,</i> à qqe ch. ;<br><b>   II <i>intr. :</i><br>      1</b> fixer ensemble son attention sur, être également attentif : τινί, POL. <i>9, 2, 7 ;</i> ἐπί τι, POL. <i>3, 9, 4,</i> à qqe ch. ;<br><b>      2</b> (<i>à l’ao.2</i> συνεπέστην <i>et au pf</i>. συνεφέστηκα) être ensemble <i>ou</i> en même temps préposé à, THC. <i>2, 75, 3 ;</i> se soulever avec, <i>dat</i>. DIOSC. <i>Ther. præf. ; avec idée d’hostilité,</i> NT. <i>Ap. 16, 22</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">συνεφιστημι - συνεφίστημι</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G4912":"<h1>sunecho</h1>\n<p>Strong n° 4912 <i>Prononciation [soon-ekh'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>tenir ensemble\n<ol type=\"a\">\n<li>tout objet, de peur qu'il ne tombe en morceaux ou qu'il en tombe quelque chose</li>\n</ol>\n</li>\n<li>contenir ensemble avec contrainte, comprimer\n<ol type=\"a\">\n<li>presser ensemble avec la main</li>\n<li>se boucher les oreilles</li>\n<li>presser de chaque côté\n<ol>\n<li>d'une cité assiégée</li>\n<li>d'un détroit, qui force un navire dans un canal étroit</li>\n<li>d'un enclos à bétail, où les bêtes sont tenues de tous côtés, les mettant dans une position où elles ne peuvent bouger, et pour que le fermier puisse les soigner</li>\n</ol>\n</li>\n</ol>\n</li>\n<li>retenir complètement\n<ol type=\"a\">\n<li>détenir\n<ol>\n<li>d'un prisonnier</li>\n</ol>\n</li>\n<li>métaph.\n<ol>\n<li>être tenu, être entièrement occupé par un travail</li>\n<li>dans l'enseignement de la parole</li>\n<li>contraindre, opprimer, des maux qui tiennent quelqu'un et l'affligent</li>\n<li>être tenu avec, affligé par, souffrir de</li>\n<li>presser, forcer\n<ol type=\"a\">\n<li>de l'âme</li>\n</ol>\n</li>\n</ol>\n</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>συν·έχω</b>, <i>anc. att</i>. <b>ξυν·έχω</b> <span>(<i>f</i>. συνέξω, <i>ao.2</i> συνέσχον, <i>pf</i>. συνέσχηκα ; <i>pass. f</i>. συσχεθήσομαι <i>ou</i> συνέξομαι, <i>ao</i>. συνεσχέθην, <i>ao.2,</i> συνεσχόμην)</span><br><b>   I <i>tr.</i></b> tenir ensemble, <i>d’où :</i><br><b>      1</b> tenir attaché, retenir, soutenir, maintenir : τὰ ὀστᾶ, PLAT. <i>Phæd. 98</i> d, les os, <i>en parl. de la peau ;</i> ἅπαντα, PLAT. <i>Phæd. 99</i> c, soutenir tout, <i>càd</i>. le monde, <i>en parl. d’Atlas ;</i><br><b>      2</b> maintenir ensemble, tenir rassemblé : τινάς, AR. <i>Lys. 1265,</i> retenir qqes personnes dans l’amitié ; <i>au pass</i>. PLAT. <i>Tim. 43</i> e ; εἰς ἕν, PLAT. <i>Leg. 945</i> d, maintenir <i>ou</i> réunir en un tout ; σ. στράτευμα καὶ συναθροίζειν, XÉN. <i>An. 7, 2, 8,</i> retenir et rassembler une armée ; τὴν δύναμιν ἐν τῷ χάρακι, POL. <i>10, 39, 1,</i> contenir l’armée dans le retranchement ; <i>fig</i>. φόϐοις τὰ πλήθη, POL. <i>6, 56, 11,</i> contenir les foules par la crainte ;<br><b>      3</b> <i>p. suite,</i> conserver, sauvegarder : τὴν πόλιν, PLAT. <i>Rsp. 440</i> e ; τὴν πολιτείαν, DÉM. <i>700, 15,</i> l’État, le gouvernement ; τὰ πράγματα, DÉM. <i>154, 7 ;</i> POL. <i>6, 56, 7,</i> les affaires ; τὸν ὅλον κόσμον, XÉN. <i>Mem. 4, 3, 13,</i> l’univers entier ; <i>p. suite,</i> diriger : δύο σχολάς, STR. <i>650,</i> deux écoles ;<br><b>      4</b> tenir l’un avec l’autre, <i>d’où au pass</i>. se tenir uni l’un à l’autre, <i>en parl. des relalions sexuelles,</i> ARSTT. <i>H.A. 5, 2, 10, etc. ; fig</i>. σ. ἑαυτὸν ἔν τινι, PLUT. <i>Cleom. 34,</i> s’adonner à qqe ch. ;<br><b>      5</b> tenir serré, comprimer : τὼ μηρώ, AR. <i>Nub. 966,</i> serrer les jambes ; τὰ ὦτα αὐτῶν, NT. <i>Ap. 7, 57,</i> se boucher les oreilles ; τὸ πνεῦμα, PLUT. <i>M. 847</i> b, retenir son souffle ; <i>au pass</i>. être serré, pressé : αἰχμῇσι καὶ ἐγχειριδίοισι, HDT. <i>1, 214,</i> par les lances et les poignards ; <i>fig</i>. φροντίδι, EUR. <i>Her. 634,</i> être oppressé par un souci ; κακοῖς, AR. <i>Eccl. 1096,</i> être sous l’étreinte du malheur ; δίψῃ, THC. <i>2, 49,</i> être pressé par la soif ; ἀμηχανίᾳ, XÉN. <i>Œc. 1, 22,</i> être réduit à ne savoir que faire ; πόνῳ, THC. <i>3, 98,</i> être accablé de fatigue ; νοσήμασι, PLAT. <i>Gorg. 512</i> a, être accablé par les maladies ;<br><b>      6</b> avoir en soi, contenir : πᾶν σάκος, HÉS. <i>Sc. 315,</i> occuper toute la continuité, <i>càd</i>. tout le bord du bouclier, <i>en parl. de l’image de l’Océan ; au pass</i>. être renfermé : ἐν φρέατι, PLAT. <i>Theæt. 165</i> b, être enfoncé dans un puits ; <i>fig</i>. τὸ συνέχον, POL. <i>2, 13, 3 ; 4, 5, 5, etc</i>. ce qui contient en soi toute la question, le point principal ; τὰ συνέχοντα, POL. <i>6, 46, 6,</i> les points principaux ; τὸ σ. τῆς ἐκκλησίας, POL. <i>28, 4, 2,</i> le point principal de la délibération ; τὸ σ. τῆς σωτηρίας, POL. <i>10, 47, 11,</i> le remède principal, le grand remède ; <i>particul</i>. le point principal dans une démonstration juridique, RHÉT. <i>3, 456 W. ; 4, 140 W. ;</i> QUINT. <i>3, 11, 9 ;</i><br><b>   II <i>intr</i>.<br>      1</b> se tenir ensemble, se réunir : ἵνα ξυνέχουσι τένοντες, IL. <i>20, 478,</i> là où se réunissent les muscles ; <i>cf</i>. IL. <i>4, 133 ; 20, 415 ;</i> ARSTT. <i>H.A. 4, 5 ;</i><br><b>      2</b> être lié à, avoir rapport à, <i>avec</i> πρός <i>et l’acc</i>. SEXT. <i>P. 1, 145 ;</i><br><b>      3</b> <i>avec idée de temps,</i> continuer, durer, se prolonger, CHRYS.<br><span><b><span class=\"arrow\"></span></b> <i>Fut. moy</i>. συνέξομαι <i>au sens pass</i>. DÉM. <i>1484, 23 ; part. ao.2 moy</i>. συσχόμενος (<i>var</i>. συνεχόμενος) <i>au sens pass</i>. PLAT. <i>Theæt. 165</i> b.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">συνεχω - συνέχω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n12 fois dans 12 versets de 5 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Luc (6)</li>\n<li>Actes (3)</li>\n<li>2 Corinthiens (1)</li>\n<li>Philippiens (1)</li>\n</ul>\n</td></tr>\n</table>","G4913":"<h1>sunedomai</h1>\n<p>Strong n° 4913 <i>Prononciation [soon-ay'-dom-ahee]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>se réjouir ensemble avec (un ou plusieurs autres)</li>\n<li>dans le N.T. utilisé une fois pour se réjouir en soi-même ou intérieurement</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>συν·ήδομαι</b> <span>(<i>f</i>. συνησθήσομαι, <i>ao</i>. συνήσθην)</span><br><b>      1</b> se réjouir avec : τινι, EUR. <i>Ion 728 ;</i> XÉN. <i>Cyr. 4, 1, 7 ; 8, 7, 27 ;</i> DÉM. <i>579, 19,</i> qqn ; <i>avec</i> ὅτι, XÉN. <i>An. 7, 8, 1 ; ou avec un part</i>. HDT. <i>3, 36,</i> de ce que, <i>etc. ;</i> τινὶ συνήδεσθαι ἐπί τινι, XÉN. <i>Cyr. 8, 2, 2, etc</i>. se réjouir de qqe ch. avec qqn ; οὐ συνήδομαί σοι ταῖς ὁδοῖς, SOPH. <i>O.C. 1397,</i> je déplore avec toi ton voyage ; <i>opp. à</i> συνάχθεσθαι, XÉN. <i>Cyr. 1, 6, 24 ; à</i> συναλγεῖν, ARSTT. <i>Nic. 9, 4, 5 ;</i><br><b>      2</b> féliciter : τινί τινος, APP. <i>Mac. 15,</i> qqn de qqe ch. ; τινι ὅτι, XÉN. <i>An. 5, 5, 8,</i> qqn de ce que, <i>etc</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">συνηδομαι - συνήδομαι</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Romains (1)</li>\n</ul>\n</td></tr>\n</table>","G4914":"<h1>sunetheia</h1>\n<p>Strong n° 4914 <i>Prononciation [soon-ay'-thi-ah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>relations, rapport (avec quelqu'un), intimité</li>\n<li>coutume</li>\n<li>ce que l'on est accoutumé de faire, une habitude, usage, us</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>συνήθεια</b>, <i>anc. att</i>. <b>ξυνήθεια, ας (ἡ) :<br>   I</b> habitudes en commun, vie en commun, ARSTT. <i>H.A. 6, 9, 4 ;</i> EL. <i>N.A. 2, 31 ; p. suite :</i><br><b>      1</b> relations habituelles, commerce, société : τινος, ISOCR. <i>2</i> a ; ESCHN. <i>48, 27 ;</i> μετά τινος, ESCHN. <i>31, 18 ;</i> πρός τινα, ISOCR. <i>2 a et b</i>, avec qqn ; <i>joint à</i> φιλία, ARSTT. <i>G.A. 3, 2, 15 ; au plur</i>. ARSTT. <i>Pol. 6, 4, 19 ;</i><br><b>      2</b> <i>particul</i>. commerce intime, relations sexuelles, XÉN. <i>Cyr. 6, 1, 31, etc. ; en parl. d’animaux,</i> ARSTT. <i>H.A. 6, 21, 6 ;</i><br><b>   II</b> habitude, <i>particul. :</i><br><b>      1</b> manière d’être habituelle, HH. <i>Merc. 485 ;</i> PLAT. <i>Rsp. 516</i> a ; DÉM. <i>342, 11, etc. ;</i> ὑπὸ συνηθείας, PLAT. <i>Theæt. 157</i> b, par habitude ; διὰ συνήθειαν, PLAT. <i>Soph. 248</i> b, <i>ou</i> κατὰ συνήθειαν, PLAT. <i>Rsp. 620</i> a, selon l’habitude ; παρὰ συνήθειαν, PLAT. <i>Leg. 655</i> e, contrairement à l’usage ; συνήθειαν ἔχειν τινί, POL. <i>40, 10, 2,</i> avoir l’habitude de qqe ch. ; σ. κτᾶσθαι πρός τι, PLUT. <i>M. 791</i> a, acquérir l’habitude de qqe ch. ;<br><b>      2</b> usage courant d’un mot, d’une locution, PLAT. <i>Theæt. 168</i> b ; ESCHN. <i>23, 37 ; particul</i>. dialecte commun <i>ou</i> vulgaire, PLUT. <i>M. 22 c et f, 113</i> a, <i>etc. ;</i><br><b>      3</b> <i>au plur. c</i>. καταμήνια, ARSTT. <i>H.A. 6, 21</i>.<br><span><b>Étym</b>. συνήθης.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">συνηθεια - συνήθεια</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Jean (1)</li>\n<li>1 Corinthiens (1)</li>\n</ul>\n</td></tr>\n</table>","G4915":"<h1>sunelikiotes</h1>\n<p>Strong n° 4915 <i>Prononciation [soon-ay-lik-ee-o'-tace]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>quelqu'un du même âge, égal en âge</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>συν·ηλικιώτης, ου (ὁ)</b> <span>[ῐκ]</span> <i>c</i>. συνῆλιξ DH. <i>10, 49 ;</i> DS. <i>1, 53 ;</i> ALCIPHR. <i>1, 12 ;</i> NT. <i>Gal. 1, 14</i>.<br><span><b>Étym</b>. σ. ἡλικιώτης.</span><br><br>\n<b>συν·ῆλιξ</b>, <i>anc. att</i>. <b>ξυν·ῆλιξ, ικος</b> (ὁ, ἡ, τὸ) <span>[ῐκ]</span> de même âge, <i>subst</i>. compagnon, camarade de, <i>dat</i>. ESCHL. <i>Pers. 784 ; abs</i>. EUP. <i>2-1, 501 Meineke ; fém</i>. ANTH. <i>7, 711 ; neutre plur</i>. ξυνήλικα, SPT. <i>Dan. 1, 10</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Dor</i>. συνᾶλιξ, ANTH. <i>l. c</i>.<br><span><b>Étym</b>. σ. ἧλιξ.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">συνηλικιωτης - συνηλικιώτης</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Galates (1)</li>\n</ul>\n</td></tr>\n</table>","G4916":"<h1>sunthapto</h1>\n<p>Strong n° 4916 <i>Prononciation [soon-thap'-to]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>enterrer, ensevelir ensemble</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>συν·θάπτω</b>, ensevelir avec : τινά τινι, EUR. <i>Alc. 149,</i> une personne avec une autre ; τινά, ESCHL. <i>Sept. 1027 ;</i> SOPH. <i>Aj. 1378, etc</i>. ensevelir qqn avec (d’autres) ; <i>au pass</i>. HDT. <i>5, 5 ;</i> THC. <i>1, 8, etc</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">συνθαπτω - συνθάπτω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Romains (1)</li>\n<li>Colossiens (1)</li>\n</ul>\n</td></tr>\n</table>","G4917":"<h1>sunthlao</h1>\n<p>Strong n° 4917 <i>Prononciation [soon-thlah'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>casser en morceaux, briser, fracasser</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>συν·θλάω-ῶ</b>, briser <i>ou</i> broyer ensemble, Ps.-ERATOSTH. <i>Cat. 11 ;</i> DS. <i>1, 57 ; au pass</i>. ALEX. (<i>Com. fr. 3, 510</i>) ; NT. <i>Matth. 21, 44, etc</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">συνθλαω - συνθλάω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G4918":"<h1>sunthlibo</h1>\n<p>Strong n° 4918 <i>Prononciation [soon-thlee'-bo]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>presser ensemble, presser de tous côtés, serrer de près</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>συν·θλίϐω</b> <span>[ῑ]</span> presser ensemble, comprimer, ARSTT. <i>Rhet. 1, 5, 12, etc. ; au pass</i>. PLAT. <i>Tim. 91</i> e ; ARSTT. <i>H.A. 5, 28, 2, etc</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">συνθλιβω - συνθλίβω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 1 livre biblique (NT)\n<ul>\n<li>Marc (2)</li>\n</ul>\n</td></tr>\n</table>","G4919":"<h1>sunthrupto</h1>\n<p>Strong n° 4919 <i>Prononciation [soon-throop'-to]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>casser en morceaux, écraser</li>\n<li>métaph.\n<ol type=\"a\">\n<li>briser le cœur</li>\n<li>priver de force et de courage, décourager, rendre incapable d'endurer des épreuves</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>συν·θρύπτω</b>, briser, amollir, énerver, NT. <i>Ap. 21, 13</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">συνθρυπτω - συνθρύπτω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G4920":"<h1>suniemi</h1>\n<p>Strong n° 4920 <i>Prononciation [soon-ee'-ay-mee]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>mettre ou amener ensemble\n<ol type=\"a\">\n<li>dans un sens hostile : de combattants</li>\n</ol>\n</li>\n<li>adapter la perception avec la chose perçue\n<ol type=\"a\">\n<li>disposer ou joindre ensemble dans l'esprit\n<ol>\n<li>comprendre : l'homme de la compréhension</li>\n<li>idiome pour : un homme bon et juste (ayant la connaissance de ces choses qui appartiennent au salut)</li>\n</ol>\n</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>συν·ίημι</b>, <i>ion. et anc. att</i>. <b>ξυν·ίημι</b> <span>(<i>impft</i>. συνίην <i>et</i> συνίειν, <i>f</i>. συνήσω, <i>ao</i>. συνῆκα, <i>ao.2</i> σύνην, <i>pf</i>. συνεῖκα)</span> <i>litt</i>. envoyer <i>ou</i> lancer ensemble <i>ou</i> l’un contre l’autre, <i>d’où :</i><br><b>   I</b> lancer à la fois : ἀμφοτέρῃς ἕνα ξ. ὀϊστόν, MUS. GRAMM. <i>18,</i> lancer un seul trait sur les deux ensemble ;<br><b>   II</b> mettre aux prises : τινὰς μάχεσθαι, IL. <i>1, 8 ; 7, 210,</i> des hommes pour combattre ;<br><b>   III</b> rapprocher de : φθέγγονθ' ὥστε θεοῖσι ξυνιέμεν, HÉS. <i>Th. 831,</i> ses bouches résonnaient de manière à faire parvenir le son jusqu’aux dieux, <i>en parl. de Typhée ;</i><br><b>   IV</b> rapprocher par la pensée, <i>càd. :</i><br><b>      1</b> faire attention à, écouter, <i>abs</i>. IL. <i>15, 442 ;</i> OD. <i>1, 271 ; avec un acc. de ch. :</i> τινὸς ὄπα, IL. <i>2, 182 ;</i> τινὸς ἔπος, OD. <i>6, 289,</i> écouter la voix <i>ou</i> la parole de qqn ; <i>avec un gén. de pers. :</i> τινός, IL. <i>2, 26 ;</i> ORACL. (HDT. <i>1, 47</i>) écouter qqn ; <i>rar. avec un gén. de chose,</i> IL. <i>1, 273 ;</i><br><b>      2</b> comprendre, se rendre compte de, <i>avec un gén. de pers. :</i> ἀλλήλων, HDT. <i>4, 114 ;</i> THC. <i>1, 3, etc</i>. se comprendre les uns les autres ; <i>avec un acc</i>. PD. <i>P. 3, 141 ;</i> HDT. <i>3, 46 ;</i> ESCHL. <i>Pers. 361, Ch. 887, etc. ;</i> SOPH. <i>El. 1479 ;</i> XÉN. <i>An. 7, 6, 8, etc. ; abs</i>. οἱ ξυνιέντες, THGN. <i>904,</i> les hommes intelligents ; <i>dans le dialogue :</i> συνίης ; DIPH. (<i>Com. fr. 4, 389</i>) comprends-tu ? <i>avec une conjonct. :</i> ξυνίημ' ὅτι βούλει, AR. <i>Av. 946,</i> je comprends que tu veux ; <i>avec un part. :</i> οὐ συνῆκα γεγενημένος, LUC. <i>D. deor. 2, 1,</i> je ne m’aperçus pas que j’étais devenu, <i>etc. ; cf</i>. PLUT. <i>M. 231</i> d, <i>etc. ;</i><br><b><i>Moy</i>. συνίεμαι</b> <span>(<i>f</i>. συνήσομαι, <i>ao</i>. συνείμην, <i>etc</i>.)</span> s’entendre, s’accorder : ἀμφὶ γάμῳ, IL. <i>13, 381,</i> au sujet d’un mariage.<br><span><b><span class=\"arrow\"></span></b> <i>Act. prés. impér</i>. ξυνίει, OD. <i>8, 241, etc., et</i> ξύνιε, THGN. <i>1240</i> (ξυνίει <i>Bgk) ; inf</i>. ξυνιέμεν <span>[ῑ]</span> HÉS. <i>Th. 831 et</i> ξυνιεῖν, THGN. <i>565 (régul</i>. συνιέναι, PLAT. <i>Prot. 339) Impf. 3 sg</i>. συνίει, XÉN. <i>An. 7, 6, 8, et</i> συνίη, CÉB. <i>3, 2, 3 ; 3 pl. épq</i>. ξύνιεν, IL. <i>1, 273. Ao. poét</i>. ἐσυνῆκα, ALC. <i>132 et</i> ἐξυνῆκα, ANACR. <i>146 ; épq</i>. ξυνέηκα, IL. <i>2, 182 ;</i> OD. <i>18, 34 ; 1 pl. dor</i>. συνήκαμες, PLUT. <i>M. 232, etc. Ao.2 impér</i>. ξύνες, IL. <i>2, 26, 63 ; 24, 133 ;</i> PD. <i>fr. 82 Bgk, etc. ; inf. poét</i>. συνέμεν, PD. <i>P. 3, 80 (régul</i>. συνεῖναι, PLAT. <i>Crat. 414</i> d). <i>Moy. 3 sg. ao.2</i> ξύνετο, OD. <i>4, 76 ; sbj. 1 pl</i>. συνώμεθα, IL. <i>13, 381</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">συνιημι - συνίημι</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Synonymes</big></td></tr>\n<tr><td> – une connaissance fondée sur une expérience personnelle\n<br><br> – voir avec les yeux de l'esprit, donc une pure et claire perception mentale\n<br><br> – une connaissance obtenue par la proximité de la chose connue, notre compréhension\n<br><br> – implique une perspicacité naturelle, une connaissance obtenue à travers les cinq sens</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n26 fois dans 25 versets de 7 livres bibliques (NT)\n<ul>\n<li>Matthieu (9)</li>\n<li>Marc (5)</li>\n<li>Luc (4)</li>\n<li>Actes (4)</li>\n<li>Romains (2)</li>\n<li>2 Corinthiens (1)</li>\n<li>Ephésiens (1)</li>\n</ul>\n</td></tr>\n</table>","G4921":"<h1>sunistao</h1>\n<p>Strong n° 4921 <i>Prononciation [soon-is-tah'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>placer ensemble, mettre au même lieu, amener ensemble\n<ol type=\"a\">\n<li>tenir, retenir avec (ou proche)</li>\n</ol>\n</li>\n<li>retenir quelqu'un avec un autre\n<ol type=\"a\">\n<li>en le présentant, ou par introduction</li>\n<li>comprendre</li>\n</ol>\n</li>\n<li>mettre ensemble par composition ou combinaison, enseigner en combinant et comparant\n<ol type=\"a\">\n<li>montrer, prouver, établir, exposer</li>\n</ol>\n</li>\n<li>rassembler, regrouper des parties dans un tout\n<ol type=\"a\">\n<li>être composé de, consistant en</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>συν·ίστημι</b>, <i>anc. att</i>. <b>ξυν·ίστημι :<br>A</b> <i>tr. (aux temps suiv. : prés., impf</i>. συνίστην, <i>fut</i>. συστήσω, <i>ao.1</i> συνέστησα, <i>pf</i>. συνέστακα <span>[τᾰ]</span>) placer debout avec <i>ou</i> en même temps, <i>d’où :</i><br><b>   I</b> placer ensemble, réunir, rassembler : τὰς ἄρκυς καὶ τὰ δίκτυα, XÉN. <i>Cyn. 6, 12,</i> dresser, tendre les rets et les filets ; τοὺς ἐκ τῆς τροπῆς σκεδασθέντας σ. DH. <i>8, 18,</i> rallier les fuyards dispersés ;<br><b>   II</b> constituer, instituer : σ. τισὶν ἡγεμόνα, POL. <i>2, 24, 6,</i> donner un chef à une troupe ; στρατιώτας τινί, DS. <i>17, 64,</i> mettre des soldats à la disposition de qqn ; σ. ἀντίπαλον ἑαυτῷ, XÉN. <i>Cyr. 6, 1, 26,</i> (Cyrus comprenant que son adversaire était parti afin de) réunir des troupes contre lui ; <i>au pass</i>. συσταθεὶς συνήγορος, PLUT. <i>M. 840</i> e, ayant été institué comme défenseur (dans un procès) ;<br><b>   III</b> rassembler, réunir, associer pour une entreprise commune (combat, guerre, conjuration) : τινὰς ἐπί τινι, HDT. <i>6, 74 ; 3, 84 ;</i> τινὰς ἐπί τινα, PLUT. <i>Cim. 1, 6 ;</i> PAUS. <i>2, 9, 3,</i> coaliser un peuple, un parti contre qqn ; τὰς πόλεις πρὸς ἀλλήλας, XÉN. <i>Hell. 3, 5, 2,</i> coaliser les villes les unes avec les autres (contre les Lacédémoniens) ; <i>avec le rég. du but :</i> τινὰς ἐπὶ πρᾶξιν, PLUT. <i>Lyc. 5 ;</i> ἐς ξυνωμοσίαν, THC. <i>6, 16 ; 8, 48,</i> rassembler des peuples, qqes personnes pour une entreprise, pour une conjuration ; Ἀσίην πᾶσαν ἑωυτῷ, HDT. <i>1, 103,</i> rassembler (autour de soi) toute l’Asie, soumettre toute l’Asie ;<br><b>   IV</b> réunir à, mettre en relation : τινί τινα, XÉN. <i>Conv. 5, 63 ; Œc. 3, 14 ; Mem. 1, 6, 14 ;</i> PLAT. <i>Charm. 155</i> b, <i>Theag. 122</i> a, <i>etc</i>. mettre une personne en relation avec une autre, la lui recommander ; <i>au pass</i>. συνεστάθη Κύρῳ, XÉN. <i>An. 3, 18,</i> il fut présenté <i>ou</i> recommandé à Cyrus ; <i>cf</i>. XÉN. <i>An. 5, 9, 23 ;</i> DÉM. <i>1241, 7, etc. ; t. de droit</i> συνιστάναι τινά, DÉM. <i>1029, 26 ; 1032, 27,</i> présenter à un banquier le mandataire chargé de recevoir un paiement ;<br><b>   V</b> composer, réunir en un tout par l’assemblage des parties, <i>d’où</i> faire naître, créer, produire : ζῷον ἔμψυχον, PLAT. <i>Tim. 91</i> a, un être animé ; ὀστοῦν, PLAT. <i>Tim. 73</i> e, un os ; τὴν ὀλιγαρχίαν, THC. <i>8, 48,</i> constituer l’oligarchie ; ἐκ δημοκρατίας καὶ μοναρχίας τὴν πολιτείαν, ARSTT. <i>Pol. 2, 3, 13,</i> constituer le gouvernement d’un mélange de démocratie et de monarchie ; μαντικήν, HDT. <i>2, 49,</i> instituer l’art divinatoire ; μύθους, ARSTT. <i>Poet. 17, 1,</i> composer des fables ; σ. ἐπί τινι θάνατον, HDT. <i>3, 71,</i> comploter la mort de qqn ; πόλεμον ἐπί τινα, DÉM. <i>191, 13,</i> provoquer une guerre contre qqn ;<br><b>   VI</b> rassembler, resserrer, <i>d’où :</i><br><b>      1</b> contracter, plisser, rider : τὸ πρόσωπον, PLUT. <i>M. 152</i> b, <i>etc</i>. le visage ;<br><b>      2</b> faire coaguler : τὸ γάλα, POL. <i>1, 25, 1,</i> le lait ;<br><b>      3</b> rendre compact, solide : τὸ σῶμα, HPC. <i>1245, 8,</i> le corps ; ἴχνη, XÉN. <i>Cyn. 5, 3,</i> donner de la consistance à des traces de pas (du gibier) ;<br><b>      4</b> <i>fig</i>. donner de la consistance, <i>d’où :</i> σ. τὰς τιμὰς τοῦ σίτου, DÉM. <i>1285, 6,</i> élever <i>ou</i> hausser le prix du blé ;<br><b>   VII</b> produire, prouver, montrer : εὔνοιαν, POL. <i>4, 5, 6,</i> de la bienveillance ; θεοῦ δικαιοσύνην, NT. <i>Rom. 3, 5,</i> montrer la justice de Dieu ; <i>suivi de</i> ὅτι, POL. <i>3, 108, 4 ; avec une propos. inf</i>. DS. <i>1, 96 ; 13, 91 ; 14, 45 ;</i><br><b>B</b> <i>intr. (aux temps suiv. : ao.2</i> συνέστην, <i>pf</i>. συνέστηκα, <i>pl.q.pf</i>. συνειστήκειν <i>et au moy</i>.) :<br><b>   I</b> se tenir ensemble, XÉN. <i>Cyn. 6, 16 ; Cyr. 2, 1, 29 ;</i> ἁθρόοι συστάντες, XÉN. <i>An. 7, 3, 47 ; ou</i> συνεστῶτες, PLAT. <i>Lys. 203</i> a, se tenant réunis en masse ;<br><b>   II</b> <i>avec idée d’hostilité,</i> se rapprocher, se rencontrer, en venir aux mains : πολέμοιο συνεσταότος, IL. <i>14, 96,</i> lorsque le combat fut engagé (<i>seul ex. de ce mot dans Hom.) ; cf</i>. THC. <i>1, 15 ;</i> DÉM. <i>230, 27 ;</i> POL. <i>3, 2, 1 ;</i> PLUT. <i>Tim. 37 ;</i> μάχης συνεστεώσης, HDT. <i>1, 74,</i> le combat s’étant engagé ; κρατερὰ μάχη συνέστη, PLUT. <i>Cim. 13,</i> un combat acharné s’engagea ; <i>fig</i>. συνίστασθαί τινι, s’engager dans un combat avec qqn, se quereller, se disputer : συνεστηκότων τῶν στρατηγῶν, HDT. <i>8, 79,</i> tandis que les généraux se querellaient ; γνῶμαι συνέστασαν, HDT. <i>1, 208 ; 7, 142,</i> les opinions se contredisaient, étaient opposées ; <i>avec le dat</i>. σ. τινί, HDT. <i>6, 108,</i> lutter contre qqn ; σ. ταύτῃ τῇ γνώμῃ, HDT. <i>4, 132,</i> combattre cette opinion (cette interprétation) ; <i>p. suite,</i> tenir ferme, tenir bon, HDT. <i>1, 214 ; 6, 29 ;</i> THC. <i>4, 96 ;</i> POL. <i>14, 8, 9, etc. ; fig</i>. λιμῷ σ. HDT. <i>7, 170,</i> lutter contre la faim ; σ. πόνῳ, HDT. <i>8, 74 ;</i> λιμῷ καὶ καμάτῳ, HDT. <i>9, 89,</i> lutter contre une épreuve, contre la faim et la fatigue ; <i>cf</i>. SOPH. <i>O.C. 514 ;</i><br><b>   III</b> être engagé <i>ou</i> s’engager dans une liaison amicale, entrer en relation avec, <i>d’où :</i><br><b>      1</b> être lié par mariage, SOPH. <i>Tr. 28 ;</i><br><b>      2</b> assister qqn. <i>dat</i>. M. TYR. <i>10, 8 ;</i><br><b>      3</b> être attaché comme ami, <i>ou</i> disciple, <i>ou</i> partisan à, <i>dat</i>. ISOCR. <i>Ep. 4, 8 ;</i><br><b>      4</b> conspirer avec, <i>dat</i>. THC. <i>2, 88 ; 3, 70, etc. ;</i> οὐδὲν ἐν τῇ πόλει ξυνιστάμενον, AR. <i>Eq. 863,</i> aucune conjuration dans la ville ; <i>d’où en gén</i>. se concerter : οἱ ξυνεστῶτες, THC. <i>8, 66,</i> les conjurés ; σ. μετά τινος, DÉM. <i>917, 13,</i> se concerter avec qqn ; <i>abs</i>. XÉN. <i>Hell. 2, 1, 1 ; 4, 4, 1 ;</i> σ. πρός τινα, THC. <i>1, 1 ;</i> XÉN. <i>Hell. 4, 2, 1 ;</i> πρὸς τὰς μεγίστας πόλεις, THC. <i>1, 15,</i> s’unir à qqn, aux plus grands États ;<br><b>   IV</b> se constituer, <i>d’où :</i><br><b>      1</b> se former, s’organiser par un rassemblement : σύλλογοι ἐγένοντο καὶ κύκλοι συνίσταντο, XÉN. <i>An. 5, 7, 2,</i> il se formait des rassemblements et des groupes s’organisaient ;<br><b>      2</b> se former par la réunion de plusieurs parties, <i>avec</i> ἐκ <i>et le gén</i>. PLAT. <i>Tim. 54</i> c ; ARSTT. <i>Nic. 6, 7, 4 ;</i> PLUT. <i>Num. 17 ; au pf</i>. être formé, constitué : ἐξ οἰκιῶν, XÉN. <i>Mem. 3, 6, 14,</i> de maisons, <i>en parl. d’une ville ;</i><br><b>      3</b> <i>p. suite,</i> se former, se constituer, naître, <i>au propre,</i> ARSTT. <i>H.A. 5, 31 ; 6, 10 ;</i> ξυνεστὼς στρατός, EUR. <i>I.A. 87,</i> armée rassemblée, prête à partir ; <i>en parl. de plantes,</i> TH. <i>C.P. 4, 4, 10 ; d’arbres,</i> TH. <i>C.P. 2, 1, 5 ; de fruits,</i> TH. <i>H.P. 3, 18, 6, etc. ; fig</i>. συνιστάμενον καὶ φυόμενον κακόν, DÉM. <i>245, 24,</i> mal qui se forme et se développe ;<br><b>      4</b> <i>p. ext</i>. prendre de la consistance, être consistant, ferme, solide : σώματα συνεστηκότα, XÉN. <i>Cyn. 7, 8,</i> corps solidement constitués ; <i>p. anal</i>. συνεστῶτες εὖ μῦθοι, ARSTT. <i>Poet. 7, 7,</i> fables bien composées ;<br><b>      5</b> <i>p. suite,</i> se maintenir, être durable : τοῦτο συνεστήκεε μέχρι οὗ, HDT. <i>7, 225,</i> cette situation se prolongea jusqu’au moment où, <i>etc. ;</i> συνεστηκὸς στράτευμα, DÉM. <i>93 fin,</i> armée permanente ; <i>cf</i>. DÉM. <i>92, 23 ; 101, 8 ;</i> στρατόπεδα συνεστῶτα, HDN <i>6, 56,</i> camps permanents ; ἱππικὸν συνεστηκός, XÉN. <i>An. 7, 6, 26,</i> corps de cavalerie formé ; οἱ ἔτι συνεστῶτες, PLUT. <i>Sert. 20,</i> ceux qui tiennent encore bon ;<br><b>   V</b> se contracter, se resserrer ; <i>en parl. de liquides,</i> se figer, se coaguler : συνίσταται τὸ αἷμα, ARSTT. <i>H.A. 3, 6,</i> le sang se coagule ; <i>en gén</i>. συνεστηκυῖα χιών, POL. <i>3, 55, 2,</i> neige devenue solide <i>ou</i> dure ; κοιλίη συνίσταται, HPC. <i>267, 3,</i> le ventre se resserre ; τοῦ ἀέρος συνισταμένου, PLUT. <i>Ant. 40,</i> lorsque le temps devint froid ; <i>fig</i>. τοῦ σκυθρωποῦ καὶ ξυνεστῶτος φρενῶν, EUR. <i>Alc. 797,</i> de l’âme sombre et serrée ;<br><b><i>Moy</i>. συνίσταμαι</b> <span>(<i>f</i>. συστήσομαι, <i>ao</i>. συνεστησάμην)</span><br><b>   I <i>tr. :</i><br>      1</b> constituer pour soi, former <i>ou</i> organiser pour soi : σφηκῶνας, ARSTT. <i>H.A. 9, 41,</i> se fabriquer des ruches, <i>en parl. des abeilles ;</i> πόλιν, PLAT. <i>Phædr. 269</i> c, se bâtir une ville ; δυναστείαν, POL. <i>2, 13, 3,</i> fonder sa puissance ; βουλήν, PLUT. <i>Sol. 19,</i> instituer un sénat ; ζῷα, LUC. <i>Prom. 12,</i> créer des animaux ; ἄνθρωπον, LUC. <i>Herm. 20,</i> créer un homme ; ἑορτήν, APD. <i>3, 14, 6,</i> instituer une fête ; ναυτικὰς δυνάμεις, POL. <i>1, 25, 5,</i> se pourvoir de forces navales ; μισθοφόρους, POL. <i>4, 60, 5,</i> se procurer des mercenaires ;<br><b>      2</b> <i>t. de math</i>. construire (une figure) EUCL. <i>Elem. 1, 1, 7 ;</i><br><b>      3</b> entreprendre : πόλεμον, ISOCR. <i>217</i> e, une guerre ; μάχην, APD. <i>2, 5, 10,</i> engager un combat ; πολιορκίαν, POL. <i>1, 30, 5,</i> entreprendre un siège ; κίνδυνον, POL. <i>3, 106, 4 ;</i> DS. <i>1, 18,</i> affronter un danger ;<br><b>   II</b> <i>intr. (v. ci-dessus</i>).<br><span><b><span class=\"arrow\"></span></b> <i>Pf</i>. συνέστακα <span>[τᾰ]</span> <i>au sens trans</i>. SEXT. <i>M. 7, 109 ;</i> JAMBL. <i>V. Pyth. 261 ;</i> ANTH. <i>11, 139 ; pf. part. att</i>. συνεστώς, ῶσα, ώς <i>ou</i> ός, PLAT. <i>Tim. 56</i> b ; <i>ion</i>. συνεστεώς, εῶσα, εώς, HDT. <i>1, 74, etc. ; épq. gén. sg. masc</i>. συνεσταότος, IL. <i>14, 96</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">συνισταω - συνίστημι</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n16 fois dans 15 versets de 6 livres bibliques (NT)\n<ul>\n<li>Luc (1)</li>\n<li>Romains (3)</li>\n<li>2 Corinthiens (9)</li>\n<li>Galates (1)</li>\n<li>Colossiens (1)</li>\n<li>2 Pierre (1)</li>\n</ul>\n</td></tr>\n</table>","G4922":"<h1>sunodeuo</h1>\n<p>Strong n° 4922 <i>Prononciation [soon-od-yoo'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>voyager avec, voyager en compagnie avec, accompagner, faire route avec</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>συν·οδεύω :<br>      1</b> faire route avec, <i>dat</i>. PLUT. <i>Pomp. 40, M. 609</i> d, <i>etc. ;</i> LUC. <i>Per. 24 ; abs</i>. PLUT. <i>Ant. 13 ;</i><br><b>      2</b> être en conjonction (<i>en parl. du soleil, de la lune et de la terre</i>) PLUT. <i>M. 891</i> f ; CLÉOM. <i>Cycl. th. 1, p. 23 ; 2, p. 116 ;</i> MAN. <i>5, 62, 111, 274 ;</i><br><b>      3</b> <i>t. de gr</i>. s’accorder avec, DYSC. <i>Synt. 54, etc</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">συνοδευω - συνοδεύω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G4923":"<h1>sunodia</h1>\n<p>Strong n° 4923 <i>Prononciation [soon-od-ee'-ah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>un voyage en compagnie\n<ol type=\"a\">\n<li>d'une compagnie de voyageurs, associés dans un voyage, une caravane</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>συνοδία, ας (ἡ) :<br>      1</b> voyage fait de compagnie, CIC. <i>Att. 10, 7, 2 ;</i> PLUT. <i>M. 48</i> a ; <i>p. ext</i>. compagnie, société, fréquentation, MÉN. <i>Monost. 24 ;</i> PLUT. <i>Galb. 20 ;</i><br><b>      2</b> société de voyageurs, caravane, STR. <i>204, 528 ;</i> NT. <i>Luc. 2, 44 ; p. ext</i>. famille, SPT. <i>Neh. 7, 5, etc</i>.<br><span><b>Étym</b>. σύνοδος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">συνοδια - συνοδία</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G4924":"<h1>sunoikeo</h1>\n<p>Strong n° 4924 <i>Prononciation [soon-oy-keh'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>demeurer ensemble, cohabiter, vivre avec\n<ol type=\"a\">\n<li>d'une association domestique</li>\n<li>des relations entre maris et épouses</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>συν·οικέω</b>, <i>anc. att</i>. <b>ξυν·οικέω-ῶ :<br>   I <i>intr. :</i><br>      1</b> habiter ensemble <i>ou</i> avec, HOM. <i>Ep. 15, 15 ;</i> τινι, ESCHL. <i>Ch. 909 ;</i> SOPH. <i>Tr. 545, etc. ;</i> μετά τινος, PLUT. <i>Rom. 9,</i> vivre avec qqn ; <i>en parl. de peuples,</i> vivre avec, former une communauté avec, <i>dat</i>. HDT. <i>4, 148 ; abs</i>. THC. <i>2, 68 ; 6, 63, etc. ;</i><br><b>      2</b> cohabiter, être marié avec, vivre avec (<i>une femme,</i> HDT. <i>1, 91, 196 ; un homme,</i> HDT. <i>1, 37, 108) ; abs</i>. HDT. <i>1, 93, etc. ; fig</i>. σ. ἡδοναῖς, PLAT. <i>Rsp. 587</i> c, vivre dans le plaisir ; <i>avec un suj. de chose,</i> vivre avec qqn, être habituel à qqn, <i>en parl. de la richesse, de la pauvreté,</i> PLAT. <i>Leg. 679</i> b, <i>etc. ;</i><br><b>   II <i>tr.</i></b> coloniser avec : Κυρηναίοισι Λιϐύην, HDT. <i>4, 159,</i> coloniser la Libye avec les Cyrénéens ; <i>au pass</i>. συνοικουμένη χώρα, XÉN. <i>Œc. 4, 8,</i> région (partie d’un État) très peuplée ; <i>en parl. d’une région du ciel couverte de constellations,</i> MAN. <i>5, 165</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">συνοικεω - συνοικέω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>1 Pierre (1)</li>\n</ul>\n</td></tr>\n</table>","G4925":"<h1>sunoikodomeo</h1>\n<p>Strong n° 4925 <i>Prononciation [soon-oy-kod-om-eh'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>bâtir ensemble\n<ol type=\"a\">\n<li>construire ensemble ou avec d'autres</li>\n<li>mettre ensemble ou construire en bâtissant, en utilisant plusieurs choses bâtir un tout\n<ol>\n<li>du corps humain</li>\n</ol>\n</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>συν·οικοδομέω</b>, <i>anc. att</i>. <b>ξυν·οικοδομέω-ῶ</b> (<i>pf. pass</i>. συνῳκοδόμημαι) :<br><b>      1</b> bâtir ensemble : ἐκ πολλῶν ἓν οἰκητήριον PLUT. <i>Thes. c. Rom. 4,</i> de plusieurs constructions n’en faire qu’une ;<br><b>      2</b> bâtir avec, <i>càd</i>. unir des matériaux <i>ou</i> des parties d’édifice à d’autres dans une construction, <i>au pass</i>. THC. <i>1, 93 ;</i> DS. <i>13, 82 ;</i><br><b>      3</b> bâtir entièrement, <i>au pass</i>. DC. <i>39, 61</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">συνοικοδομεω - συνοικοδομέω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Ephésiens (1)</li>\n</ul>\n</td></tr>\n</table>","G4926":"<h1>sunomileo</h1>\n<p>Strong n° 4926 <i>Prononciation [soon-om-il-eh'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>parler avec, avoir une conversation, s'entretenir avec</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>συν·ομιλέω-ῶ</b> <span>[ῑ]</span> être en relation avec, avoir commerce avec, <i>dat</i>. NT. <i>Ap. 10, 27</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">συνομιλεω - συνομιλέω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G4927":"<h1>sunomoreo</h1>\n<p>Strong n° 4927 <i>Prononciation [soon-om-or-eh'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>être au bord, être contigu à, être mitoyen\n<ol type=\"a\">\n<li>d'une chose</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>συν·ομορέω-ῶ</b>, être limitrophe de, <i>dat</i>. NT. <i>Ap. 18, 7</i>.<br><span><b>Étym</b>. σύν, ὅμορος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">συνομορεω - συνομορέω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G4928":"<h1>sunoche</h1>\n<p>Strong n° 4928 <i>Prononciation [soon-okh-ay']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>se tenir ensemble, un voisinage</li>\n<li>la partie resserrée d'un chemin</li>\n<li>métaph. détresse, angoisse, resserrement (de cœur)</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>συνοχή</b>, <i>anc. att</i>. <b>ξυνοχή, ῆς (ἡ) :<br>   I</b> <i>intr. :</i><br><b>      1</b> continuité, ARSTT. <i>Top. 4, 2, 13 ;</i><br><b>      2</b> point de jonction : βλεφάρων, COL. <i>73,</i> réunion <i>ou</i> clôture des paupières ; ξ. χιτῶνος, A. RH. <i>1, 744,</i> point d’attache de la tunique sur les épaules ;<br><b>      3</b> cohésion, jonction, union, <i>d’où</i> contention d’esprit, attention, CHRYSIPP. (PLUT. <i>M. 1054</i> f) ; PLUT. <i>M. 881</i> b, <i>886</i> e ;<br><b>      4</b> resserrement : ἐν ξυνοχῇσιν ὁδοῦ, IL. <i>23, 330,</i> à l’endroit où la route se resserre, carrefour ; σ. ἁλός, A. RH. <i>2, 318,</i> détroit ; πολέμοιο, A. RH. <i>1, 160 ; ou</i> ἀγῶνος, Q. SM. <i>4, 342,</i> mêlée (<i>litt</i>. endroit où les combattants se pressent le plus) ;<br><b>   II</b> <i>tr. :</i><br><b>      1</b> action de tenir dans sa main, <i>gén</i>. PHILSTR. <i>168 ;</i><br><b>      2</b> ce qui resserre, <i>au pl</i>. liens, entraves, MAN. <i>1, 313, etc. ; fig</i>. anxiété, inquiétude, NT. <i>Luc. 21, 25 ; 2Cor. 2, 4</i>.<br><span><b>Étym</b>. συνέχω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">συνοχη - συνοχή</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Luc (1)</li>\n<li>2 Corinthiens (1)</li>\n</ul>\n</td></tr>\n</table>","G4929":"<h1>suntasso</h1>\n<p>Strong n° 4929 <i>Prononciation [soon-tas-so]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>mettre en ordre avec ou ensemble, arranger</li>\n<li>constituer\n<ol type=\"a\">\n<li>prescrire, désigner, nommer, ordonner</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>συν·τάσσω</b>, <i>att</i>. <b>συν·τάττω</b>, <i>anc. att</i>. <b>ξυν·τάττω :<br>   I</b> ranger ensemble, arranger, disposer en un tout, <i>acc</i>. XÉN. <i>Mem. 1, 4, 13 ;</i> PLAT. <i>Phil. 30</i> c, <i>etc. ; au pass</i>. ψυχὴ συντεταγμένη σώματι, PLAT. <i>Leg. 903</i> d, l’âme unie au corps ; πολιτεία συντεταγμένη, ARSTT. <i>Pol. 2, 11, 2,</i> gouvernement organisé ; <i>p. suite,</i> organiser de façon à faire entrer dans, à réunir à : ἀπόρους εἰς τὸ πολίτευμα, PLUT. <i>Cic. 30,</i> faire entrer les indigents dans l’organisation politique ; <i>au pass</i>. se réunir à, entrer dans l’organisation de, <i>avec</i> εἰς <i>et l’acc</i>. PLUT. <i>Arat. 24 ; abs. au pass</i>. s’organiser, se concerter : οἱ συντεταγμένοι, XÉN. <i>Hell. 3, 3, 7,</i> les conjurés ; <i>particul. :</i><br><b>      1</b> ranger en bataille : στράτευμα, XÉN. <i>Hell. 1, 2, 15,</i> une armée ; ἑαυτούς, PLUT. <i>Alc. 31,</i> se ranger en bataille ; πεζοὺς ἱππεῦσι σ. XÉN. <i>Hell. 7, 2, 24,</i> ranger l’infanterie en ligne avec la cavalerie ; σ. τινὶ τάξιν, ARR. <i>An. 4, 24, 10,</i> assigner à qqn le commandement d’une troupe ; <i>au pass</i>. avoir l’habitude d’être rangés, XÉN. <i>Cyr. 6, 4, 14, etc. ;</i><br><b>      2</b> composer un ouvrage, <i>acc</i>. POL. <i>2, 40, 4 ;</i> PLUT. <i>Brut. 4 ; joint à</i> γράφειν, LUC. <i>Philops. 32 ; au pass</i>. PLAT. <i>Leg. 930</i> c, <i>etc. ;</i><br><b>      3</b> combiner, machiner (une intrigue, un complot, <i>etc</i>.) DÉM. <i>888, 26 ;</i> ESCHN. <i>52, 36 ;</i><br><b>      4</b> construire une phrase, DH. <i>Comp. 34, 5 ;</i><br><b>   II</b> régler d’un commun accord : κατὰ τὸ συντεταγμένον, POL. <i>3, 42, 9,</i> selon la chose convenue, selon la convention ;<br><b>   III</b> ordonner, prescrire, <i>acc</i>. ATT. ; <i>avec l’inf</i>. XÉN. <i>Cyr. 8, 6, 8 ;</i> POL. <i>3, 50, 9 ; avec</i> ὅπως, XÉN. <i>Cyr. 8, 2, 3 ; avec une prop. inf</i>. ESCHN. <i>31, 8 ; au pass</i>. être ordonné, commandé : τινι, DÉM. <i>251, 11,</i> à qqn ; <i>abs</i>. POL. <i>9, 17, 2, etc. ; particul. :</i><br><b>      1</b> prescrire, faire une ordonnance (de médecin) : τί τινι, PLUT. <i>M. 204</i> b, <i>Per. 13,</i> prescrire un remède, des soins à qqn ; <i>au pass</i>. τὰ συντεταγμένα, DS. <i>1, 70,</i> les prescriptions médicales ;<br><b>      2</b> imposer une taxe, ESCHN. <i>67, 16 ; au pass</i>. être fixé, <i>en parl. d’impôts, de contributions,</i> DÉM. <i>1667, 6 ; en parl. de pers</i>. être frappé d’un impôt, ESCHN. <i>67, 28 ;</i><br><b><i>Moy.</i></b> :<br><b>   I <i>tr. :</i><br>      1</b> ranger, disposer qqe ch. à soi (<i>son armée,</i> XÉN. <i>Hell. 2, 4, 34 ; sa flotte,</i> XÉN. <i>Hell. 6, 2, 3, etc.) ; en gén</i>. arranger, fixer, régler : τὰ νόμιμα, PLAT. <i>Leg. 626</i> a ; νόμους, PLUT. <i>Sol. 5,</i> les coutumes, les lois ; τὴν εἰσφοράν, DÉM. <i>838, 9,</i> le chiffre de la contribution, <i>etc. ;</i><br><b>      2</b> composer (un discours, un livre, <i>etc.) acc</i>. PLAT. <i>Phædr. 263</i> e ; POL. <i>1, 3, 8 ;</i> DH. <i>Lys. 14 ;</i> PLUT. <i>Cato ma. 25, etc. ; abs</i>. composer, écrire : ὑπέρ τινος, POL. <i>9, 2, 2,</i> sur un sujet ;<br><b>      3</b> ordonner, prescrire, LUC. <i>Pseud. 5 ;</i><br><b>   II <i>intr. :</i><br>      1</b> se rapprocher de, se joindre à, se réunir avec : μετά τινος, LUC. <i>Dem. enc. 46,</i> se ranger du côté de qqn ; <i>en parl. de choses,</i> s’accorder, PLUT. <i>Them. 27 ;</i><br><b>      2</b> <i>particul. en parl. de troupes qui se rassemblent,</i> XÉN. <i>Cyr. 2, 4, 32 ;</i> XÉN. <i>An. 6, 1, 21, etc. ; au part</i>. ξυντεταγμένος, en bon ordre, THC. <i>3, 108 ;</i> DÉM. <i>585, 27 ;</i><br><b>      3</b> se mettre d’accord avec, convenir avec : τι, DÉM. <i>708, 18,</i> convenir de qqe ch. (avec qqn) ; πρός τινα, POL. <i>3, 67, 1,</i> convenir (de qqe ch.) avec qqn ; τι πρός τινα, POL. <i>9, 17, 1,</i> convenir de qqe ch. avec qqn : τινι <i>ou</i> πρός τινα <i>avec l’inf</i>. DÉM. <i>344 fin ;</i> POL. <i>5, 92, 7,</i> convenir avec qqn de, <i>etc. ;</i><br><b>      4</b> prendre congé de, faire ses adieux à, <i>dat</i>. ANTH. <i>9, 171 ;</i> RHÉT. <i>9, 309 W</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">συντασσω - συντάσσω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 1 livre biblique (NT)\n<ul>\n<li>Matthieu (2)</li>\n</ul>\n</td></tr>\n</table>","G4930":"<h1>sunteleia</h1>\n<p>Strong n° 4930 <i>Prononciation [soon-tel'-i-ah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>achèvement, consommation, fin</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>συντέλεια</b>, <i>anc. att</i>. <b>ξυντέλεια, ας (ἡ) :<br>   I</b> paiement en commun, DÉM. <i>306, 18 ;</i> ARSTT. <i>Rhet. Al. 3, 5 ;</i> DC. <i>42, 6 ; d’où</i> contribution, part de contribution personnelle, DÉM. <i>464, 1 ;</i> ce qui est fourni par qqn : ἡ παρὰ τοῦ διδασκάλου σ. ARSTD. <i>t. 2, 226,</i> ce que fournit le maître, <i>càd</i>. l’instruction ;<br><b>   II</b> <i>à Athènes,</i> association de citoyens pour subvenir à certaines dépenses publiques (armement d’une galère, <i>etc</i>.) DÉM. <i>261, 16 (décr.) ; 262, 8 ; p. ext. :</i><br><b>      1</b> toute association, corporation <i>ou</i> confédération avec trésor commun, POL. <i>5, 94, 1 ;</i> DS. <i>5, 80 ;</i> PLUT. <i>Phil. c. Flam. 1 ;</i><br><b>      2</b> réunion, assemblée (de dieux), ESCHL. <i>Sept. 251 ;</i><br><b>   III</b> <i>p. suite,</i> action de mener à terme, d’effectuer, accomplissement, achèvement, POL. <i>1, 3, 3, etc. ;</i> συντέλειαν ἔχειν, POL. <i>1, 4, 3,</i> être achevé ; συντέλειαν λαμϐάνειν, POL. <i>4, 28, 3,</i> prendre fin ; συντέλειαν ἐπιθεῖναι, POL. <i>11, 33, 7,</i> mettre fin aux travaux ; <i>p. suite :</i><br><b>      1</b> <i>t. de philos</i>. chose parvenue à son achèvement, à sa réalisation, réalité, OCELL. <i>2, 3 ;</i><br><b>      2</b> <i>t. de gr</i>. action accomplie, achevée, <i>d’où</i> temps marquant l’achèvement d’une action, parfait, D. PHAL. <i>§ 214</i>.<br><span><b>Étym</b>. συντελής.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">συντελεια - συντέλεια</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n6 fois dans 6 versets de 2 livres bibliques (NT)\n<ul>\n<li>Matthieu (5)</li>\n<li>Hébreux (1)</li>\n</ul>\n</td></tr>\n</table>","G4931":"<h1>sunteleo</h1>\n<p>Strong n° 4931 <i>Prononciation [soon-tel-eh'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>achever ensemble ou au même moment</li>\n<li>finir complètement\n<ol type=\"a\">\n<li>amener au but, finir, compléter</li>\n</ol>\n</li>\n<li>accomplir, amener à l'accomplissement</li>\n<li>effectuer, faire, conclure</li>\n<li>finir\n<ol type=\"a\">\n<li>faire une fin de</li>\n<li>amener à ses fins</li>\n<li>détruire</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>συντελέω</b>, <i>anc. att</i>. <b>ξυντελέω-ῶ :<br>   I <i>tr.</i></b> finir, accomplir, exécuter avec <i>ou</i> ensemble : ἅρματα, XÉN. <i>Cyr. 6, 1, 50,</i> faire fabriquer des chars ; στέφανον καὶ ἱμάτιον, DÉM. <i>522, 4,</i> confectionner à la fois une couronne et un vêtement ; ναῦς, POL. <i>1, 21, 3,</i> construire des vaisseaux ; νεών, PLUT. <i>Ant. 23,</i> construire un temple ; τὴν δαπάνην ἑξήκοντα τάλαντα συντελεῖ, DÉM. <i>183, 13,</i> soixante talents constituent la dépense totale ; σ. εἰρήνην, DS. <i>12, 26,</i> conclure la paix ; φιλοσόφους διάλογους, PLUT. <i>Cic. 40,</i> composer des dialogues philosophiques ; <i>particul. en parl. de fêtes, luttes, jeux, etc. :</i> σ. ἁγιστείας, PLAT. <i>Ax. 371</i> d, célébrer ensemble les rites sacrés ; ἀγῶνα, DS. <i>11, 29 ;</i> STR. <i>795, 796 ;</i> PLUT. <i>Thes. 19,</i> organiser ensemble un concours ; θυσίας, DS. <i>17, 16 ;</i> PLUT. <i>Them. 13,</i> célébrer ensemble des sacrifices ; πανήγυριν, DS. <i>17, 16,</i> tenir une assemblée générale ; τὰ Ἴσθμια, PLUT. <i>Ages. 21,</i> célébrer ensemble les jeux Isthmiques ;<br><b>   II <i>intr. :</i><br>      1</b> parvenir avec <i>ou</i> ensemble au même but, à une même fin, <i>avec</i> εἰς <i>et l’acc</i>. PLUT. <i>Sol. 20 ;</i> HDN <i>2, 2, 15 ; d’où</i> concourir à, contribuer à, <i>avec</i> πρός <i>et l’acc</i>. ARSTT. <i>G.A. 1, 12 ;</i> PLUT. <i>Lyc. 25 ; ou</i> εἰς <i>et l’acc</i>. ARSTT. <i>H.A. 3, 1, 1 ; P.A. 3, 7, 2 ;</i><br><b>      2</b> <i>p. suite,</i> payer ensemble <i>ou</i> en commun des impôts, des tributs, fournir les mêmes contributions, payer les mêmes frais : ἐν ταῖς εἰσφοραῖς σ. εἰς τὸν πόλεμον, DÉM. <i>465, 23,</i> contribuer au paiement des contributions de guerre ; σ. εἰσφορὰς τοῖς Ἀχαιοῖς, POL. <i>4, 60, 4,</i> payer la contribution aux Achéens ;<br><b>      3</b> <i>p. suite, en gén</i>. contribuer à, aider à : πρός τι, LUC. <i>Salt. 63,</i> à qqe ch. ; οὐδὲν τῷ χρησμῷ πρὸς τὴν νόσον σ. LUC. <i>Alex. 36,</i> n’aider en rien à l’oracle contre la maladie ; <i>avec le dat</i>. σ. τῷ βίῳ, ALEX. (<i>Com. fr. 3, 518</i>) être utile pour la vie ;<br><b>      4</b> <i>p. suite,</i> συντελεῖν εἴς τινας <i>ou</i> εἴς τι, appartenir à une certaine classe, <i>litt</i>. payer des impôts comme citoyen inscrit parmi (les hommes faits, <i>etc</i>.) : σ. εἰς ἄνδρας, ISOCR. <i>277</i> b, faire partie des hommes faits ; εἰς τὸ μετοίκιον, LUC. <i>Bis acc. 9,</i> faire partie des métèques ; <i>avec le dat</i>. σ. τῷ χορῷ, ALCIPHR. <i>3, 71,</i> faire partie du chœur ;<br><b>      5</b> payer une contribution à une cité, à un État, à un peuple, <i>en parl. de cités ou de peuples soumis à une souveraineté <i>ou</i> à une juridiction étrangère, càd</i>. être tributaire, payer un tribut à un autre État : ἐς Ἀθήνας, THC. <i>2, 15 ;</i> ἐς Ὀρχομενόν, THC. <i>4, 76,</i> être tributaire d’Athènes, d’Orchomène ; <i>cf</i>. XÉN. <i>Hell. 7, 4, 12 ;</i> ISOCR. <i>298</i> c ; PLUT. <i>Lyc. 8, etc. ; avec le dat</i>. σ. τινι, ISOCR. <i>298</i> a ; PLUT. <i>Arat. 34, m. sign. ; abs</i>. PLUT. <i>Arat. 54 ;</i><br><b><i>Moy.</i></b> (<i>inf. ao</i>. συντελέσασθαι) accomplir, achever, venir à bout de, <i>acc</i>. POL. <i>1, 9, 6 ; 5, 100, 9 ;</i> DS. <i>1, 59</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">συντελεω - συντελέω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n7 fois dans 7 versets de 6 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Marc (1)</li>\n<li>Luc (2)</li>\n<li>Actes (1)</li>\n<li>Romains (1)</li>\n<li>Hébreux (1)</li>\n</ul>\n</td></tr>\n</table>","G4932":"<h1>suntemno</h1>\n<p>Strong n° 4932 <i>Prononciation [soon-tem'-no]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>couper en morceaux</li>\n<li>découper</li>\n<li>métaph.\n<ol type=\"a\">\n<li>expédier brièvement, exécuter ou finir rapidement, abréger</li>\n<li>se hâter</li>\n<li>une courte parole c.à.d. une prophétie ou un décret très brefs</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>συν·τέμνω</b>, couper sur la masse, diminuer en coupant, tailler, rogner, réduire, THC. <i>7, 36 ; fig. :</i> σ. τὰς δαπάνας, XÉN. <i>Hier. 4, 9,</i> réduire les dépenses ; σ. λόγους, AR. <i>Th. 178 ;</i> ESCHN. <i>32, 23 ;</i> ἀποκρίσεις, PLAT. <i>Prot. 334</i> d, abréger des discours, des réponses ; <i>abs</i>. ὡς δὴ συντέμνω (<i>s.-e</i>. τὸν λόγον) EUR. <i>Tr. 441 ; ou</i> ἵνα συντέμνω, DÉM. <i>704, 11,</i> pour abréger ; συντεμνόντι (<i>s.-e</i>. εἰπεῖν) ANAXILAS (ATH. <i>558</i> e) en un mot, bref ; <i>particul. :</i><br><b>      1</b> <i>avec idée de lieu,</i> atteindre au plus vite, <i>acc.,</i> SOPH. <i>Ant. 1103 ;</i> prendre le plus court chemin, <i>avec</i> ἐπί <i>et l’acc</i>. HDT. <i>7, 123, etc. ;</i><br><b>      2</b> <i>avec idée de temps,</i> serrer de près : τοῦ χρόνου συντάμνοντος (<i>ion. p</i>. συντέμνοντος) HDT. <i>5, 41,</i> le temps pressant ;<br><b>      3</b> <i>en gén</i>. couper, supprimer, détruire, <i>fig</i>. SOPH. <i>Ant. 1103 ;</i><br><b>      4</b> diviser ensemble, PLAT. <i>Soph. 227</i> d, <i>Pol. 261</i> a.<br><span><b><span class=\"arrow\"></span></b> <i>Ion</i>. συντάμνω, HDT. <i>ll. cc</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">συντεμνω - συντέμνω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Romains (2)</li>\n</ul>\n</td></tr>\n</table>","G4933":"<h1>suntereo</h1>\n<p>Strong n° 4933 <i>Prononciation [soon-tay-reh'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>préserver, conserver (une chose pour qu'elle ne soit pas perdue)</li>\n<li>garder en soi-même, garder à l'esprit (une chose, de peur qu'elle ne soit oubliée)</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>συν·τηρέω-ῶ :<br>   I</b> conserver :<br><b>      1</b> conserver <i>ou</i> préserver avec soin, <i>acc</i>. ARSTT. <i>Plant. 1, 1, 12,</i> NT. <i>Luc. 2, 19 ;</i><br><b>      2</b> conserver un secret, POL. <i>31, 6, 5 ;</i><br><b>   II</b> observer, surveiller (l’occasion) PLUT. <i>Marc. 12</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">συντηρεω - συντηρέω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 3 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Marc (1)</li>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G4934":"<h1>suntithemai</h1>\n<p>Strong n° 4934 <i>Prononciation [soon-tith'-em-ahee]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>mettre ensemble, placer ensemble, se joindre à\n<ol type=\"a\">\n<li>mettre à l'esprit\n<ol>\n<li>résoudre, déterminer</li>\n<li>faire un arrangement, s'engager</li>\n</ol>\n</li>\n<li>consentir à, être d'accord pour, s'entendre pour, décider</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>συν·τίθημι</b>, <i>anc. att</i>. <b>ξυν·τίθημι</b> <span>(<i>f</i>. συνθήσω, <i>ao</i>. συνέθηκα, <i>etc</i>.)</span> <span>[τῐ]</span> mettre ensemble, <i>càd. :</i><br><b>   I. 1</b> rassembler, réunir : ἄρθρα στόματος, EUR. <i>Cycl. 625, litt</i>. réunir les articulations de la bouche, <i>càd</i>. fermer les lèvres ; ὅπλα ἐν ναῷ, XÉN. <i>Hell. 2, 3, 20,</i> réunir des armes dans un temple ; ἐν ἅλῳ σῖτον, PLUT. <i>M. 774</i> f, rassembler du blé dans une grange ; <i>p. opp. à</i> ἀνασείειν, XÉN. <i>Œc. 10, 11, en parl. de vêtements ; à</i> ἀνατείνειν, XÉN. <i>Cyn. 5, 10 ; à</i> διαιρεῖν, PLAT. <i>Soph. 52</i> a, <i>etc. ; fig</i>. ἐν βραχεῖ συνθείς, SOPH. <i>El. 673,</i> en résumant brièvement ;<br><b>      2</b> <i>t. d’arithm</i>. ajouter l’un à l’autre, additionner, <i>acc</i>. HDT. <i>3, 95 ; t. de rhét</i>. accumuler, ARSTT. <i>Rhet. 1, 7, 31 ;</i><br><b>   II</b> adapter, ajuster : λίθους, THC. <i>4, 4,</i> des pierres ; συλλαϐάς, PLAT. <i>Crat. 425</i> a, des syllabes, <i>etc. ; d’où :</i><br><b>      1</b> construire : τριήρεας, HDT. <i>7, 36,</i> des trirèmes ; θνητὸν γένος, PLAT. <i>Tim. 69</i> d, créer la race mortelle ;<br><b>      2</b> <i>fig</i>. mettre en ordre, arranger, disposer avec art, composer : λόγον, EUR. <i>Bacch. 297 ;</i> PLAT. <i>Phædr. 260</i> b, <i>etc</i>. un discours ; ποίησιν, PLAT. <i>Phædr. 278</i> c, une œuvre poétique, <i>etc. ;</i> τὰ Ἑλληνικά, THC. <i>1, 97,</i> exposer les affaires de la Grèce ;<br><b>      3</b> combiner, machiner : ἀπάτην, PLUT. <i>Nic. 26,</i> une fraude ; μύθους ψευδεῖς, PLAT. <i>Rsp. 377</i> d, composer des récits mensongers ; ψευδεῖς αἰτίας, DÉM. <i>778, 22,</i> machiner des accusations mensongères ; ὁ συνθεὶς τάδε, SOPH. <i>O.R. 401,</i> le rusé instigateur de tout cela ; <i>rar. en b. part,</i> s’occuper de, avoir soin de, <i>acc</i>. IS. <i>70, 29 ; d’où</i> établir, fixer : συντεθεὶς χρόνος, PLAT. <i>Phædr. 254</i> d, temps fixé ;<br><b>   III</b> rapprocher par l’esprit : ἅπαντα εἰς ἕν, EUR. <i>I.T. 1016,</i> rassembler toutes les circonstances dans son esprit, <i>d’où :</i><br><b>      1</b> mettre à côté l’un de l’autre, comparer, <i>acc</i>. DÉM. <i>819, 2 ; 853, 19 ;</i> PLUT. <i>Luc. 8 ;</i><br><b>      2</b> juger, conjecturer, <i>avec une prop. inf</i>. POL. <i>28, 15, 14 ;</i><br><b>      3</b> conclure, ARR. <i>Ind. 34 ;</i><br><b>   IV</b> commettre, <i>d’où :</i><br><b>      1</b> confier : τινί τι, POL. <i>5, 10, 4,</i> qqe ch. à qqn ; <i>cf</i>. POL. <i>28, 18, 3, etc. ;</i><br><b>      2</b> procurer : τινὶ συμμάχους, DS. <i>13, 52,</i> des alliés à qqn ;<br><b><i>Moy.</i></b> <span>(<i>f</i>. συνθήσομαι, <i>ao.2</i> συνεθέμην, <i>etc</i>.)</span><br><b>   I</b> rassembler pour soi, <i>acc</i>. XÉN. <i>Hell. 4, 8, 20 ; 6, 1, 17 ;</i><br><b>   II</b> rapprocher <i>ou</i> recueillir dans son esprit, <i>càd. :</i><br><b>      1</b> écouter, observer, remarquer : θυμῷ, IL. <i>7, 44 ;</i> φρεσί. OD. <i>1, 328,</i> recueillir dans son cœur, dans son esprit : <i>abs</i>. IL. <i>19, 84 ;</i> OD. <i>15, 27 ; 24, 265 ;</i><br><b>      2</b> percevoir par l’oreille, entendre, <i>acc</i>. OD. <i>20, 92 ; abs</i>. OD. <i>17, 153, etc. ; avec un gén</i>. APOLLIN. <i>Ps. 117, 34 et 56 ;</i><br><b>   III</b> convenir de, <i>d’où :</i><br><b>      1</b> fixer <i>ou</i> régler par une convention : τι, THC. <i>3, 114, etc. ;</i> XÉN. <i>Ath. 2, 17, etc. ;</i> EUR. <i>Bacch. 807,</i> qqe ch. ; φιλίαν, XÉN. <i>An. 2, 5, 8, etc</i>. un traité d’amitié ; εἰρήνην, ISOCR. <i>Antid. § 109, etc</i>. un traité de paix ; τινί τι, HDT. <i>3, 157, etc. ;</i> PLUT. <i>Pel. 20 ; ou</i> τι πρός τινα, HDT. <i>7, 145 ;</i> XÉN. <i>Hell. 6, 3, 7,</i> qqe ch. avec qqn ; <i>abs</i>. faire une convention, un pacte, un traité avec, <i>dat</i>. PD. <i>N. 4, 122 ;</i> HDT. <i>6, 115 ;</i> XÉN. <i>Mem. 2, 6, 26, etc. ;</i><br><b>      2</b> gager, faire un pari : πρός τινα, PLUT. <i>Alc. 8,</i> avec qqn ;<br><b>      3</b> promettre, <i>avec l’inf. prés</i>. PD. <i>P. 11, 64 ; avec l’inf. fut</i>. XÉN. <i>Hell. 3, 5, 6 ;</i> PLUT. <i>Rom. 19, Alc. 30, etc. ;</i><br><b>      4</b> tomber d’accord avec, être du même avis que, consentir à, <i>dat</i>. LYS. (HARP. <i>p. 106, 9 Bkk</i>.) ; DH. <i>Isocr. 18 ;</i> PAUS. <i>4, 15, 2, etc</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Ao.2 moy. indic. 3 sg. poét</i>. σύνθετο, IL. <i>7, 44 ;</i> OD. <i>1, 328 ; 20, 92 ; impér. 2 sg. poét</i>. σύνθεο, IL. <i>1, 76 ; 19, 84 ;</i> OD. <i>15, 27, 318 ; 17, 153, etc</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">συντιθημαι - συντίθημι</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n4 fois dans 4 versets de 3 livres bibliques (NT)\n<ul>\n<li>Luc (1)</li>\n<li>Jean (1)</li>\n<li>Actes (2)</li>\n</ul>\n</td></tr>\n</table>","G4935":"<h1>suntomos</h1>\n<p>Strong n° 4935 <i>Prononciation [soon-tom'-oce]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>avec concision, brièvement, en quelques paroles</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>συντόμως</b>, <i>adv. :</i><br><b>      1</b> en peu de mots, ESCHL. <i>Ag. 629, etc. ;</i> PLAT. <i>Tim. 25</i> e ;<br><b>      2</b> en peu de temps, ESCHL. <i>Eum. 415 ;</i> SOPH. <i>O.R. 810 ;</i> HPC. <i>152</i> c, <i>1154</i> a ; XÉN. <i>Hell. 3, 4, 15</i>.<br><span>•<i> Cp</i>. -ώτερον, ISOCR. <i>53</i> d, <i>195</i> c ; <i>ou</i> -ωτέρως, IS. <i>83, 11 ;</i> <i>• Sup</i>. -ώτατον, ALEX. (ATH. <i>562</i> b) ; -ώτατα, ISOCR. <i>214</i> a ; -ωτάτως, SOPH. <i>O.C. 1579</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">συντομως - συντόμως</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adverbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G4936":"<h1>suntrecho</h1>\n<p>Strong n° 4936 <i>Prononciation [soon-trekh'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>courir ensemble\n<ol type=\"a\">\n<li>du rassemblement d'une multitude</li>\n</ol>\n</li>\n<li>accourir avec les autres</li>\n<li>métaph.\n<ol type=\"a\">\n<li>se précipiter avec, se ruer, se jeter, plonger</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>συν·τρέχω</b> <span>(<i>f</i>. συνθρέξομαι <i>ou</i> συνδραμοῦμαι, <i>ao.2</i> συνέδραμον, <i>etc</i>.)</span><br><b>   I</b> courir avec, <i>càd. :</i><br><b>      1</b> lutter à la course avec, <i>dat</i>. PLAT. <i>Pol. 266</i> c ;<br><b>      2</b> courir avec à la suite de, XÉN. <i>Cyr. 2, 2, 9 ;</i><br><b>   II</b> courir de différents points vers un même lieu, <i>d’où :</i><br><b>      1</b> se rassembler, HDT. <i>2, 121 ; 8, 71 ;</i> LYCURG. <i>149, 40 ; en parl. de nuages,</i> HDT. <i>1, 87 ;</i><br><b>      2</b> se mêler avec, <i>dat. en parl. de liquides,</i> SOPH. <i>O.C. 160 ;</i><br><b>      3</b> rencontrer, <i>dat</i>. SOPH. <i>Tr. 879 ; avec idée d’hostilité,</i> se rencontrer, en venir aux mains, IL. <i>16, 335, 337 ;</i> ἐς χεῖρας σ. POL. <i>2, 33, 5, m. sign. ;</i> σ. τινί, PLUT. <i>Artax. 7,</i> en venir aux mains avec qqn ;<br><b>      4</b> <i>fig</i>. aboutir ensemble à, marcher d’accord, s’accorder, <i>avec</i> πρός <i>et l’acc</i>. HDT. <i>1, 53 ; avec le dat</i>. XÉN. <i>Cyr. 8, 2, 27 ;</i><br><b>      5</b> concourir, concorder, DÉM. <i>214, 7 ;</i> ISOCR. <i>130</i> b ; <i>avec idée de temps,</i> coïncider avec, <i>dat</i>. SOPH. <i>Tr. 295 ; abs</i>. ESCHL. <i>fr. 299 ;</i> EUR. <i>Or. 1215 ;</i><br><b>   III</b> se replier sur soi-même, se contracter, HPC. <i>Fract. 775 ;</i> XÉN. <i>Cyn. 10, 17 ;</i> εἰς ἑαυτήν, PLUT. <i>M. 97, 8</i> d, se replier sur elle-même.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">συντρεχω - συντρέχω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 3 livres bibliques (NT)\n<ul>\n<li>Marc (1)</li>\n<li>Actes (1)</li>\n<li>1 Pierre (1)</li>\n</ul>\n</td></tr>\n</table>","G4937":"<h1>suntribo</h1>\n<p>Strong n° 4937 <i>Prononciation [soon-tree'-bo]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>briser, casser en morceaux, fracasser, broyer</li>\n<li>mettre à terre\n<ol type=\"a\">\n<li>mettre Satan sous son pied et le piétiner (comme un conquérant)</li>\n<li>rompre, écraser\n<ol>\n<li>déchirer un corps et briser une force</li>\n</ol>\n</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>συν·τρίϐω</b>, <i>anc. att</i>. <b>ξυν·τρίϐω</b> <span>[ῑ]</span><br><b>      1</b> frotter l’un contre l’autre : πυρεῖα, LUC. <i>V.H. 1, 32,</i> des morceaux de bois sec pour se procurer du feu ;<br><b>      2</b> broyer ensemble : φάρμακα, PLUT. <i>M. 436</i> b, des drogues ; <i>fig</i>. ποῦ συντρίϐεται τὸ πρᾶγμα ; DÉM. <i>142, 22,</i> en quel point les intérêts se heurtent-ils ? où commence le conflit ? ;<br><b>      3</b> <i>en gén</i>. broyer, briser : δόρατα, XÉN. <i>Hell. 3, 4, 14,</i> briser des lances ; ᾠά, ARSTT. <i>H.A. 6, 9, 3,</i> briser des œufs ; τινὰ τῆς κεφαλῆς, AR. <i>Pax 71 ;</i> ISOCR. <i>381</i> b ; τῶν κρανίων, LUC. <i>Char. 5,</i> casser la tête de qqn ; <i>au pass. :</i> συντριϐόμεθα τὰς κεφάλας, LYS. <i>98, 7,</i> nous avons la tête cassée ; συντετριμμένοι σκέλη, XÉN. <i>An. 4, 7, 4,</i> qui ont les jambes brisées ; <i>fig</i>. σ. τοὺς Ἀχαιούς, POL. <i>5, 47, 1,</i> briser, <i>càd</i>. décourager les Achéens ; τὴν ἐπίνοιαν, AR. <i>Vesp. 1050,</i> voir briser sa création ; τὸν ἄνθρωπον, PLUT. <i>M. 165</i> b, briser l’homme, <i>en parl. de la crainte ; au pass</i>. συντρίϐεσθαι τῇ διανοίᾳ, POL. <i>21, 10, 2,</i> avoir l’esprit brisé ; τὴν καρδίαν, NT. <i>Luc. 4, 18,</i> avoir le cœur brisé.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">συντριβω - συντρίβω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n8 fois dans 8 versets de 6 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Marc (2)</li>\n<li>Luc (2)</li>\n<li>Jean (1)</li>\n<li>Romains (1)</li>\n<li>Apocalypse (1)</li>\n</ul>\n</td></tr>\n</table>","G4938":"<h1>suntrimma</h1>\n<p>Strong n° 4938 <i>Prononciation [soon-trim'-mah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>ce qui est cassé ou brisé, une fracture</li>\n<li>calamité, ruine, destruction</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>σύντριμμα, ατος (τὸ) :<br>      1</b> fracture, ARSTT. <i>Aud. 34 ;</i> SPT. <i>Lev. 21, 19 ;</i><br><b>      2</b> <i>fig</i>. ruine, SPT. <i>Esaï. 59, 7 ; Jer. 3, 22</i>.<br><span><b>Étym</b>. συντρίϐω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">συντριμμα - σύντριμμα</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Romains (1)</li>\n</ul>\n</td></tr>\n</table>","G4939":"<h1>suntrophos</h1>\n<p>Strong n° 4939 <i>Prononciation [soon'-trof-os]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>nourri avec quelqu'un, frère de lait</li>\n<li>élevé avec un autre</li>\n<li>compagnon d'enfance et de jeunesse</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>σύντροφος</b>, <i>anc. att</i>. <b>ξύντροφος, ος, ον :<br>   I</b> <i>pass</i>. nourri <i>ou</i> élevé avec, <i>d’où :</i><br><b>      1</b> <i>en parl. de pers</i>. qui vit avec, compagnon <i>ou</i> compagne de, <i>dat</i>. HDT. <i>1, 99 ;</i> AR. <i>Ach. 989 ; gén</i>. PHYLARQ. (ATH. <i>271</i> e) ; POL. <i>5, 9, 4, etc. ; en parl. d’animaux,</i> qui vit avec, familier avec, <i>dat</i>. HDT. <i>2, 65 ; abs. en parl. d’animaux,</i> compagnon, XÉN. <i>Mem. 2, 3, 4 ; joint à</i> συνήθη, ARSTT. <i>H.A. 9, 44, 2 ; particul</i>. qui a les mêmes habitudes, PLAT. <i>Leg. 949</i> c ; <i>avec un gén. ou un dat. de ch. :</i> σ. τῇ φιλοσοφίᾳ καὶ πενίᾳ, LUC. <i>Nigr. 12,</i> nourri dans la philosophie et la pauvreté ;<br><b>      2</b> <i>en parl. de choses,</i> naturel, habituel, HPC. <i>Aër. 283, etc. ;</i> τὰ ξύντροφα, THC. <i>2, 50,</i> les maux <i>ou</i> les accidents ordinaires ; <i>avec un rég</i>. familier à, habituel à : τινι, HPC. <i>Off. 744 ;</i> HDT. <i>7, 102 ;</i> τινος, SOPH. <i>Ph. 203,</i> à qqn ;<br><b>   II</b> <i>act. :</i><br><b>      1</b> qui aide à nourrir : τινί τινος, PLAT. <i>Leg. 845</i> d, qui aide qqn à nourrir qqn ; <i>p. suite,</i> qui aide à préserver, <i>gén</i>. XÉN. <i>Mem. 4, 3, 8 ;</i><br><b>      2</b> qui aide à mener paître, pâtre auxiliaire, <i>gén</i>. PLAT. <i>Pol. 267</i> e.<br><span><b>Étym</b>. συντρέφω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">συνθροφος - σύντροφος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G4940":"<h1>suntugchano</h1>\n<p>Strong n° 4940 <i>Prononciation [soon-toong-khan'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>rencontrer, venir, accoster</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>συν·τυγχάνω</b>, <i>anc. att</i>. <b>ξυντυγχάνω</b> <span>(<i>f</i>. συντεύξομαι, <i>ao.2</i> συνέτυχον, <i>etc</i>.)</span><br><b>      1</b> se rencontrer avec, rencontrer, <i>dat</i>. HDT. <i>4, 14 ;</i> AR. <i>Nub. 608, etc. ; ou gén</i>. SOPH. <i>Ph. 320, etc. ; avec un suj. de chose,</i> SOPH. <i>Ph. 683, etc. ; abs. en parl. d’événements,</i> se rencontrer, arriver, survenir, ESCHL. <i>Sept. 274 ;</i> SOPH. <i>Aj. 313 ;</i> THC. <i>3, 59 ;</i> ὁ συντυχών, <i>fréq. chez les Att. ;</i> EUR. <i>Hec. 1182, etc. ; au prés</i>. ὁ συντυγχάνων, PLAT. <i>Leg. 762</i> d, le premier venu ; τὸ συντυχόν, XÉN. <i>Ages. 9, 3 ;</i> τὰ συντυχόντα, HDT. <i>8, 136 ;</i> τὰ συντυγχάνοντα, XÉN. <i>Mem. 1, 6, 7 ;</i> PLUT. <i>Oth. 13,</i> les événements ; οὐ συντυχὸν ἔργον, HDT. <i>1, 51,</i> travail qui n’est pas le premier venu, non commun, non vulgaire ;<br><b>      2</b> <i>impers</i>. συντυγχάνει, il se rencontre que, <i>avec une prop. inf</i>. THC. <i>7, 70 ;</i> PLUT. <i>Lys. 12, Pel. 18 ; ou un part</i>. CHRYSIPP. (PLUT. <i>M. 1054</i> c).\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">συντυγχανω - συντυγχάνω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G4941":"<h1>Suntuche</h1>\n<p>Strong n° 4941 <i>Prononciation [soon-too'-khay]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Syntyche = « rencontre avec le destin », « qui a de la chance »\n<ol><li>une femme membre de l'église de Philippes</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Συντυχη - Συντύχη</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Philippiens (1)</li>\n</ul>\n</td></tr>\n</table>","G4942":"<h1>sunupokrinomai</h1>\n<p>Strong n° 4942 <i>Prononciation [soon-oo-pok-rin'-om-ahee]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>dissimuler à quelqu'un</li>\n<li>agir d'une manière hypocrite avec, jouer un rôle, feindre</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>συν·υποκρίνομαι</b> <span>[ῑν]</span><br><b>      1</b> jouer un rôle avec, <i>dat</i>. feindre en même temps, POL. <i>3, 52, 6 ;</i><br><b>      2</b> aider à feindre : τινί τι, PLUT. <i>Mar. 14,</i> aider qqn à feindre qqe ch., appuyer un prétexte donné par qqn.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">συνυποκρινομαι - συνυποκρίνομαι</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Galates (1)</li>\n</ul>\n</td></tr>\n</table>","G4943":"<h1>sunupourgeo</h1>\n<p>Strong n° 4943 <i>Prononciation [soon-oop-oorg-eh'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>porter secours ensemble, coopérer en assistant, assister de sa coopération</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>συν·υπουργέω</b>, <i>ion. et anc. att</i>. <b>ξυν·υπουργέω-ῶ</b>, joindre son assistance à celle d’un autre, HPC. <i>Art. 824 ;</i> LUC. <i>Bis acc. 17 ;</i> NT. <i>2Cor. 1, 11</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">συνυπουργεω - συνυπουργέω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>2 Corinthiens (1)</li>\n</ul>\n</td></tr>\n</table>","G4944":"<h1>sunodino</h1>\n<p>Strong n° 4944 <i>Prononciation [soon-o-dee'-no]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>ressentir ensemble les peines de l'enfantement, être en travail ensemble</li>\n<li>souffrir l'agonie avec (comme une femme qui accouche)</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>συν·ωδίνω</b> <span>[ῑ]</span> souffrir en même temps qu’une autre les douleurs de l’enfantement, <i>d’où</i> souffrir avec un autre, EUR. <i>Hel. 727 ;</i> ARSTT. <i>Eud. 7, 6, 5</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">συνωδινω - συνωδίνω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Romains (1)</li>\n</ul>\n</td></tr>\n</table>","G4945":"<h1>sunomosia</h1>\n<p>Strong n° 4945 <i>Prononciation [soon-o-mos-ee'-ah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>un serment fait ensemble</li>\n<li>une conspiration, un complot, une conjuration</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>συνωμοσία</b>, <i>anc. att</i>. <b>ξυνωμοσία, ας (ἡ) :<br>      1</b> union par serment, conjuration, AR. <i>Eq. 476 ;</i> THC. <i>6, 27, 60 ;</i> οἱ ἐν τῇ ξυνωμοσίᾳ, THC. <i>8, 49 ;</i> οἱ ἐκ τῆς συνωμοσίας, PLUT. <i>Ant. 13,</i> ceux de la conjuration, les conjurés ;<br><b>      2</b> association politique, THC. <i>8, 54, 81 ;</i> PLAT. <i>Ap. 36</i> b, <i>Rsp. 365</i> d ;<br><b>      3</b> ligue de confédérés, confédération, THC. <i>7, 83</i>.<br><span><b>Étym</b>. συνόμνυμι.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">συνωμοσια - συνωμοσία</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G4946":"<h1>Surakousai</h1>\n<p>Strong n° 4946 <i>Prononciation [soo-rak'-oo-sahee]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Syracuse = « une ouïe Syrienne », « violemment »\n<ol><li>grande cité maritime de Sicile, ayant un excellent port, entourée par un rempart de 25 kilomètres</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>Συράκουσα, ης (ἡ)</b> <span>[ῠᾱκ]</span><br><b>      1</b> ἡ Σ. E. BYZ. <i>p. 593, 2 Meineke ;</i> DS. <i>13, 75 ; 14, 11 ; ou mieux</i> αἱ Συράκουσαι, Syracuse (<i>auj</i>. Siracusa) <i>v. de Sicile,</i> THC. <i>5, 4, etc. ;</i> XÉN. <i>Hell. 1, 1, 29, etc. ;</i><br><b>      2</b> Syrakousa, <i>f</i>. PLUT. <i>Am. narr. 2</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Ion</i>. Συρήκουσαι, HDT. <i>7, 154, etc</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Συρακουσαι - Συράκουσαι</font>\n<br><br>pluriel de dérivation incertaine</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre de lieu</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G4947":"<h1>Suria</h1>\n<p>Strong n° 4947 <i>Prononciation [soo-ree'-ah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Syrie (Angl. Syria) = « hauteurs, élevé »\n<ol>\n<li>région d'Asie limitée au nord par les chaînes du Taurus et de l'Amanus, à l'est par l'Euphrate et l'Arabie, au sud par la Palestine, et à l'ouest par la Phénicie et la Méditerranée</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n➀ <b>Συρία, ας (ἡ)</b> <span>[ῠ]</span> la Syrie, <i>contrée d’Asie Mineure,</i> HDT. <i>1, 105, etc. ;</i> XÉN. <i>Cyr. 6, 2, 11, etc. ;</i> Σ. ἡ Παλαιστίνη, HDT. <i>3, 91 ; 4, 39,</i> la Syrie de Palestine ; ἡ Φοινίκη Σ. DS. <i>19, 93,</i> la Syrie de Phénicie ; Κοιλὴ Σ. STR. <i>133,</i> la Syrie Creuse, <i>càd</i>. enfoncée, <i>ou</i> Cœlésyrie, <i>entre le Liban et l’Anti-Liban, auj</i>. la Bekaa.<br><span><b><span class=\"arrow\"></span></b> <i>Ion</i>. Συρίη, HDT. <i>ll. cc</i>.</span><br><br>\n➁ <b>Συρία</b>, <i>ion</i>. <b>Συρίη, ης (ἡ)</b> <span>[ῠ]</span> Syria, <i>une des Cyclades, auj</i>. Syros, OD. <i>15, 403</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Συρια</font> &lt; סוריא - <font face=\"Georgia\">Συρία</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre de lieu</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n8 fois dans 8 versets de 4 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Luc (1)</li>\n<li>Actes (5)</li>\n<li>Galates (1)</li>\n</ul>\n</td></tr>\n</table>","G4948":"<h1>Suros</h1>\n<p>Strong n° 4948 <i>Prononciation [soo'-ros]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>un habitant de Syrie</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>Σύρος, ου (ὁ)</b> <span>[ῠ]</span><br><b>   I</b> <i>n. ethn. ou géogr. :</i><br><b>      1</b> Syrien, HDT. <i>2, 104 ;</i> ESCHL. <i>fr. 264 ;</i> XÉN. <i>Mem. 2, 1, 10, etc. ;</i> PLUT. <i>Mar. 17, etc. ;</i><br><b>      2</b> <i>synon. de</i> Ἀσσύριος, HDT. <i>7, 63 ;</i> XÉN. <i>Cyr. 5, 4, 51, etc. ;</i><br><b>      3</b> Σύροι Καππαδόκαι (<i>postér</i>. Λευκόσυροι) les Syriens de Cappadoce (<i>v</i>. Σύριος) HDT. <i>1, 72 ; 2, 104, etc. ;</i><br><b>   II</b> <i>n. d’h</i>. Syros, <i>fils d’Apollon,</i> PLUT. <i>Luc. 23, etc</i>. (<i>v</i>. Συρία). (ὁ)\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Συρος - Σύρος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G4949":"<h1>Surophoinissa</h1>\n<p>Strong n° 4949 <i>Prononciation [soo-rof-oy'-nis-sah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Syro-phénicienne (Syrophenician) = « palmier élevé »\n<ol><li>le nom d'une race mixte, à moitié Phénicienne et à moitié Syrienne</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Συροφοινισσα - Συροφοινίκισσα</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Marc (1)</li>\n</ul>\n</td></tr>\n</table>","G4950":"<h1>Surtis</h1>\n<p>Strong n° 4950 <i>Prononciation [soor'-tis]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>la Syrte, les bancs de la Syrie, les bancs de sable de la Syrie ; il s'agit de la Grande et de la Petite Syrte, deux bancs de sables mouvants, fort redoutés de l'équipage du navire de Paul. La Grande est au sud-est de l'échancrure de l'Afrique, face à la Sicile, la Petite est au sud-ouest de cette échancrure.</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>Σύρτις, ιδος (ἡ)</b> Syrte, <i>banc de sable, particul. n. de deux bancs de sable très spacieux sur la côte de Libye,</i> la Grande Syrte (<i>auj</i>. golfe de Syrte), la Petite Syrte (<i>auj</i>. golfe de Gabès) HDT. <i>2, 32, 150, etc. ;</i> ARSTT. <i>Mund. 3 ;</i> STR. <i>123, etc. ;</i> PLUT. <i>Dio. 25 ;</i> LUC. <i>Dips. 6, etc</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Gén</i>. -ιδος, DP. <i>477, etc. ; gén. ion</i>. -ιος, HDT. <i>2, 32, etc. ; plur</i>. Σύρτιδες, DP. <i>184</i>.<br><span><b>Étym</b>. σύρω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Συρτις - Σύρτις</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G4951":"<h1>suro</h1>\n<p>Strong n° 4951 <i>Prononciation [soo'-ro]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>tirer, traîner\n<ol type=\"a\">\n<li>quelqu'un devant le juge, en prison, au châtiment</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>σύρω</b> <span>[ῡ]</span> <span>(<i>f</i>. συρῶ <span>[ῠ]</span>, <i>ao</i>. ἔσυρα <span>[ῡ]</span>, <i>pf</i>. σέσυρκα ; <i>pass. ao</i>. ἐσύρην <span>[ῠ]</span>, <i>pf</i>. σέσυρμαι)</span><br><b>   I <i>tr. :</i><br>      1</b> tirer (un filet, un vêtement, <i>etc.) acc</i>. THCR. <i>Idyl. 2, 73 ;</i> PLUT. <i>M. 977</i> f ; DC. <i>46, 18 ; au pass</i>. CHRISTOD. <i>Ecphr. 91 ;</i> TRIPHIOD. <i>82 ;</i> ANTH. <i>9, 310 ;</i><br><b>      2</b> traîner de force, <i>acc</i>. THCR. <i>Idyl. 30, 12 ;</i> ANTH. <i>7, 152, etc. ;</i><br><b>      3</b> <i>en parl. de la mer, de cours d’eau,</i> charrier, entraîner, <i>acc</i>. ANTH. <i>7, 216 ; au pass. en parl. de pépites d’or,</i> STR. <i>146 ; de pers</i>. PLUT. <i>Mar. 23 ; avec idée de violence,</i> entraîner dans son cours, <i>acc</i>. PLUT. <i>M. 5</i> f ;<br><b>   II <i>intr</i>.<br>      1</b> ramper, LGS <i>3, 27 ;</i><br><b>      2</b> s’avancer avec effort, LYC. <i>217</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Act. prés. part. fém. dor</i>. σύροισα, THCR. <i>Idyl. 2, 73</i>.<br><span><b>Étym</b>. <i>R. indo-europ</i>. *tuer-, remuer ; <i>cf</i>. σαίρω².</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">συρω - σύρω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n5 fois dans 5 versets de 3 livres bibliques (NT)\n<ul>\n<li>Jean (1)</li>\n<li>Actes (3)</li>\n<li>Apocalypse (1)</li>\n</ul>\n</td></tr>\n</table>","G4952":"<h1>susparasso</h1>\n<p>Strong n° 4952 <i>Prononciation [soos-par-as'-so]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>convulser complètement, secouer, tourmenter</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>συ·σπαράσσω</b>, <i>att</i>. <b>-άττω</b> <span>[πᾰ]</span> mettre en pièces <i>ou simpl</i>. tourmenter en même temps, NT. <i>Luc. 9, 42</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">συ-σπαρασσω - συσπαράσσω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G4953":"<h1>sussemon</h1>\n<p>Strong n° 4953 <i>Prononciation [soos'-say-mon]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>un signe commun ou un signe convenu</li>\n<li>un signe donné selon un accord</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>σύσ·σημος, ος, ον</b>, marqué d’un signe convenu, <i>d’où subst</i>. <b>τὸ σύσσημον :<br>      1</b> signe <i>ou</i> signal convenu, NT. <i>Marc. 14, 44 ;</i> STR. <i>280 ;</i> DS. <i>11, 22 ;</i><br><b>      2</b> estampille <i>ou</i> poinçon public, STR. <i>708 ;</i><br><b>      3</b> <i>au plur</i>. insignes (du pouvoir) STR. <i>1, 70 ;</i><br><b>      4</b> signe convenu, signe de reconnaissance, gage, ANTH. <i>App. 32</i>.<br><span><b>Étym</b>. σύν, σῆμα.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">συσσημον - σύσσημον</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Marc (1)</li>\n</ul>\n</td></tr>\n</table>","G4954":"<h1>sussomos</h1>\n<p>Strong n° 4954 <i>Prononciation [soos'-so-mos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>appartenant au même corps</li>\n<li>métaph. à la même église</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>σύσ·σωμος, ος, ον</b>, uni en un seul corps, NT. <i>Eph. 3, 6</i>.<br><span><b>Étym</b>. σύν, σῶμα.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">συσσωμος - σύσσωμος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Ephésiens (1)</li>\n</ul>\n</td></tr>\n</table>","G4955":"<h1>sustasiastes</h1>\n<p>Strong n° 4955 <i>Prononciation [soos-tas-ee-as-tace']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>un compagnon d'insurrection, un camarade d'émeute, un émeutier</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>στασιαστής, οῦ (ὁ)</b> <span>[τᾰ]</span> factieux, DH. <i>6, 70 ;</i> JOS. <i>A.J. 14, 1, 3, etc</i>.<br><span><b>Étym</b>. στασιάζω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">συστασιαστης - στασιαστής</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Marc (1)</li>\n</ul>\n</td></tr>\n</table>","G4956":"<h1>sustatikos</h1>\n<p>Strong n° 4956 <i>Prononciation [soos-tat-ee-kos']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>de recommandation, d'éloge, de louange, d'introduction</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>συστατικός, ή, όν</b> <span>[ᾰ]</span> propre à donner de la consistance, <i>càd. :</i><br><b>      1</b> propre à unir, à resserrer, TH. <i>Sens. 84 ;</i> SEXT. <i>M. 8, 84 ;</i><br><b>      2</b> propre à faire accueillir, à recommander, ARSTT. (DL. <i>5, 18</i>) ; ἐπιστολὴ συστατική, NT. <i>2Cor. 3, 1 ; ou simpl</i>. ἡ συστατική, DL. <i>8, 87,</i> lettre de recommandation.<br><span>•<i> Cp</i>. -ώτερος, DL. <i>5, 18</i>.<br><span><b>Étym</b>. συνίστημι.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">συστατικος - συστατικός</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>2 Corinthiens (2)</li>\n</ul>\n</td></tr>\n</table>","G4957":"<h1>sustauroo</h1>\n<p>Strong n° 4957 <i>Prononciation [soos-tow-ro'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>crucifier avec</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>συ·σταυρόω-ῶ</b>, crucifier avec, <i>dat</i>. NT. <i>Marc. 15, 32 ; Gal. 2, 20</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">συσταυροω - συσταυρόω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n5 fois dans 5 versets de 5 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Marc (1)</li>\n<li>Jean (1)</li>\n<li>Romains (1)</li>\n<li>Galates (1)</li>\n</ul>\n</td></tr>\n</table>","G4958":"<h1>sustello</h1>\n<p>Strong n° 4958 <i>Prononciation [soos-tel'-lo]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>placer ensemble\n<ol type=\"a\">\n<li>tirer ensemble, mettre en contact\n<ol>\n<li>diminuer</li>\n<li>raccourcir, abréger</li>\n<li>le temps a été mis entre de brèves limites, il est court</li>\n</ol>\n</li>\n<li>rouler ensemble, enrouler, envelopper de bandages, etc., ensevelir</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>συ·στέλλω</b>, <i>anc. att</i>. <b>ξυ·στέλλω</b> <span>(<i>ao</i>. συνέστειλα, <i>pf</i>. συνέσταλκα ; <i>pass. ao.2</i> συνεστάλην, <i>pf</i>. συνέσταλμαι)</span><br><b>   I</b> rassembler, <i>d’où :</i><br><b>      1</b> refermer, replier : ἱστία, AR. <i>Ran. 999,</i> des voiles, <i>càd</i>. diminuer la surface des voiles, prendre des ris ; τὴν γλῶτταν, ARSTT. <i>P.A. 2, 17, 2,</i> la langue ;<br><b>      2</b> contracter : τὸ πρόσωπον, LUC. <i>D. mer. 13, 5,</i> le visage ; <i>au pass</i>. se contracter, se resserrer, ARSTT. <i>Mot. an. 7, 9, etc. ;</i> TH. <i>C.P. 1, 15, 1, etc. ;</i><br><b>      3</b> refouler : εἰς τὸ τεῖχος, PLUT. <i>Syll. 9,</i> dans l’enceinte des remparts ; <i>cf</i>. PLUT. <i>Per. 19, Cam. 34 ;</i><br><b>      4</b> restreindre, réduire, XÉN. <i>Vect. 4, 3 ;</i> DÉM. <i>309, 2, etc. ; au pass</i>. se restreindre : τῇ διαίτῃ, HPC. <i>Art. 817</i> c, pour le régime de vie ; σ. ἐς εὐτέλειαν, THC. <i>8, 4,</i> réduire les dépenses à une simplicité convenable ; σ. τι εἰς τὸ μέτριον, PLAT. <i>Leg. 691</i> e, réduire qqe ch. à la juste mesure ;<br><b>      5</b> déprimer, rabaisser, EUR. <i>fr. 724 ;</i> ISOCR. <i>176</i> a ; <i>joint à</i> ταπεινοῦν, PLAT. <i>Lys. 210</i> e ; <i>au pass</i>. être rabaissé, abattu, découragé, EUR. <i>H.f. 1417 ;</i> POL. <i>5, 15, 8 ;</i><br><b>      6</b> amoindrir, étriquer, DH. <i>Comp. 20 ;</i> φράσιν <i>ou</i> λέξιν, HERMOG. <i>3, 225 Walz</i> le style, la diction ;<br><b>      7</b> abréger, <i>particul</i>. prononcer une syllabe en l’abrégeant, <i>p. opp. à</i> ἐκτείνω, DH. <i>Comp. 14, etc. ;</i><br><b>   II</b> envelopper entièrement : τινὰ πέπλοις, EUR. <i>Tr. 378,</i> qqn d’un voile ; <i>cf</i>. LUC. <i>Im. 7 ;</i> NT. <i>Ap. 8, 6 ;</i><br><b><i>Moy.</i></b> s’envelopper de : θαἰμάτια, AR. <i>Eccl. 99,</i> de ses vêtements ; ἑαυτόν, AR. <i>Eccl. 484,</i> se ceindre les reins (pour l’action) ; συσταλείς, AR. <i>Vesp. 424, Lys. 1042,</i> qui a les reins ceints, <i>càd</i>. tout prêt.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">συστελλω - συστέλλω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Actes (1)</li>\n<li>1 Corinthiens (1)</li>\n</ul>\n</td></tr>\n</table>","G4959":"<h1>sustenazo</h1>\n<p>Strong n° 4959 <i>Prononciation [soos-ten-ad'-zo]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>gémir ensemble, soupirer ensemble</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>συ·στενάζω</b>, gémir avec, <i>dat</i>. EUR. <i>Ion 935 ; abs</i>. NT. <i>Rom. 8, 22</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">συστεναζω - συστενάζω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Romains (1)</li>\n</ul>\n</td></tr>\n</table>","G4960":"<h1>sustoicheo</h1>\n<p>Strong n° 4960 <i>Prononciation [soos-toy-kheh'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>se tenir ou marcher sur la même rangée (ou en file)\n<ol type=\"a\">\n<li>de soldats</li>\n<li>se tenir contre, être parallèle avec</li>\n<li>répondre à, ressembler à, correspondre\n<ol>\n<li>ainsi d'un type dans l'A.T. qui correspond à l'antitype dans le N.T., et y a trouvé son accomplissement</li>\n</ol>\n</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>συ·στοιχέω-ῶ :<br>      1</b> être sur le même rang, sur la même ligne, POL. <i>10, 21, 7 ;</i><br><b>      2</b> correspondre à, <i>dat</i>. NT. <i>Gal. 4, 25 ; d’où</i> être d’accord avec, MUSON. (STOB. <i>167, 12</i>).\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">συστοιχεω - συστοιχέω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Galates (1)</li>\n</ul>\n</td></tr>\n</table>","G4961":"<h1>sustratiotes</h1>\n<p>Strong n° 4961 <i>Prononciation [soos-trat-ee-o'-tace]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>un compagnon soldat, compagnon de combat</li>\n<li>un associé dans les labeurs et conflits pour la cause de Christ</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>συ·στρατιώτης, ου (ὁ)</b> <span>[ᾰ]</span> compagnon d’armes, XÉN. <i>An. 1, 2, 26 ; Hell. 2, 4, 20 ; 5, 3, 17 ;</i> PLAT. <i>Rsp. 556</i> c ; ARSTT. <i>Nic. 8, 9, 1</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">συστρατιωτης - συστρατιώτης</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Philippiens (1)</li>\n<li>Philémon (1)</li>\n</ul>\n</td></tr>\n</table>","G4962":"<h1>sustrepho</h1>\n<p>Strong n° 4962 <i>Prononciation [soos-tref'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>tordre ensemble, rouler ensemble</li>\n<li>collecter, combiner, unir\n<ol type=\"a\">\n<li>des hommes : les rassembler eux-mêmes, les assembler</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>συ·στρέφω :<br>   I</b> tourner une chose avec une autre <i>ou</i> sur elle-même, <i>d’où :</i><br><b>      1</b> rouler ensemble, envelopper dans un tourbillon, ESCHL. <i>fr. 195 ; cf</i>. AR. <i>Lys. 975, Th. 61 ;</i><br><b>      2</b> mettre en faisceau, <i>acc</i>. NT. <i>Ap. 28, 3 ;</i><br><b>      3</b> pelotonner, friser, crêper (des cheveux) THÉODECT. (STR. <i>695</i>) ;<br><b>      4</b> <i>en parl. d’animaux,</i> rassembler, ramasser : σ. ἰσχίον, ANTH. <i>5, 104,</i> tourner les hanches en marchant ; ἑαυτόν, PLAT. <i>Rsp. 336</i> b ; ARSTT. <i>H.A. 9, 48,</i> se ramasser sur soi-même ; σ. ἵππον, PLUT. <i>Pyrrh. 16,</i> rassembler un cheval ; <i>au pass</i>. κύων συστρεφόμενος, PLUT. <i>M. 157</i> b, chien ramassé sur soi-même ;<br><b>      5</b> grouper, unir : ἔθνος, HDT. <i>1, 101,</i> une nation ; σ. ἑωυτούς, HDT. <i>9, 18,</i> se former en troupe serrée, <i>en parl. de troupes ; au pass</i>. se grouper, HDT. <i>9, 62 ;</i> THC. <i>7, 30 ; en parl. de troupes,</i> se former en rangs serrés, THC. <i>2, 4 ;</i> XÉN. <i>Hell. 6, 4, 12, etc. ; en parl. des animaux qui se réunissent par troupes,</i> ARSTT. <i>H.A. 9, 37 et 42 ; fig</i>. s’unir, se concerter, se liguer, HDT. <i>6, 6 ;</i> THC. <i>4, 68 ; 8, 54 ;</i> ἐπί τινα, ESCHN. <i>52, 6,</i> contre qqn ;<br><b>      6</b> rassembler, condenser, épaissir, ATH. <i>41</i> b ; <i>joint à</i> πυκνοῦν, ANTYLL. <i>98 ; au pass</i>. se condenser, s’épaissir, HPC. <i>45, 18, 1254</i> f ; ARSTT. <i>Mund. 4 ;</i> σωμάτιον συνεστραμμένον, ARR. <i>Epict. 1, 24, 8,</i> petit corps compact, solide ;<br><b>      7</b> resserrer : ἐνθυμήματα, ARSTT. <i>Rhet. 3, 18 ; ou</i> νοήματα, DH. <i>Lys. 6, 13, etc</i>. ses pensées ; πρᾶγμα, CRAT. (<i>Com. fr. 2, 68</i>) exposer un fait sommairement, en termes concis ; συνεστραμμένη λέξις, DH. <i>Rhet. 5, 7,</i> style resserré, concis ; ῥῆμα συνεστραμμένον, PLAT. <i>Prot. 343</i> e, mot concis ; συνεστραμμένον τι ἔχειν, D. PHAL. <i>§ 177,</i> avoir qqe ch. de concis ; συνέστραπται τοῖς νοήμασι, DH. <i>Lys. 5,</i> il est bref, concis dans l’expression de ses pensées ;<br><b>   II</b> tourner <i>ou</i> exposer ensemble, <i>càd</i>. de suite, sans interruption (un récit) ANTIPH. (ATH. <i>449</i> d, <i>623</i> b).\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">συστρεφω - συστρέφω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G4963":"<h1>sustrophe</h1>\n<p>Strong n° 4963 <i>Prononciation [soos-trof-ay']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>de choses tortillées ensemble, liées ensemble</li>\n<li>une combinaison secrète, une coalition, une conspiration, un complot</li>\n<li>une affluence de personnes désordonnées, une émeute</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>συστροφή, ῆς (ἡ) :<br>   I</b> <i>act</i>. action de tourner <i>ou</i> de tordre ensemble, torsion d’ensemble, PLAT. <i>Pol. 282</i> e ;<br><b>   II</b> <i>pass</i>. toute chose agglomérée, <i>particul. :</i><br><b>      1</b> masse compacte : νεῶν, POL. <i>4, 34, 6,</i> de navires ; essaim d’abeilles, SPT. <i>Judith 14, 8 ;</i> troupe d’oiseaux, ARTÉM. <i>2, 20 ;</i><br><b>      2</b> troupe d’hommes, <i>particul</i>. troupe de soldats, HDT. <i>7, 9 ;</i> DH. <i>5, 31 ;</i> DS. <i>11, 8 ;</i> rassemblement séditieux, <i>d’où</i> rébellion, SPT. <i>4Reg. 15, 15 ; Amos 7, 10 ;</i> NT. <i>Ap. 23, 12, etc. ;</i><br><b>      3</b> averse de pluie, ouragan, trombe d’eau, POL. <i>3, 74, 5 ; 11, 24, 9 ;</i> SPT. <i>Hos. 4, 19 ;</i> CLÉM. <i>489, 30 ;</i><br><b>      4</b> nœud dans le bois, TH. <i>H.P. 5, 2, 3 ; 6, 5, 1 ;</i><br><b>      5</b> condensation <i>ou</i> dépôt d’humeurs, HPC. <i>Art. 807 ;</i> de callosités aux articulations, DIOSC. <i>1, 35, etc. ;</i><br><b>      6</b> condensation, densité, <i>en gén</i>. ARSTT. <i>Probl. 34, 7 ;</i><br><b>      7</b> concision, brièveté du style, DH. <i>Dem. 18, Thuc. 53 ;</i> D. PHAL. <i>§ 8</i>.<br><span><b>Étym</b>. συστρέφω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">συστροφη - συστροφή</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 1 livre biblique (NT)\n<ul>\n<li>Actes (2)</li>\n</ul>\n</td></tr>\n</table>","G4964":"<h1>suschematizo</h1>\n<p>Strong n° 4964 <i>Prononciation [soos-khay-mat-id'-zo]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>se conformer (c.à.d. son esprit et son caractère) au modèle d'un autre, (se façonner selon)</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>συ·σχηματίζω</b> <span>[ᾰ]</span> figurer <i>ou</i> façonner sur le modèle de, conformer, PLUT. <i>M. 83</i> b ; τι πρός τι, ARSTT. <i>Top. 6, 14, 4,</i> une ch. à une autre<br><i><b>Moy</b>. :</i><br><b>      1</b> se conformer à, se modeler sur : πρός τινα, PLUT. <i>M. 100</i> f, sur qqn ; πρός τι, <i>Num. 20,</i> sur qqe ch. ; τινι, NT. <i>Rom. 12, 2 ; 1Petr. 1, 14,</i> sur qqn <i>ou</i> qqe ch. ; <i>en parl. des orateurs, des acteurs,</i> RHÉT. <i>5, 610 W. ;</i><br><b>      2</b> <i>en parl. des astres,</i> prendre une position déterminée à l’égard les uns des autres, SEXT. <i>M. 5, 33 ;</i> PROCL. <i>Ptol. p. 18</i> b, <i>142</i> f.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">συσχηματιζω - συσχηματίζω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Synonymes</big></td></tr>\n<tr><td> – décrit ce qui est l'essence du caractère et ainsi ce qui est complet ou durable, pas simplement une forme ou un aperçu\n<br><br> – conformer une chose à une autre, le mot décrit ce qui est transitoire, changeable, et instable</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Romains (1)</li>\n<li>1 Pierre (1)</li>\n</ul>\n</td></tr>\n</table>","G4965":"<h1>Suchar</h1>\n<p>Strong n° 4965 <i>Prononciation [soo-khar']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Sychar = « ivresse »\n<ol><li>probablement un autre nom pour la ville de Sichem, une ville de Samarie, près du puits de Jacob</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Συχαρ</font> &lt; סוכר - <font face=\"Georgia\">Συχάρ</font>\n<br><br>Voir définition \t</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre de lieu</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Jean (1)</li>\n</ul>\n</td></tr>\n</table>","G4966":"<h1>Suchem</h1>\n<p>Strong n° 4966 <i>Prononciation [soo-khem']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Sichem (Angl. Shechem) = « épaule »\n<ol>\n<li>une ville d'Ephraïm (actuellement Naplouse)</li>\n<li>le fils d'Hémor</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Συχεμ</font> &lt; שכמה - <font face=\"Georgia\">Συχέμ</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre de lieu</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (2)</li>\n</ul>\n</td></tr>\n</table>","G4967":"<h1>sphage</h1>\n<p>Strong n° 4967 <i>Prononciation [sfag-ay']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>abattage, action d'égorger\n<ol type=\"a\">\n<li>de brebis destinées à la boucherie</li>\n<li>du jour de la destruction, du carnage</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>σφαγή, ῆς (ἡ)</b> <span>[ᾰ]</span><br><b>      1</b> égorgement, meurtre, immolation, EUR. <i>Hec. 571, 1037, etc. ; au plur</i>. ESCHL. <i>Eum. 187, etc. ;</i> SOPH. <i>El. 37, etc. ;</i> EUR. <i>Hec. 522, etc. ;</i> σφαγὰς ποιεῖσθαι, XÉN. <i>Hell. 4, 4, 2 ; ou</i> ποιεῖν, XÉN. <i>Hell. 2, 2, 6, etc</i>. égorger ; mets provenant d’un meurtre, ESCHL. <i>Ag. 1599 ;</i> égorgement d’une victime, SOPH. <i>Tr. 756, etc. ;</i><br><b>      2</b> <i>p. suite,</i> blessure, plaie, SOPH. <i>Tr. 573, etc. ;</i> EUR. <i>El. 1228 ;</i> αἵματος σφαγή, ESCHL. <i>Ag. 1389,</i> sang qui coule d’une blessure ;<br><b>      3</b> gorge, <i>particul</i>. endroit de la gorge où l’on frappe la victime, ANT. <i>137, 28 ; au plur</i>. ESCHL. <i>Pr. 863 ;</i> THC. <i>4, 48 ;</i> XÉN. <i>Cyn. 10, 16 ;</i> EUR. <i>Or. 291 ;</i> ARSTT. <i>H.A. 3, 2, 6</i>.<br><span><b>Étym</b>. σφάζω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">σφαγη - σφαγή</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 3 livres bibliques (NT)\n<ul>\n<li>Actes (1)</li>\n<li>Romains (1)</li>\n<li>Jacques (1)</li>\n</ul>\n</td></tr>\n</table>","G4968":"<h1>sphagion</h1>\n<p>Strong n° 4968 <i>Prononciation [sfag'-ee-on]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>ce qui est destiné à l'abattage, une victime</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>σφάγιον, ου (τὸ)</b> <span>[ᾰ]</span><br><b>      1</b> victime pour un sacrifice, EUR. <i>Hec. 108, 119 ; Or. 842, etc. ; en prose,</i> DÉM. <i>1398, 7 ; au plur</i>. HDT. <i>9, 41, 45 ;</i> ESCHL. <i>Sept. 230 ;</i> THC. <i>6, 69 ; etc. ;</i> τὰ σφάγια ἐγίνετο καλά, HDT. <i>112,</i> les victimes donnaient des signes favorables, XÉN. <i>An. 1, 8, 15 ;</i> ESCHL. <i>Sept. 379 ;</i> HDT. <i>9, 61 ;</i><br><b>      2</b> <i>p. suite,</i> sacrifice, EUR. <i>Hec. 137 ; Or. 658, 811</i>.<br><span><b>Étym</b>. σφάγιος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">σφαγιον - σφάγιον</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G4969":"<h1>sphazo</h1>\n<p>Strong n° 4969 <i>Prononciation [sfad'-zo]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>tuer, abattre, un boucher</li>\n<li>mettre à mort par violence</li>\n<li>blessé mortellement</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>σφάζω</b>, <i>néo-att</i>. <b>σφάττω</b> <span>(<i>impf</i>. ἔσφαζον, <i>f</i>. σφάξω, <i>ao</i>. ἔσφαξα, <i>pf. inus., pl.q.pf</i>. ἐσφάκειν ; <i>pass. f</i>. σφαγήσομαι, <i>ao</i>. ἐσφάχθην, <i>ao.2</i> ἐσφάγην, <i>pf</i>. ἔσφαγμαι)</span><br><b>      1</b> égorger une victime (<i>dans Hom. touj</i>. une brebis <i>ou</i> un bœuf, <i>etc</i>.) IL. <i>9, 467 ;</i> OD. <i>1, 92 ; 4, 320 ; 9, 46 ; 23, 305 ; cf</i>. XÉN. <i>An. 2, 2, 9 ; postér</i>. un animal quelconque <i>ou</i> même une victime humaine, PD. <i>P. 11, 36 ;</i> ESCHL. <i>Ag. 1433, etc. ;</i> SOPH. <i>Aj. 236, 299 ;</i> EUR. <i>Ph. 913, etc. ;</i> Γῇ, XÉN. <i>Cyr. 8, 3, 24,</i> immoler une victime à la Terre ; <i>particul</i>. enfoncer le couteau dans la gorge de la victime (pour recueillir son sang) IL. <i>1, 459, etc. ;</i> σφ. τινὰ ἐς τὸν κρητῆρα, HDT. <i>3, 11,</i> recueillir dans le cratère le sang de la victime égorgée ;<br><b>      2</b> égorger <i>ou</i> tuer avec un couteau <i>ou</i> une épée, HDT. <i>5, 27 ; 7, 107 ;</i> ESCHL. <i>Ch. 904 ; en gén</i>. XÉN. <i>An. 4, 5, 10 ;</i> THC. <i>2, 92 ;</i> PLAT. <i>Euthyd. 301</i> c ;<br><b>      3</b> égorger, <i>en gén., en parl. des loups qui égorgent les brebis,</i> ARSTT. <i>H.A. 9, 6, 9</i>.<br><span><b>Étym</b>. <i>p.-ê. pré-grec</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">σφαζω - σφάζω</font>\n<br><br>un verbe primaire</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n10 fois dans 9 versets de 2 livres bibliques (NT)\n<ul>\n<li>1 Jean (2)</li>\n<li>Apocalypse (8)</li>\n</ul>\n</td></tr>\n</table>","G4970":"<h1>sphodra</h1>\n<p>Strong n° 4970 <i>Prononciation [sfod'-rah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>extrêmement, grandement</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>σφόδρα</b> <span>[ᾰ]</span> <i>adv. :</i><br><b>      1</b> fortement, avec véhémence, PD. <i>N. 4, 61 ;</i> HDT. <i>9, 17 ;</i> SOPH. <i>El. 1053 ;</i> ANT. <i>143, 12 ; subst</i>. τὸ σφ. PLAT. <i>Conv. 210</i> b, la véhémence ;<br><b>      2</b> <i>en mauv. part,</i> sévèrement, durement, THC. <i>3, 46 ;</i><br><b>      3</b> <i>en b. part,</i> avec une précision rigoureuse (définir) PLAT. <i>Phædr. 263</i> d ;<br><b>      4</b> <i>en gén</i>. très, fort, tout à fait, ATT. ; <i>avec un adj</i>. σφ. ἄδικος, PLAT. <i>Rsp. 361</i> a, tout à fait injuste ; <i>après l’adj</i>. ARSTT. <i>Meteor. 2, 3, 35, etc. ; avec un subst</i>. τὴν σφ. φιλίαν, PLAT. <i>Leg. 731</i> e, l’amitié profonde ; <i>cf</i>. PLAT. <i>Leg. 952</i> c, <i>etc. ; avec un adv. :</i> μάλα σφ. PLAT. <i>1 Alc. 124</i> d, tout à fait, très fort ; πάνυ σφ. AR. <i>Pl. 25, etc. ;</i> σφ. πάνυ, ESCHN. <i>33, 4 ;</i> πάνυ καὶ σφ. PLAT. <i>Leg. 627</i> a, <i>m. sign. ; particul. dans les réponses :</i> σφ. γε, ATT. oui certes ; καὶ σφ. γε, ATT. <i>m. sign. ;</i> πάνυ σφ. PLAT. <i>Ap. 25</i> a, <i>26</i> b ; πάνυ γε σφ. PLAT. <i>Men. 82</i> b, certes tout à fait ; οὔπω σφ. PLAT. <i>1 Alc. 123</i> d, pas du tout ; οὐ σφ. HPC. <i>p. 290, 23 ; 291, 53,</i> non tellement, <i>càd</i>. peu <i>ou</i> rarement.<br><span><b>Étym</b>. <i>plur. neutre de</i> σφοδρός, <i>avec chang. d’accent</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">σφοδρα - σφόδρα</font>\n<br><br>neutre pluriel de sphodros (violent) comme adverbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adverbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n11 fois dans 11 versets de 5 livres bibliques (NT)\n<ul>\n<li>Matthieu (7)</li>\n<li>Marc (1)</li>\n<li>Luc (1)</li>\n<li>Actes (1)</li>\n<li>Apocalypse (1)</li>\n</ul>\n</td></tr>\n</table>","G4971":"<h1>sphodros</h1>\n<p>Strong n° 4971 <i>Prononciation [sfod-roce']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>extrêmement, fortement</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>σφοδρῶς</b>, <i>adv</i>., avec véhémence, avec force, OD. <i>12, 124 ;</i> XÉN. <i>Œc. 1, 21, etc. ;</i> PLAT. <i>Ap. 23</i> e, <i>etc</i>.<br><span>•<i> Cp</i>. -ότερον, TH. <i>C.P. 5, 10, 1 ; ou</i> -οτέρως, TH. <i>C.P. 5, 9, 13</i>. <i>• Sup</i>. -ότατον, XÉN. <i>Eq. 12, 13</i>.<br><span><b>Étym</b>. σφοδρός.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">σφοδρως - σφοδρῶς</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adverbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G4972":"<h1>sphragizo</h1>\n<p>Strong n° 4972 <i>Prononciation [sfrag-id'-zo]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>mettre un sceau dessus, marquer d'un sceau, sceller\n<ol type=\"a\">\n<li>pour la sûreté : de Satan</li>\n<li>puisque les choses scellées sont cachées (comme le contenu d'une lettre) : cacher, garder au silence, tenir secret</li>\n<li>dans le but de marquer une personne ou une chose\n<ol>\n<li>poser une marque par l'impression d'un sceau ou un timbre</li>\n<li>il est dit que les anges sont scellés par Dieu</li>\n</ol>\n</li>\n<li>dans le but de prouver, confirmer, ou attester une chose\n<ol>\n<li>confirmer l'authenticité, mettre hors de doute\n<ol type=\"a\">\n<li>d'un document écrit</li>\n<li>prouver par un témoignage qu'une personne est bien ce qu'elle affirme être</li>\n</ol>\n</li>\n</ol>\n</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>σφραγίζω</b> <span>[ᾱ]</span><br><b>   I</b> sceller, marquer d’un sceau, <i>acc</i>. EUR. <i>I.A. 38 ; d’où en gén</i>. déposer une empreinte, <i>au pass</i>. être déposé sous forme d’empreinte ; <i>fig. :</i><br><b>      1</b> sceller (les lèvres), rendre muet, NONN. <i>D. 26, 261 ;</i><br><b>      2</b> sceller, <i>càd</i>. mettre fin à, <i>acc</i>. THÉODOT. <i>Dan. 9, 24 ;</i><br><b>   II</b> marquer d’une empreinte, <i>en gén. au pass. en poésie,</i> EUR. <i>I.T. 1372 ;</i> ANTH. <i>5, 35, etc. ; p. ext. :</i><br><b>      1</b> marquer d’un signe, délimiter, fixer, déterminer, <i>p. suite,</i> consolider, confirmer, ANTH. <i>9, 236 ; avec</i> ὅτι, NT. <i>Joh. 3, 33 ;</i><br><b>      2</b> marquer du signe de la croix, faire le signe de la croix, ECCL. ;<br><b><i>Moy.</i></b> :<br><b>      1</b> marquer de son sceau, sceller, ARSTT. <i>Mem. 1, 10 ;</i> PLUT. <i>Pomp. 5 ;</i><br><b>      2</b> <i>fig</i>. enfermer, limiter, <i>acc</i>. ANTH. <i>9, 297 ; cf</i>. confirmer, SEXT. <i>M. 1, 271 ; d’où</i> assurer, NT. <i>Rom. 15, 28, 3 ;</i> ARCHÉL. (A. CARYST. <i>96</i>).<br><span><b><span class=\"arrow\"></span></b> <i>Ion</i>. σφρηγίζω, NONN. <i>D. l. c</i>.<br><span><b>Étym</b>. σφραγίς.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">σφραγιζω - σφραγίζω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n27 fois dans 17 versets de 6 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Jean (2)</li>\n<li>Romains (1)</li>\n<li>2 Corinthiens (2)</li>\n<li>Ephésiens (2)</li>\n<li>Apocalypse (19)</li>\n</ul>\n</td></tr>\n</table>","G4973":"<h1>sphragis</h1>\n<p>Strong n° 4973 <i>Prononciation [sfrag-ece']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>un sceau\n<ol type=\"a\">\n<li>le sceau placé sur des livres</li>\n<li>un cachet</li>\n<li>l'inscription ou impression faite par un sceau\n<ol>\n<li>du nom de Dieu et Christ marqué sur les fronts</li>\n</ol>\n</li>\n<li>ce par quoi une chose est confirmée, prouvée, authentifiée comme par un sceau (un témoignage ou preuve)</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>σφραγίς, ῖδος</b>, <i>postér</i>. <b>ίδος (ἡ)</b> <span>[ᾱῑ, <i>postér</i>. ῐ, <i>v. ci-dessous</i>]</span><br><b>   I</b> sceau, <i>particul</i>. cachet, anneau pour cacheter, HDT. <i>1, 195, etc. ;</i> AR. <i>Av. 560, etc. ;</i> PLAT. <i>Hipp. ma. 368</i> c, <i>etc. ;</i> POL. <i>24, 4, 10 ;</i><br><b>   II</b> empreinte, <i>càd. :</i><br><b>      1</b> signe gravé sur un cachet, STR. <i>416 ;</i><br><b>      2</b> empreinte d’un cachet sur une lettre, SOL. (DL. <i>1, 57</i>) ; THC. <i>1, 129, 132 ;</i> XÉN. <i>Hell. 7, 1, 39 ;</i> SOPH. <i>Tr. 615, etc. ;</i> EUR. <i>I.A. 155, etc. ;</i><br><b>      3</b> marque quelconque, signe, cicatrice, LYC. <i>780 ;</i> tâche <i>ou</i> moucheture de la peau, OPP. <i>C. 2, 299 ;</i><br><b>      4</b> signe pour marquer les mesures sur les cartes de géographie, STR. <i>78, 84 ;</i><br><b>      5</b> signe de la croix, ECCL. ;<br><b>   III</b> matière servant à faire des cachets :<br><b>      1</b> pierre précieuse que l’on gravait, HDT. <i>7, 69 ;</i> ARSTT. <i>Meteor. 4, 9, 30, etc. ;</i> TH. <i>Lap. 44, etc. ; d’où</i> pierre précieuse, <i>en gén</i>. LUC. <i>Ind. 2 ;</i><br><b>      2</b> argile de Lemnos propre à recevoir des empreintes, ARÉT. <i>Cur. m. acut. 2, 2</i>.<br><span><b><span class=\"arrow\"></span></b> <span>[ῐ]</span> ANTH. <i>10, 42 ;</i> NAZ. <i>Carm. 48, 207. Ion</i>. σφρηγίς, THGN. <i>19 ;</i> ORPH. <i>H. 34, 26, etc. ;</i> HDT. OPP. <i>ll. cc</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">σφραγις - σφραγίς</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n16 fois dans 16 versets de 4 livres bibliques (NT)\n<ul>\n<li>Romains (1)</li>\n<li>1 Corinthiens (1)</li>\n<li>2 Timothée (1)</li>\n<li>Apocalypse (13)</li>\n</ul>\n</td></tr>\n</table>","G4974":"<h1>sphuron</h1>\n<p>Strong n° 4974 <i>Prononciation [sfoo-ron']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>la cheville, le talon</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>σφυρόν, οῦ (τὸ)</b> <span>[ῠ]</span><br><b>   I</b> cheville du pied, IL. <i>4, 147, 518 ; 6, 117 ; 17, 290 ; 22, 397 ;</i> EUR. <i>Ph. 26 ;</i> AR. <i>Ach. 1179 ; en parl. d’un cheval,</i> EUR. <i>I.A. 225 ;</i><br><b>   II</b> <i>p. ext</i>. talon, <i>d’où</i> pied, PD. <i>I. 7, 19 ;</i> EUR. <i>Alc. 586 ;</i> OPP. <i>C. 3, 143 ; fig. :</i><br><b>      1</b> pied d’une montagne, PD. <i>P. 2, 85 ;</i> ANTH. <i>6, 114 ; 7, 501 ;</i> A. LIB. <i>8 ;</i><br><b>      2</b> extrémité d’un pays, d’une île, <i>etc</i>. THCR. <i>Idyl. 16, 77 ;</i> MUS. <i>45 ;</i> NONN. <i>D. 2, 1</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">σφυρον - σφυδρόν</font>\n<br><br>vient d'un dérivé venant probablement du même mot que sphaira (une balle, « sphère », voir le féminin sphura, un marteau)</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G4975":"<h1>schedon</h1>\n<p>Strong n° 4975 <i>Prononciation [skhed-on']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>proche, près de</li>\n<li>très proche, presque, environ</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>σχεδόν</b>, <i>adv. litt</i>. en tenant à, <i>d’où</i> proche, près :<br><b>   I</b> <i>avec idée de lieu :</i><br><b>      1</b> <i>sans mouv</i>. IL. <i>5, 458, etc. ; avec un dat</i>. νῆσοι σχ. ἀλλήλῃσι, IL. <i>9, 23,</i> îles rapprochées les unes des autres ; τύμϐῳ σχ. PD. <i>N. 10, 123,</i> près d’un tombeau ; <i>d’ord. avec le gén</i>. σχ. ἔγχεος, IL. <i>20, 363,</i> près d’une javeline ; <i>après son rég. :</i> γαίης σχ. OD. <i>5, 288,</i> près de la terre ;<br><b>      2</b> <i>avec mouv</i>. σχ. ἐλθεῖν τινι, IL. <i>9, 304,</i> venir près de qqn ; <i>cf</i>. HÉS. <i>Sc. 435 ; avec le gén</i>. OD. <i>4, 439 ; 11, 481 ; fig</i>. proche par le sang, OD. <i>10, 441 ;</i><br><b>   II</b> <i>avec idée de temps :</i> θάνατος δή τοι σχ. ἐστιν, IL. <i>17, 202,</i> la mort est près de toi ; <i>cf</i>. OD. <i>2, 284 ; 6, 27 ; suivi d’un relat. :</i> σοὶ φημὶ σχ. ἔμμεναι ὁππότε, <i>etc</i>. IL. <i>13, 817,</i> je te dis que le temps est proche où, <i>etc. ;</i><br><b>   III</b> <i>postér. avec idée de degré :</i><br><b>      1</b> à peu près, presque, <i>avec un pron. :</i> σχ. τι ταὐτά, PLAT. <i>Parm. 128</i> b, à peu près les mêmes ; σχ. τι τοιαῦτα, PLAT. <i>Conv. 201</i> e ; σχ. τι ταῦτα, PLAT. <i>Gorg. 412</i> c, à peu près semblables ; <i>avec un verbe exprimant l’idée de dire ou de savoir :</i> σχ. εἴρηκα ἃ νομίζω συμφέρειν, DÉM. <i>38, 27,</i> j’ai dit à peu près ce que je crois utile ; σχ. ἐπίσταμαι, SOPH. <i>Tr. 43,</i> je sais à peu près, <i>etc. avec un verbe en gén</i>. SOPH. <i>Ant. 470, etc. ;</i><br><b>      2</b> un peu : σχ. πρόσθεν, SOPH. <i>O.R. 736,</i> peu avant ;<br><b>      3</b> peut-être, DIUS (STOB. <i>Fl. 65, 17</i>) ; σχ. ἴσως, PLAT. <i>Soph. 253</i> c, <i>etc. ;</i> σχ. που, DS. <i>Exc. 537, 51,</i> peut-être ; <i>avec ironie :</i> σχ. τι τὴν σὴν οὐ καταισχύνω φύσιν, SOPH. <i>El. 608,</i> je pense que je ne fais pas honte à mon origine (au sang que j’ai reçu de toi) ; σχ. ἔχω ὃ εἰπὼν ἀναγκάσω σε λέγειν, PLAT. <i>Phædr. 236</i> d, je pense avoir un argument au moyen duquel je te forcerai à parler ; <i>dans les réponses :</i> peut-être, précisément, PLAT. <i>Soph. 250</i> c, <i>255</i> c, <i>etc</i>.<br><span><b>Étym</b>. ἔχω, -δον.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">σχεδον - σχεδόν</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adverbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 2 livres bibliques (NT)\n<ul>\n<li>Actes (2)</li>\n<li>Hébreux (1)</li>\n</ul>\n</td></tr>\n</table>","G4976":"<h1>schema</h1>\n<p>Strong n° 4976 <i>Prononciation [skhay'-mah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>l'ensemble, comprenant tout ce qui dans une personne frappe les sens, le visage, le port, le discours, les actions, la manière de vivre etc.</li>\n<li>aspect, dessin, figure, silhouette, les dehors</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>σχῆμα, ατος (τὸ) :<br>   I</b> manière d’être, <i>d’où :</i><br><b>      1</b> forme, figure, extérieur <i>d’une personne,</i> ESCHL. <i>Sept. 489 ;</i> EUR. <i>Med. 1071, etc. ;</i> HPC. <i>17, 40, etc. ; d’un animal,</i> XÉN. <i>Eq. 1, 8 ; 7, 10, etc. ; d’une chose (de la bouche,</i> ARSTT. <i>Poet. 20, 4 ; du visage,</i> ARSTT. <i>Poet. 10, 27, 4 ; d’un rocher,</i> SOPH. <i>Ph. 952 ; d’une armée rangée en bataille,</i> XÉN. <i>An. 1, 10, 10) ; fig</i>. σχ. πόλεως, THC. <i>6, 89 ;</i> πολιτείας, PLAT. <i>Pol. 291</i> d, forme de l’État, constitution politique ; σχ. νούσου, HPC. <i>Epid. 6, 8, 43,</i> forme d’une maladie ;<br><b>      2</b> <i>p. suite,</i> attitude extérieure, manière d’être extérieure, maintien : τύραννον σχῆμα ἔχειν, SOPH. <i>Ant. 1169,</i> avoir l’air d’un roi ; ταπεινὸν σχ. XÉN. <i>Cyr. 5, 1, 15,</i> air humble ; ὑπηρέτου σχ. DÉM. <i>690, 21,</i> air d’un serviteur ; <i>au plur</i>. attitudes du corps, gestes, XÉN. <i>Conv. 9, 5 ; Mem. 3, 10, 5 ; joint à</i> ὄμμασι καὶ βαδίσματι, XÉN. <i>Ap. 27 ;</i> σχήματα λέξεως, ARSTT. <i>Poet. 19, 7,</i> caractères extérieurs du discours, <i>càd</i>. exposition du discours par le débit et le geste ; σχήματα κωμῳδίας, ARSTT. <i>Poet. 4, 12,</i> forme caractéristique de la comédie ; σχῆμα λέξεως ἔμμετρον, ARSTT. <i>Rhet. 3, 8,</i> forme métrique de l’expression ; <i>abs</i>. figure géométrique, ARSTT. <i>An. 2, 3, 5, etc. ;</i> figure de rhétorique, PLAT. <i>Ion 536</i> c ; CIC. <i>Brut. 37, etc. ; t. de log</i>. figure du syllogisme, ARSTT. <i>An. pr. 1, 22, etc. ; p. ext</i>. ἐν σχήματι, selon la forme, à la façon de : ἐν τείχους σχήματι, HDN <i>2, 11, 16,</i> à la façon d’un mur ; ἐν σχήματι πατρός τε καὶ μητρός, PLAT. <i>Leg. 859</i> a, à la façon d’un père et d’une mère : ἐν σχήματι νόμου, PLAT. <i>Leg. 718</i> b, en forme de loi ;<br><b>      3</b> <i>particul</i>. maintien imposant, extérieur grave, LUC. <i>D. mort. 10, 8, etc. ; d’où</i> noblesse, dignité, ALCIPHR. <i>1, 34 ;</i> κατὰ σχῆμα, POL. <i>3, 85, 9, etc. ;</i> PLUT. <i>M. 44</i> a, <i>etc</i>. avec bienséance, avec dignité, dignement ; <i>p. suite,</i> magnificence, éclat, EUR. <i>Alc. 911, Hec. 619, Andr. 1 ;</i> PLAT. <i>Leg. 685</i> c ; <i>d’où</i> rang élevé, POL. <i>3, 85, 9, etc. ;</i><br><b>      4</b> habillement, costume, XÉN. <i>Cyr. 5, 1, 5 ; Œc. 2, 4 ;</i> AR. <i>Ach. 64, Eq. 1331 ;</i> THCR. <i>Idyl. 10, 35 ;</i><br><b>      5</b> maintien, posture, position, <i>en gén</i>. HPC. <i>Off. 744 ; particul</i>. attitude d’un athlète, ISOCR. <i>Antid. § 183 ;</i> maintien, position d’un danseur, figure de danse, AR. <i>Vesp. 1485 ;</i> PLAT. <i>Leg. 669</i> d ; <i>au plur</i>. figures, poses, gestes, EUR. <i>Cycl. 221 ;</i> AR. <i>Pax 323 ;</i> XÉN. <i>Conv. 2, 15 ; 7, 5 ; 16, 22 ;</i><br><b>   II</b> extérieur, <i>p. opp. à l’intérieur, càd</i>. apparence, <i>d’où :</i><br><b>      1</b> simple apparence, forme sans réalité, ombre, EUR. <i>Eol. 25, 3 Nauck ;</i><br><b>      2</b> figure <i>ou</i> attitude de convention, rôle d’acteur, rôle, PLAT. <i>1 Alc. 135</i> d ;<br><b>      3</b> faux-semblant, prétexte, PLAT. <i>Epin. 989</i> a ; PLUT. <i>Dio. 16, Galb. 16</i>.<br><span><b>Étym</b>. σχεῖν, <i>v</i>. ἔχω ; <i>cf. lat</i>. habēre <i>et</i> habitus.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">σχημα - σχῆμα</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>1 Corinthiens (1)</li>\n<li>Philippiens (1)</li>\n</ul>\n</td></tr>\n</table>","G4977":"<h1>schizo</h1>\n<p>Strong n° 4977 <i>Prononciation [skhid'-zo]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>se fendre, se casser en morceaux, se déchirer</li>\n<li>diviser par déchirure</li>\n<li>partager en fractions, être divisé</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>σχίζω</b> <span>(<i>f</i>. σχίσω, <i>ao</i>. ἔσχισα <span>[ῐ]</span>, <i>pf. inus. ; pass. ao</i>. ἐσχίσθην, <i>pf</i>. ἔσχισμαι)</span> fendre, séparer en fendant :<br><b>      1</b> <i>avec idée de violence :</i> σχ. δώδεκα μοίρας, HH. <i>Merc. 128,</i> fendre douze parts, <i>càd</i>. diviser qqe ch. en douze parts ; σχ. ῥινὸν ὀνύχεσσι, HÉS. <i>Sc. 428,</i> déchirer la peau avec ses griffes, <i>en parl. d’un lion ;</i> κάρα πελέκει, SOPH. <i>El. 98,</i> fendre la tête d’un coup de hache ; ξύλα, XÉN. <i>Cyr. 5, 3, 49,</i> fendre du bois ; νῶτον γᾶς, PD. <i>P. 4, 407,</i> fendre le dos de la terre, <i>en parl. du laboureur ;</i> ἱμάτιον, NT. <i>Luc. 5, 36,</i> déchirer un vêtement ; <i>au pass</i>. σχιζόμενοι τοὺς χιτῶνας, SPT. <i>Esaï. 36, 22,</i> qui ont leurs tuniques déchirées en deux ; πρῷρα σχίζει τὸ κῦμα, LUC. <i>Am. 6,</i> la proue fend le flot ;<br><b>      2</b> <i>sans idée de violence :</i> fendre, séparer, partager en deux : Νεῖλος σχ. μέσην Αἴγυπτον, HDT. <i>2, 17,</i> le Nil partage l’Égypte en deux moitiés ; Ἴστρος σχ. ῥοόν, A. RH. <i>4, 325,</i> l’Ister sépare son cours en deux bras ; σχίζειν τὸ γάλα, DIOSC. <i>2, 77,</i> faire cailler le lait, <i>càd</i>. faire que le petit-lait se sépare des grumeaux ; <i>au pass</i>. se fendre, se séparer, se diviser, <i>en parl. d’une route,</i> HDT. <i>7, 31 ; de cours d’eau,</i> PLAT. <i>Tim. 21</i> e ; A. RH. <i>4, 291, 312 ; de plantes et d’arbres dont les rejetons se divisent en branches, rameaux, etc</i>. TH. <i>H.P. 1, 1, 9, etc. ;</i> ἡ στρατιὴ ἐσχίζετο, l’armée se divisa, HDT. <i>8, 34 ; fig</i>. ἐσχίζοντό σφεων αἱ γνῶμαι, HDT. <i>7, 219,</i> leurs opinions se partageaient, ils étaient divisés dans leurs décisions ; <i>cf</i>. XÉN. <i>Conv. 4, 59 ;</i> NT. <i>Ap. 14, 4 ; 23, 7 ;</i> Νεῖλος σχίζεται τριφασίας ὁδούς, HDT. <i>2, 17,</i> le Nil se partage en trois bras ; φύλλα ἐσχισμένα εἰς πέντε μοίρας, DIOSC. <i>4, 41,</i> feuilles séparées en cinq parties.<br><span><b><span class=\"arrow\"></span></b> <i>Ao. épq. 3 sg</i>. σχίσσε, PD. <i>N. 9, 59</i>.<br><span><b>Étym</b>. <i>R. indo-europ</i>. *skid-, couper, fendre, séparer ; <i>cf. lat</i>. scindō, <i>sscr</i>. chinádmi.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">σχιζω - σχίζω</font>\n<br><br>apparemment un verbe primaire</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n10 fois dans 9 versets de 5 livres bibliques (NT)\n<ul>\n<li>Matthieu (2)</li>\n<li>Marc (2)</li>\n<li>Luc (2)</li>\n<li>Jean (2)</li>\n<li>Actes (2)</li>\n</ul>\n</td></tr>\n</table>","G4978":"<h1>schisma</h1>\n<p>Strong n° 4978 <i>Prononciation [skhis'-mah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>une déchirure</li>\n<li>métaph. une division, une dissension</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>σχίσμα, ατος (τὸ)</b> fente, séparation, ARSTT. <i>H.A. 2, 1, 26 ; en parl. de feuilles,</i> TH. <i>H.P. 3, 11, 1 ; fig</i>. scission, dissentiment, NT. <i>Joh. 9, 16 ; d’où</i> schisme, ECCL.<br><span><b>Étym</b>. σχίζω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">σχισμα - σχίσμα</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n8 fois dans 8 versets de 4 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Marc (1)</li>\n<li>Jean (3)</li>\n<li>1 Corinthiens (3)</li>\n</ul>\n</td></tr>\n</table>","G4979":"<h1>schoinion</h1>\n<p>Strong n° 4979 <i>Prononciation [skhoy-nee'-on]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>une corde ou cordage fait de joncs</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>σχοινίον, ου (τὸ) :<br>      1</b> corde de jonc tressé, corde, cordage, HDT. <i>1, 26 ; 5, 85, 86, etc. ;</i> AR. <i>Pax 299, 437 ; Ach. 22 ; particul</i>. câble, AR. <i>Pax 36 ;</i> DÉM. <i>1145, 6 ;</i><br><b>      2</b> chaîne d’arpentage, MATH. <i>p. 310 ;</i> SPT. <i>2Reg. 8, 2 ; fig</i>. chaîne, enchaînement, suite non interrompue, PD. <i>fr. 248 (124) Bgk ;</i><br><b>      3</b> <i>p. suite</i> lot de terre mesuré au cordeau, <i>d’où</i> part, portion, SPT. <i>Ps. 15, 6 ;</i><br><b>      4</b> le membre viril, AR. <i>Vesp. 1342</i>.<br><span><b>Étym</b>. σχοῖνος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">σχοινιον - σχοινίον</font>\n<br><br>diminutif de schoinos (un jonc)</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Jean (1)</li>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G4980":"<h1>scholazo</h1>\n<p>Strong n° 4980 <i>Prononciation [skhol-ad'-zo]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>cesser le labeur, flâner</li>\n<li>être libéré de travail, être en loisir, être désœuvré\n<ol type=\"a\">\n<li>avoir du loisir pour une chose</li>\n<li>se donner à une chose</li>\n</ol>\n</li>\n<li>de choses\n<ol type=\"a\">\n<li>de lieux : être inoccupé, vide</li>\n<li>de la fonction vacante d'un centenier</li>\n<li>d'une fonction ecclésiastique vacante</li>\n<li>de fonctionnaires sans charge</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>σχολάζω</b> <span>(<i>ao</i>. ἐσχόλασα, <i>pf</i>. ἐσχόλακα)</span><br><b>   I</b> avoir <i>ou</i> prendre du loisir, être oisif, inoccupé :<br><b>      1</b> <i>abs</i>. ESCHL. <i>Suppl. 207, etc. ;</i> EUR. <i>Hec. 730, etc. ;</i> tarder, différer, ESCHL. <i>Suppl. 883 ;</i><br><b>      2</b> <i>avec un inf</i>. avoir le loisir de, XÉN. <i>Cyr. 2, 1, 9 ; 8, 1, 18 ;</i> PLAT. <i>Leg. 763</i> d, <i>etc. ;</i><br><b>      3</b> <i>avec un rég. d’éloignement :</i> τινός, PLUT. <i>Nic. 2, 8 ;</i> ἀπό τινος, XÉN. <i>Cyr. 7, 5, 52,</i> se reposer de qqe occupation ;<br><b>      4</b> <i>avec un rég. de tendance,</i> consacrer son loisir à : πρός τι, XÉN. <i>Mem. 3, 6, 6 ;</i> τινί, DÉM. <i>594, 16 ;</i> LUC. <i>Macr. 4 ; V.H. 2, 15, etc. ;</i> πρός τινι, ARSTT. <i>Pol. 5, 8, 16 ;</i> ἐπί τινος, ARSTT. <i>P.A. 4, 5, 61 ;</i> περί τι, PLUT. <i>Brut. 22,</i> à qqe ch. ; <i>avec un rég. de pers. :</i> τινί, XÉN. <i>Cyr. 7, 5, 39 ;</i> πρός τινα, PLUT. <i>Num. 14,</i> à qqn, <i>càd</i>. fréquenter qqn, entretenir des relations amicales avec qqn ; <i>particul</i>. être auditeur <i>ou</i> disciple de qqn, XÉN. <i>Conv. 4, 44 ; ou au contr</i>. être le maître de qqn, tenir école, faire des cours, des conférences, DH. <i>Amm. 1, 5 ;</i> PLUT. <i>Dem. 5 ; au pass</i>. SEXT. <i>M. 11, 167 ;</i><br><b>   II</b> <i>en parl. de choses,</i> être vacant : τόπος σχολάζων, PLUT. <i>C. Gracch. 12,</i> lieu vide ; καθέδρα σχολάζουσα, JUL. <i>Cæs. 316</i> c, chaire vacante.<br><span><b>Étym</b>. σχολή.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">σχολαζω - σχολάζω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>1 Corinthiens (1)</li>\n</ul>\n</td></tr>\n</table>","G4981":"<h1>schole</h1>\n<p>Strong n° 4981 <i>Prononciation [skhol-ay']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>libération du labeur</li>\n<li>un lieu où l'on a du loisir pour toute chose, une école</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>σχολή, ῆς (ἡ) :<br>A</b> <i>subst. : propr</i>. arrêt, <i>d’où :</i><br><b>   I</b> repos, loisir, PD. <i>N. 10, 85 ;</i> HDT. <i>3, 134 ;</i> ATT. ; σχολὴν ἔχειν, XÉN. <i>Cyr. 7, 5, 42 et 52 ;</i> EUR. <i>Andr. 732,</i> avoir du loisir ; σχ. λαϐεῖν, EUR. <i>I.T. 1432,</i> prendre du loisir ; σχ. ποιεῖσθαι, XÉN. <i>Mem. 2, 6, 3,</i> se donner du loisir ; σχ. ἄγειν, HDT. <i>3, 134 ;</i> THC. <i>5, 29,</i> être de loisir ; σχ. ἄγειν τινί, LUC. <i>Cal. 15 ;</i> ἐπί τινι, PLAT. <i>Ap. 36</i> d ; περί τι, ANTIPAT. (STOB. <i>Fl. 67, 25</i>) ; πρός τι, ARR. <i>Epict. 1, 27, 15,</i> vaquer à qqe occupation ; σχ. διδόναι τινί, XÉN. <i>Cyr. 4, 2, 22 ; ou</i> παρέχειν, XÉN. <i>Hier. 10, 5,</i> procurer du loisir à qqn ; σχολή ἐστι πρός τι, PLAT. <i>Phædr. 227</i> b, il y a du loisir pour qqe ch., on a le loisir de qqe ch. ; σχολή ἐστί τινι, <i>avec l’inf</i>. SOPH. <i>Aj. 816, etc. ; ou</i> πάρεστί τινι <i>avec l’inf</i>. ESCHL. <i>Ag. 1055,</i> qqn a le loisir de faire qqe ch. ; οὐ σχολὴ αὐτῷ, PLAT. <i>Prot. 314</i> d, il n’a pas le temps ; οὐκ οὔσης σχολῆς, XÉN. <i>Cyr. 5, 1, 8,</i> faute de temps ; ἐπὶ σχολῆς, EUR. <i>I.T. 1220 ;</i> PLAT. <i>Theæt. 172</i> d ; <i>ou</i> κατὰ σχολήν, PLAT. <i>Phædr. 228</i> a, à loisir ; <i>p. suite :</i><br><b>      1</b> occupation d’un homme de loisir, PLAT. <i>Leg. 820</i> c ; <i>particul</i>. occupation studieuse, entretien savant, étude, PLUT. <i>M. 519</i> f, <i>605</i> a ; σχολὰς λέγειν, ARR. <i>Epict. 4, 11, 35,</i> faire des cours, des conférences ;<br><b>      2</b> association savante, ARSTT. <i>Pol. 2, 9, 2 ;</i><br><b>      3</b> lieu d’étude, école, DH. <i>Isocr. 1, Dem. 44, etc. ;</i> PLUT. <i>Per. 35, M. 42</i> a, <i>43</i> f ; ARR. <i>Epict. 1, 29, 34 ; 3, 21, 11 ;</i><br><b>      4</b> produit de l’étude, traité, ouvrage, PLUT. <i>M. 790</i> e ;<br><b>   II</b> relâche, trêve : κακοῦ, SOPH. <i>O.R. 1286 ;</i> πόνων, EUR. <i>H.f. 725,</i> trêve à un mal, à des épreuves ; σχ. γίγνεταί τινί τινος, PLAT. <i>Leg. 961</i> b ; <i>ou</i> ἀπό τινος, PLAT. <i>Phæd. 66</i> d, il y a trêve pour qqn à qqe ch. ;<br><b>   III</b> <i>en mauv. part,</i> inaction, lenteur, paresse, ESCHL. <i>Ag. 1059 ;</i> SOPH. <i>fr. 288 ;</i> EUR. <i>Hipp. 384 ;</i><br><b>B</b> <i>adv. au dat</i>. σχολῇ :<br><b>      1</b> à loisir, à son temps, SOPH. <i>Ant. 231 ;</i> THC. <i>1, 142 ; 3, 46 et 78 ; 5, 10 ; 8, 95 ;</i> σχ. ὑπακούειν τινί, XÉN. <i>Cyr. 2, 4, 6 ; 4, 2, 6,</i> obéir à qqn sans se presser ; σχ. καὶ βάδην, POL. <i>8, 30, 11 ;</i> LUC. <i>Cat. 2,</i> lentement et pas à pas ;<br><b>      2</b> <i>p. suite,</i> avec peine, <i>chez les Att</i>. σχ. πορεύεσθαι, XÉN. <i>Cyr. 4, 2, 6,</i> s’avancer difficilement ; <i>d’où</i> tout au plus, encore moins, ATT. ; σχολῇ γε, XÉN. <i>Mem. 3, 14, 3 ;</i> SOPH. <i>Ant. 390, etc. m. sign. ; particul. dans des réponses,</i> PLAT. <i>Rsp. 610</i> e, <i>Leg. 668</i> c, <i>etc. ;</i> εἰ μὴ…, σχολῇ γε, PLAT. <i>Phæd. 65</i> b, <i>Lach. 190</i> a, <i>etc</i>. sinon…, bien moins encore ; εἰ μὴ τούτων, σχολῇ γε τῶν ἄλλων, ARSTT. <i>Metaph. 2, 3, 10,</i> sinon de ceux-là, bien moins encore <i>ou</i> à plus forte raison des autres.<br><span><b><span class=\"arrow\"></span></b> <i>Dor</i>. σχολά <span>[ᾱ]</span> PD. <i>l. c. ;</i> THCR. <i>Idyl. 21, 34</i>.<br><span><b>Étym</b>. ἔχω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">σχολη - σχολή</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G4982":"<h1>sozo</h1>\n<p>Strong n° 4982 <i>Prononciation [sode'-zo]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>sauver, garder sain et sauf, délivrer du danger ou de la destruction\n<ol type=\"a\">\n<li>quelqu'un (d'un préjudice ou d'un péril)\n<ol>\n<li>sauver du périssement quelqu'un qui souffre, c.à.d. qui souffre de maladie, le guérir, lui redonner la santé</li>\n<li>préserver de la destruction</li>\n</ol>\n</li>\n<li>sauver dans le sens technique biblique\n<ol>\n<li>délivrer des peines du jugement Messianique, sauver des maux qui font obstacle à la délivrance par le Messie</li>\n</ol>\n</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>σῴζω</b> <span>(<i>f</i>. σώσω, <i>ao</i>. ἔσωσα, <i>qqf</i>. ἔσῳσα, <i>pf</i>. σέσωκα ; <i>pass. ao</i>. ἐσώθην, <i>pf</i>. σέσῳσμαι <i>ou</i> σέσωμαι)</span> conserver sain et sauf, <i>d’où :</i><br><b>      1</b> mettre à l’abri d’un danger, préserver <i>ou</i> tirer d’un danger, sauver : τινά <i>ou</i> τι, IL. <i>4, 83, etc. ;</i> OD. <i>9, 430, etc. ;</i> ATT. qqn <i>ou</i> qqe ch. ; <i>avec double rég. :</i> σ. υἷά τινι, OD. <i>4, 675,</i> sauver le fils de qqn ; τινὶ τὸν βίον, PLAT. <i>Prot. 357</i> a, sauver la vie à qqn ; τινὰ ἔκ τινος, IL. <i>5, 469 ; 11, 752 ; 22, 175, etc. ;</i> OD. <i>4, 753, etc. ;</i> XÉN. <i>Œc. 11, 11 ; An. 3, 2, 11, etc. ;</i> PLAT. <i>Gorg. 511</i> c, <i>etc. ; ou</i> ἀπό τινος, ESCHL. <i>Ag. 603 ; ou simpl. avec un gén. de chose :</i> τινός, SOPH. <i>Ph. 919,</i> tirer qqn de qqe danger ; <i>avec un gén. de pers. :</i> ἐχθρῶν Καδμείαν χθόνα, SOPH. <i>Ant. 1162,</i> délivrer la terre de Kadmos de ses ennemis ; <i>avec un inf. :</i> τινὰ σῴζειν θανεῖν, EUR. <i>Ph. 600,</i> sauver qqn de mourir ; <i>abs</i>. DÉM. <i>66, 27 ;</i> ἡ σῴζουσα (<i>s.-e</i>. ψῆφος) LUC. <i>Harm. 3,</i> le suffrage qui sauve, qui acquitte ; <i>au pass</i>. être sauvé, se sauver, échapper au danger, IL. <i>17, 228 ;</i> OD. <i>3, 185, etc. ;</i> ESCHL. <i>Ag. 618 ;</i> XÉN. <i>Cyr. 3, 3, 51, etc. ; en parl. de malades,</i> être rétabli, se tirer d’affaire, HPC. <i>138</i> b ; IS. <i>36, 12 ; fig</i>. être sauvé moralement, être amendé, AR. <i>Nub. 930 ;</i> PLUT. <i>M. 74</i> c ; <i>p. suite,</i> être en vie, continuer de vivre, exister, POL. <i>6, 9, 4 ;</i> σῴζεο, Dieu te conserve ! porte-toi bien ! <i>d’où</i> adieu, CALL. <i>Del. 150 ;</i> ANTH. <i>5, 241 ; 9, 171, etc. ;</i> μόγις <i>ou</i> μόλις σ. PLAT. <i>Ep. 322</i> c ; DS. <i>2, 48, etc</i>. n’être sauvé <i>ou</i> ne s’en tirer qu’avec peine ; χαλεπῶς σ. THGN. <i>695, m. sign. ; avec un n. de chose comme suj. :</i> πόλις σῴζεται, ESCHL. <i>Sept. 820 ;</i> THC. <i>3, 80, etc</i>. la cité est sauvée ; <i>cf</i>. DÉM. <i>118, 19 ; avec un gén. de chose :</i> σωθῆναι κακῶν, EUR. <i>Or. 779,</i> être délivré de ses maux ;<br><b>      2</b> ne pas tuer, laisser vivre, épargner, OD. <i>22, 357 ;</i><br><b>      3</b> ne pas perdre, conserver : σ. σπέρμα πυρός, OD. <i>5, 490,</i> conserver des charbons allumés sous la cendre ; σ. φάρμακον, SOPH. <i>Tr. 686,</i> conserver, tenir en réserve un poison ; σ. τὰ τόξα, SOPH. <i>Ph. 766,</i> garder les flèches ; σ. τὰ σκεύη, οἶκον, χρήματα, <i>etc</i>. AR. <i>Pax 730 ; Av. 380, 1062,</i> conserver son mobilier, sa maison, sa fortune, <i>etc. ;</i> θοἰμάτιον, AR. <i>Eccl. 544,</i> sauver le vêtement (empêcher qu’il ne soit volé) ; σ. τὰ ὑπάρχοντα, THC. <i>1, 70,</i> conserver ce qui existe ; τὰ ἑαυτῶν, XÉN. <i>Cyr. 3, 3, 45,</i> conserver son bien ; πόλιν, HDT. <i>8, 34 ;</i> ESCHL. <i>Sept. 749 ;</i> SOPH. <i>Ant. 1058,</i> conserver <i>ou</i> sauver la cité <i>ou</i> l’État ; τὰ πράγματα, THC. <i>1, 74,</i> maintenir les affaires en bonne situation ; σῷζε τὸν παρόντα νοῦν, ESCHL. <i>Pr. 392,</i> garde cette opinion, reste fidèle à cette opinion ; <i>avec double rég. :</i> σ. θᾶκόν τινι, AR. <i>Ran. 1517,</i> réserver la place de qqn ; σ. τὰς πόλεις Φαρναϐάζῳ, XÉN. <i>Hell. 3, 1, 15,</i> conserver les cités à Pharnabaze, faire qu’elles ne lui fassent pas défection ;<br><b>      4</b> conserver avec soi, garder dans sa mémoire : λόγον, ESCHL. <i>Pr. 524,</i> un discours ; <i>cf</i>. EUR. <i>Hel. 266 ;</i> PLAT. <i>Rsp. 486</i> c ; <i>d’où</i> conserver, <i>en gén. ; au pass</i>. être conservé, <i>en parl. d’ouvrages, d’écrits,</i> LGN <i>fr. 5, 4 ;</i> DC. <i>70, 2 ; en gén</i>. δι' ὧν τὰ προειμένα σωθήσεται, DÉM. <i>57, 22,</i> par quoi nous pourrons sauver <i>ou</i> conserver ce qui a été abandonné ; τὸ ἄπραγμον οὐ σῴζεται, THC. <i>2, 63,</i> le repos ne peut pas subsister ; <i>avec le dat. de celui à qui qqe ch. est consacré,</i> XÉN. <i>An. 7, 7, 56 ;</i> AR. <i>fr. 1022,</i> MOSCH. <i>4, 3 ; avec un rég. de mouv</i>. ramener sain et sauf : σ. τινὰ πόλινδε, IL. <i>5, 224,</i> ramener qqn sain et sauf à la ville ; ἐς ὅμιλον, IL. <i>19, 401,</i> dans l’assemblée ; ἐς οἴκους, SOPH. <i>Ph. 311,</i> dans sa maison ; <i>avec double rég. :</i> σ. τινὰ ἐκ πολέμου ἐπὶ νῆας, IL. <i>17, 452,</i> ramener qqn sain et sauf du combat vers les vaisseaux ; ἐξ Αἰγίνης δεῦρο, PLAT. <i>Gorg. 511</i> d, d’Égine ici ; <i>au pass</i>. σῴζεσθαι δεῦρο πάλιν, EUR. <i>Ph. 725,</i> revenir ici sain et sauf ; ἐς οἶκον, HDT. <i>4, 97 ;</i> οἴκαδε, XÉN. <i>Hell. 1, 6, 7,</i> revenir sain et sauf dans sa maison, dans sa patrie. ; πρὸς τὸ στρατόπεδον, XÉN. <i>Cyr. 5, 4, 16,</i> revenir sain et sauf vers le camp ; ἐπὶ θάλατταν, XÉN. <i>An. 6, 5, 20,</i> arriver sain et sauf à la mer ;<br><b>      5</b> observer : τοὺς νόμους, SOPH. <i>Ant. 114 ;</i> EUR. <i>Suppl. 313, 527,</i> les lois ; ἐφετμὰς χρηστηρίους, ESCHL. <i>Eum. 241,</i> les ordres de l’oracle ;<br><b><i>Moy.</i></b> :<br><b>      1</b> conserver pour soi, <i>acc</i>. SOPH. <i>El. 994 ;</i> EUR. <i>Hipp. 635, etc. ;</i> XÉN. <i>Hell. 4, 5, 1, etc. ;</i><br><b>      2</b> conserver dans son esprit, dans son souvenir, <i>acc</i>. ATT. SOPH. <i>Tr. 682 ;</i> EUR. <i>Bacch. 793, etc. ;</i> PLAT. <i>Theæt. 153</i> b, <i>etc</i>.<br><span><b><span class=\"arrow\"></span></b> σῴζω (<i>non</i> σώζω) <i>p</i>. *σωΐζω, <i>seule orthogr. us. dans les inscr. att</i>. CIA. <i>1, 397, 4 (av. 444 av. J.C.), etc. ; v. Meisterh. p. 142, 26 ; mais pour les temps autres que le prés. et l’impf. on rencontre deux écritures : 1° d’un th. vb</i>. σω- : <i>f</i>. σώσω, <i>ao</i>. ἔσωσα, <i>ao. pass</i>. ἐσώθην, <i>pf</i>. σέσωμαι ; <i>2° d’un th. avec allongem</i>. σῳδ-, <i>d’où vient</i> σῴζω <i>p</i>. *σῴδϳω, <i>des formes vulg. d’ao</i>. ἔσῳσα, <i>d’où 3 sg</i>. ἔσῳσεν, CIA. <i>2, 605, 6 (200/180 av. J.C.) ; v. Meisterh. p. 145, § 65, 3 ; et de pf. pass</i>. σέσῳσμαι, <i>d’où 3 sg</i>. σέσῳσται ; <i>mais la forme</i> σέσῳμαι <i>conservée dans le cps</i>. διασεσῳμένους (<i>inscr. après 319 av. J.C. ; v. Meisterh. p. 148, § 69, 3) est incorrecte et doit être écrite</i> σέσωμαι, <i>d’où 3 sg</i>. σέσωται, PLAT. <i>Criti. 109</i> d ; EUR. <i>I.T. 607 var. ou</i> σέσῳσμαι. <i>On trouve encore dans les inscr. att. un fut</i>. σωῶ, <i>p</i>. *σωιῶ, CIA. <i>1, 2 b, 7 (av. 456 av. J.C.) ; v. Meisterh. p. 143, § 64, 1 ; dans</i> HOM. <i>seul. le part. prés</i>. σῴζων, OD. <i>5, 490 ; cf</i>. σώω <i>ou</i> σαόω.<br><span><b>Étym</b>. <i>p</i>. *σωΐζω, <i>v</i>. σάος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">σωζω - σῴζω</font>\n<br><br>vient du mot sos (contraction de saoz, « sûr »)</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n109 fois dans 102 versets de 18 livres bibliques (NT)\n<ul>\n<li>Matthieu (16)</li>\n<li>Marc (15)</li>\n<li>Luc (19)</li>\n<li>Jean (6)</li>\n<li>Actes (13)</li>\n<li>Romains (8)</li>\n<li>1 Corinthiens (9)</li>\n<li>2 Corinthiens (1)</li>\n<li>Ephésiens (2)</li>\n<li>1 Thessaloniciens (1)</li>\n<li>2 Thessaloniciens (1)</li>\n<li>1 Timothée (4)</li>\n<li>2 Timothée (2)</li>\n<li>Tite (1)</li>\n<li>Hébreux (2)</li>\n<li>Jacques (5)</li>\n<li>1 Pierre (2)</li>\n<li>Jude (2)</li>\n</ul>\n</td></tr>\n</table>","G4983":"<h1>soma</h1>\n<p>Strong n° 4983 <i>Prononciation [so'-mah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>le corps, des hommes ou des animaux\n<ol type=\"a\">\n<li>un corps mort ou cadavre</li>\n<li>le corps vivant\n<ol>\n<li>des animaux</li>\n</ol>\n</li>\n</ol>\n</li>\n<li>le corps des plantes et des étoiles (les corps célestes)</li>\n<li>utilisé pour un nombre (petit ou grand) d'hommes étroitement unis dans une société ou famille; un corps social, éthique, mystique\n<ol type=\"a\">\n<li>l'Eglise dans le N.T.</li>\n</ol>\n</li>\n<li>ce qui projette une ombre, pour le distinguer de l'ombre elle-même</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>σῶμα, ατος (τὸ) :<br>   I</b> corps, <i>p. opp. à l’âme</i> (ψυχή) PLAT. <i>Gorg. 493</i> a, <i>Phæd. 91</i> c ; <i>à l’esprit</i> (εἴδωλον) PD. <i>fr. 96 ;</i> αἱ τοῦ σώματος ἡδοναί, XÉN. <i>Mem. 1, 5, 6,</i> les plaisirs du corps ; τὰ τοῦ σώματος ἔργα, XÉN. <i>Mem. 2, 8, 2,</i> les travaux <i>ou</i> exercices corporels ; <i>particul</i>. corps d’un homme <i>ou</i> d’un animal, <i>p. opp. aux plantes,</i> PLAT. <i>Rsp. 564</i> a ; <i>particul. :</i><br><b>      1</b> <i>dans Hom</i>. corps mort, cadavre (<i>en parl. d’un corps vivant,</i> δέμας) : <i>en parl. de l’homme,</i> IL. <i>7, 79 ; 22, 342 ;</i> OD. <i>11, 53 ; 12, 67 ; 24, 187 ;</i> PD. <i>N. 9, 55 ; en parl. d’un animal,</i> cadavre, charogne, IL. <i>3, 23 ; 18, 161 ; 23, 169 ;</i> HÉS. <i>Sc. 426 ;</i> PD. <i>N. 3, 82, etc. ;</i><br><b>      2</b> <i>postér</i>. corps vivant, <i>en parl. de l’homme,</i> HÉS. <i>O. 538 ;</i> THGN. <i>650 ;</i> PD. <i>O. 6, 93 ;</i> SIM. <i>fr. 183 Bgk ;</i> SOPH. <i>Ph. 51, etc. ;</i> XÉN. <i>Hell. 6, 1, 6, etc. ; en parl. d’un animal,</i> BATR. <i>61 ;</i> τὸ σῶμα σῴζειν, THC. <i>1, 136 ;</i> διασῴζειν, XÉN. <i>An. 5, 5, 13,</i> sauver sa vie ; περὶ τοῦ σώματος κινδυνεύειν, ISOCR. <i>365</i> c, exposer sa vie ; <i>p. suite,</i> être animé, homme <i>ou</i> animal ; τὸ σὸν σῶμα, EUR. <i>Hec. 301,</i> ta personne, <i>càd</i>. toi ; σῶμα ἀνικάτου θηρός, SOPH. <i>O.C. 1568,</i> le corps du monstre invincible, <i>pour</i> le monstre invincible, <i>càd</i>. Cerbère ; τὰ πολλὰ σώματα, SOPH. <i>Ant. 676, c</i>. οἱ πολλοί, la plupart ; δοῦλα καὶ ἐλεύθερα σώματα, XÉN. <i>Hell. 2, 1, 19,</i> êtres esclaves et libres ; <i>au sg. en parl. de plus. pers</i>. νεκύων σῶμα, EUR. <i>Suppl. 62,</i> les morts ; <i>particul. avec idée de dédain en parl. de prisonniers ou d’esclaves :</i> σώματα αἰχμάλωτα, DÉM. <i>480, 10,</i> prisonniers ; σώματα οἰκετικά, ESCHN. <i>3, 19,</i> serviteurs ; <i>abs</i>. σῶμα, <i>au sens de</i> « esclave », POL. <i>12, 16, 5, emploi blâmé par</i> POLL. <i>3, 78 ;</i><br><b>      3</b> <i>p. suite,</i> matière, objet tangible, <i>p. opp. à ce qui est insaisissable (comme un souffle, une ombre, etc</i>.) PLAT. <i>Pol. 288</i> d ; LUC. <i>V. auct. 25 ;</i> SEXT. <i>M. 10, 215, etc. ; d’où</i> le point capital, le fondement : τῆς πίστεως, ARSTT. <i>Rhet. 1, 1,</i> le corps de la preuve ; <i>cf</i>. LUC. <i>H. conscr. 23 ;</i><br><b>      4</b> <i>t. de math</i>. corps solide, <i>p. opp. à surface,</i> ARSTT. <i>Cæl. 1, 1, 2, etc. ;</i><br><b>      5</b> corps, ensemble, masse : τοῦ κόσμου, PLAT. <i>Tim. 31</i> b ; τοῦ παντός, PLAT. <i>Tim. 32</i> c, l’ensemble du monde, de l’univers ; <i>en parl. d’un recueil d’écrits,</i> CIC. <i>Att. 2, 1, 4 ;</i><br><b>   II</b> partie du corps, organe, <i>avec l’indication de l’organe dont on veut parler :</i> τὸ σῶμα τῶν νεφρῶν, ARSTT. <i>H.A. 2, 17,</i> les reins ; σ. παιδοποιόν, EL. <i>N.A. 17, 62,</i> le membre génital.<br><span><b><span class=\"arrow\"></span></b> <i>Dat. pl. poét</i>. σωμάτεσσι, PD. <i>P. 8, 118</i>.<br><span><b>Étym</b>. <i>inconnue</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">σωμα - σῶμα</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n146 fois dans 122 versets de 18 livres bibliques (NT)\n<ul>\n<li>Matthieu (16)</li>\n<li>Marc (5)</li>\n<li>Luc (13)</li>\n<li>Jean (6)</li>\n<li>Actes (1)</li>\n<li>Romains (13)</li>\n<li>1 Corinthiens (47)</li>\n<li>2 Corinthiens (10)</li>\n<li>Galates (1)</li>\n<li>Ephésiens (9)</li>\n<li>Philippiens (3)</li>\n<li>Colossiens (8)</li>\n<li>1 Thessaloniciens (1)</li>\n<li>Hébreux (5)</li>\n<li>Jacques (5)</li>\n<li>1 Pierre (1)</li>\n<li>Jude (1)</li>\n<li>Apocalypse (1)</li>\n</ul>\n</td></tr>\n</table>","G4984":"<h1>somatikos</h1>\n<p>Strong n° 4984 <i>Prononciation [so-mat-ee-kos']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>corporel\n<ol type=\"a\">\n<li>ayant une forme ou une nature corporelle</li>\n<li>appartenant au corps</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>σωματικός, ή, όν</b> <span>[ᾰ]</span><br><b>      1</b> du corps, corporel, ARSTT. <i>Nic. 1, 12, 6, etc. ;</i><br><b>      2</b> corporel, matériel, <i>p. opp. à</i> ἀσώματος, T. LOCR. <i>96</i> a ; ARSTT. <i>Metaph. 1, 5, 14, etc</i>.<br><span>•<i> Cp</i>. -ώτερος, TH. <i>C.P. 1, 14, 3 ;</i> <i>• Sup</i>. -ώτατος, TH. <i>fr. 1, 37</i>.<br><span><b>Étym</b>. σῶμα.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">σωματικος - σωματικός</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Luc (1)</li>\n<li>1 Timothée (1)</li>\n</ul>\n</td></tr>\n</table>","G4985":"<h1>somatikos</h1>\n<p>Strong n° 4985 <i>Prononciation [so-mat-ee-koce']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>corporel, corporellement\n<ol type=\"a\">\n<li>du corps spirituel élevé, visible seulement des habitants des cieux</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>σωματικῶς</b> <span>[ᾰμ]</span> <i>adv</i>., corporellement, PLUT. <i>M. 424</i> d ; NT. <i>Col. 2, 9</i>.<br><span>•<i> Cp</i>. -ώτερον, SEXT. <i>P. 1, 7</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">σωματικως - σωματικῶς</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adverbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Colossiens (1)</li>\n</ul>\n</td></tr>\n</table>","G4986":"<h1>Sopatros</h1>\n<p>Strong n° 4986 <i>Prononciation [so'-pat-ros]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Sopater = « sauveur de son père »\n<ol><li>le fils de Pyrrhus de Bérée, un compagnon de Paul</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>Σώ·πατρος, ου (ὁ)</b> Sôpatros, <i>h</i>. EL. <i>N.A. 10, 40</i>.<br><span><b>Étym</b>. σῶς, πατήρ.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Σωπατρος - Σώπατρος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G4987":"<h1>soreuo</h1>\n<p>Strong n° 4987 <i>Prononciation [sore-yoo'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>entasser ensemble, amasser</li>\n<li>accabler quelqu'un avec un tas de choses</li>\n<li>métaph. charger quelqu'un en le rendant conscient de nombreux péchés</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>σωρεύω</b>, entasser, amonceler, <i>acc</i>. POL. <i>16, 11, 4 ;</i> DS. <i>1, 62 ; 12, 62, etc. ;</i> τι πρός τι, ARSTT. <i>Rhet. 2, 15, 2 ;</i> τι ἐπί τινι, ANTH. <i>10, 41 ;</i> τι ἐπί τι, NT. <i>Rom. 12, 20,</i> qqe ch. sur qqe ch. ; <i>au pass</i>. être entassé, ARSTT. <i>Gen. et corr. 1, 8, 12 ; avec un rég</i>. être couvert d’un monceau, d’un amas de, <i>gén</i>. POL. <i>16, 8, 9 ; dat</i>. HDN <i>4, 8 ;</i> ANTH. <i>7, 233</i>.<br><span><b>Étym</b>. σωρός.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">σωρευω - σωρεύω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Romains (1)</li>\n<li>2 Timothée (1)</li>\n</ul>\n</td></tr>\n</table>","G4988":"<h1>Sosthenes</h1>\n<p>Strong n° 4988 <i>Prononciation [soce-then'-ace]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Sosthène (Angl. Sosthenes) = « sauveur de sa nation »\n<ol>\n<li>un Juif à Corinthe qui fut saisi et battu en présence de Gallion</li>\n<li>un certain Chrétien associé de Paul</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>Σω·σθένης, ους (ὁ)</b> Sôsthénès (Sosthène) <i>h</i>. Ps.-PLUT. <i>Fluv. 16, 3 ; 17, 4</i>.<br><span><b>Étym</b>. σῶς, σθένος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Σωσθενης - Σωσθένης</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Actes (1)</li>\n<li>1 Corinthiens (1)</li>\n</ul>\n</td></tr>\n</table>","G4989":"<h1>Sosipatros</h1>\n<p>Strong n° 4989 <i>Prononciation [so-sip'-at-ros]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Sosipater = « sauveur de son père »\n<ol><li>un parent ou compagnon de la tribu de Paul</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>Σωσί·πατρος, ου (ὁ)</b> <span>[ῐ]</span> Sôsipatros :<br><b>      1</b> <i>poète de la nouvelle comédie,</i> ATH. <i>377</i> f ;<br><b>      2</b> <i>autre,</i> ANTH. <i>5, 52</i>.<br><span><b>Étym</b>. σῴζω, πατήρ.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Σωσιπατρος - Σωσίπατρος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Romains (1)</li>\n</ul>\n</td></tr>\n</table>","G4990":"<h1>soter</h1>\n<p>Strong n° 4990 <i>Prononciation [so-tare']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>sauveur, libérateur</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>σωτήρ</b>, <i>voc</i>. <b>σῶτερ</b>, <i>gén</i>. <b>σωτῆρος :<br>   I</b> <i>adj. m. et fém</i>. qui sauve, qui protège, ESCHL. <i>Ag. 897 ; au fém</i>. ESCHL. <i>Sept. 225 ;</i> EUR. <i>El. 993 ;</i><br><b>   II</b> <i>subst</i>. (ὁ, ἡ) sauveur, libérateur, <i>avec le gén. de la pers. ou de la chose sauvée :</i> σ. ἀνθρώπων, HH. <i>21, 5,</i> sauveur des hommes ; τῆς Ἑλλάδος, HDT. <i>7, 139,</i> de la Grèce ; ἑστίας πατρός, ESCHL. <i>Ch. 264,</i> du foyer de son père ; <i>avec le gén. du danger dont on sauve :</i> σ. νόσου, SOPH. <i>O.R. 30 ;</i> σ. κακῶν, EUR. <i>Med. 360,</i> qui sauve d’un fléau, d’un malheur ; <i>particul. en parl. de Zeus,</i> PD. <i>O. 5, 40, etc. ;</i> AR. <i>Th. 1009 ;</i> DIN. <i>94, 45 ; abs</i>. ὁ Σωτήρ, PD. <i>I. 6, 11,</i> Zeus sauveur ; <i>d’où :</i> τὸ τρίτον τῷ Σωτῆρι, PLAT. <i>Rsp. 583</i> b, <i>Phil. 66</i> d, <i>Charm. 167</i> a, la troisième coupe à Zeus sauveur, <i>prov</i>. le troisième coup, le bon ; <i>en parl. d’Apollon,</i> ESCHL. <i>Ag. 512, etc. ; d’Hermès,</i> ESCHL. <i>Ch. 2 ; des Dioscures,</i> EL. <i>V.H. 4, 5 ; de la Fortune,</i> ESCHL. <i>Ag. 664 ; Sept. 826 ;</i> SOPH. <i>O.R. 81 ; des dieux en gén</i>. HDT. <i>8, 138 ;</i> ESCHL. <i>Suppl. 982 ;</i> SOPH. <i>Ph. 738 ; joint à</i> ἀποτρόπαιος, XÉN. <i>Hell. 3, 3, 4. Postér. en parl. de J.C</i>. NT. <i>2Tim. 1, 10 ;</i> CLÉM. <i>1, 953, 1237 Migne, etc</i>.<br><span><b>Étym</b>. σῴζω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">σωτηρ - σωτήρ</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n24 fois dans 24 versets de 11 livres bibliques (NT)\n<ul>\n<li>Luc (2)</li>\n<li>Jean (1)</li>\n<li>Actes (2)</li>\n<li>Ephésiens (1)</li>\n<li>Philippiens (1)</li>\n<li>1 Timothée (3)</li>\n<li>2 Timothée (1)</li>\n<li>Tite (6)</li>\n<li>2 Pierre (5)</li>\n<li>1 Jean (1)</li>\n<li>Jude (1)</li>\n</ul>\n</td></tr>\n</table>","G4991":"<h1>soteria</h1>\n<p>Strong n° 4991 <i>Prononciation [so-tay-ree'-ah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>délivrance, conservation, sûreté, sécurité, salut\n<ol type=\"a\">\n<li>la délivrance des ennemis qui molestent</li>\n<li>dans un sens moral, ce qui apporte aux âmes sécurité ou salut\n<ol>\n<li>du salut Messianique</li>\n</ol>\n</li>\n</ol>\n</li>\n<li>le salut, en tant que possession actuelle de tout vrai Chrétien</li>\n<li>le salut futur, la somme des bienfaits et bénédictions que les Chrétiens, rachetés de tous les maux terrestres, vont posséder après la seconde venue de Christ depuis les cieux, dans le royaume éternel de Dieu</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n➀ <b>σωτηρία, ας (ἡ) :<br>   I</b> salut, préservation <i>ou</i> conservation des personnes, HDT. <i>4, 98 ;</i> ATT. ; σωτηρίαν τινὶ διδόναι, EUR. <i>I.A. 1473 ;</i> πορίζειν, PLAT. <i>Prot. 321</i> b ; ἐκπορίζεσθαι, THC. <i>6, 83,</i> procurer le salut à qqn ; φέρειν, EUR. <i>Tr. 748,</i> apporter le salut à qqn ; σωτηρίαν ἔχειν, SOPH. <i>Aj. 1080, etc</i>. être sauvé ; σ. ζητεῖν, ISOCR. <i>60</i> b, chercher le salut ; εὑρίσκεσθαι, ESCHN. <i>72, 40,</i> trouver son salut ; σωτηρίας τυγχάνειν, ESCHL. <i>Pers. 508, etc</i>. obtenir <i>ou</i> rencontrer le salut, <i>etc. ; au plur</i>. PLAT. <i>Prot. 354</i> b, <i>etc. ; en parl. de choses,</i> préservation <i>ou</i> conservation : τινός, de qqe ch. (<i>des routes, des habitations,</i> ARSTT. <i>Pol. 6, 8, 4 ; des lois,</i> PLAT. <i>Rsp. 425</i> e ; <i>du ciel, des astres,</i> ARSTT. <i>Cæl. 2, 1, 4 ; Meteor. 2, 2, 10, etc.) ; cf</i>. HDT. <i>4, 98 ;</i> ESCHL. <i>Eum. 909, etc. ; avec le gén. de la chose contre laquelle on préserve,</i> PHILÉM. (<i>Com. fr. 4, 31) ; particul</i>. heureux retour, ESCHL. <i>Pers. 797, Ag. 343, 1238 ;</i> THC. <i>6, 70 ;</i> DÉM. <i>1211, 17, etc. ;</i><br><b>   II</b> moyen de salut, THC. <i>3, 20 ;</i> ESCHL. <i>Pers. 735 ;</i> SOPH. <i>Aj. 1080 ;</i> EUR. <i>Or. 778 ; au plur</i>. ARSTT. <i>Pol. 5, 1, 1, etc. ;</i><br><b>   III</b> sécurité, THC. <i>2, 60 ;</i> PLAT. <i>Prot. 356</i> d, <i>Leg. 908</i> a, <i>etc. ;</i> DÉM. <i>927, 8, etc</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Ion</i>. -ίη, HDT. <i>4, 98 ; 5, 98, etc</i>.<br><span><b>Étym</b>. σωτήρ.</span></span><br><br>\n➁ <b>σωτήρια, ων (τὰ)</b> <i>v</i>. σωτήριος.<br><br>\n<b>σωτήριος, ος, ον :<br>   I</b> <i>act. :</i><br><b>      1</b> qui sauve, qui préserve <i>ou</i> conserve, secourable, <i>en parl. de pers</i>. EUR. <i>Or. 657, etc. ; particul. en parl. de divinités,</i> SOPH. <i>El. 281 ; avec un dat</i>. THC. <i>7, 64 ;</i> EUR. <i>Or. 1637 ; avec un gén</i>. SOPH. <i>Aj. 779 ; en parl. de choses :</i> σ. τινος, ESCHL. <i>Eum. 701 ;</i> SOPH. <i>Aj. 766 ; d’ord</i>. τινι, ESCHL. <i>Sept. 183, etc. ;</i> EUR. <i>Her. 402, etc</i>. secourable à qqn ; <i>subst</i>. τὸ σωτήριον, LUC. <i>J. tr. 18,</i> moyen de salut, <i>d’où</i> salut, délivrance, SPT. <i>Ex. 20, 24 ; 1Esdr. 8, 63, etc. ;</i> τὰ σωτήρια, <i>m. sign</i>. SOPH. <i>El. 925 ;</i> ARSTT. <i>Rhet. 2, 5, 16 ; ou (s.-e</i>. ἱερά) sacrifices en actions de grâces d’une guérison, d’un heureux retour, XÉN. <i>An. 3, 2, 9 ; 5, 5, 1 ; qqf</i>. honoraires d’un médecin, POLL. <i>6, 186 ; à Smyrne,</i> lieux d’aisance publics, ANTH. <i>9, 642 ;</i><br><b>      2</b> qui annonce la guérison, HPC. <i>Aph. 1259</i>.<br><span>•<i> Cp</i>. -ώτερος, XÉN. <i>Mem. 3, 4, 10 ;</i> <i>• Sup</i>. -ώτατος, XÉN. <i>Eq. 3, 12</i>.<br><span><b>Étym</b>. σωτήρ.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">σωτηρια - σωτηρία</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n44 fois dans 43 versets de 15 livres bibliques (NT)\n<ul>\n<li>Luc (4)</li>\n<li>Jean (1)</li>\n<li>Actes (6)</li>\n<li>Romains (5)</li>\n<li>2 Corinthiens (4)</li>\n<li>Ephésiens (1)</li>\n<li>Philippiens (3)</li>\n<li>1 Thessaloniciens (2)</li>\n<li>2 Thessaloniciens (1)</li>\n<li>2 Timothée (2)</li>\n<li>Hébreux (7)</li>\n<li>1 Pierre (3)</li>\n<li>2 Pierre (1)</li>\n<li>Jude (1)</li>\n<li>Apocalypse (3)</li>\n</ul>\n</td></tr>\n</table>","G4992":"<h1>soterion</h1>\n<p>Strong n° 4992 <i>Prononciation [so-tay'-ree-on]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>qui sauve, qui apporte le salut</li>\n<li>celui qui incarne ce salut, ou à travers qui Dieu veut l'accomplir</li>\n<li>l'espérance du salut futur</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>σωτήριος, ος, ον :<br>   I</b> <i>act. :</i><br><b>      1</b> qui sauve, qui préserve <i>ou</i> conserve, secourable, <i>en parl. de pers</i>. EUR. <i>Or. 657, etc. ; particul. en parl. de divinités,</i> SOPH. <i>El. 281 ; avec un dat</i>. THC. <i>7, 64 ;</i> EUR. <i>Or. 1637 ; avec un gén</i>. SOPH. <i>Aj. 779 ; en parl. de choses :</i> σ. τινος, ESCHL. <i>Eum. 701 ;</i> SOPH. <i>Aj. 766 ; d’ord</i>. τινι, ESCHL. <i>Sept. 183, etc. ;</i> EUR. <i>Her. 402, etc</i>. secourable à qqn ; <i>subst</i>. τὸ σωτήριον, LUC. <i>J. tr. 18,</i> moyen de salut, <i>d’où</i> salut, délivrance, SPT. <i>Ex. 20, 24 ; 1Esdr. 8, 63, etc. ;</i> τὰ σωτήρια, <i>m. sign</i>. SOPH. <i>El. 925 ;</i> ARSTT. <i>Rhet. 2, 5, 16 ; ou (s.-e</i>. ἱερά) sacrifices en actions de grâces d’une guérison, d’un heureux retour, XÉN. <i>An. 3, 2, 9 ; 5, 5, 1 ; qqf</i>. honoraires d’un médecin, POLL. <i>6, 186 ; à Smyrne,</i> lieux d’aisance publics, ANTH. <i>9, 642 ;</i><br><b>      2</b> qui annonce la guérison, HPC. <i>Aph. 1259</i>.<br><span>•<i> Cp</i>. -ώτερος, XÉN. <i>Mem. 3, 4, 10 ;</i> <i>• Sup</i>. -ώτατος, XÉN. <i>Eq. 3, 12</i>.<br><span><b>Étym</b>. σωτήρ.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">σωτηριον - σωτήριος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n5 fois dans 5 versets de 4 livres bibliques (NT)\n<ul>\n<li>Luc (2)</li>\n<li>Actes (1)</li>\n<li>Ephésiens (1)</li>\n<li>Tite (1)</li>\n</ul>\n</td></tr>\n</table>","G4993":"<h1>sophroneo</h1>\n<p>Strong n° 4993 <i>Prononciation [so-fron-eh'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>avoir un esprit sain\n<ol type=\"a\">\n<li>être dans son bon sens</li>\n<li>exercer un contrôle sur soi-même\n<ol>\n<li>s'estimer d'une manière modérée, sobrement</li>\n<li>faire fléchir ses passions</li>\n</ol>\n</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>σωφρονέω-ῶ</b>, <i>litt</i>. avoir l’esprit <i>ou</i> le corps sain, <i>d’où :</i><br><b>      1</b> être sensé, prudent, sage, avisé, HDT. <i>3, 35 ;</i> BABR. <i>90, 4 ;</i><br><b>      2</b> être tempérant, sobre, ATT. ;<br><b>      3</b> être sage <i>ou</i> modéré dans ses désirs, être simple, modeste, ESCHL. <i>Pr. 982, etc. ;</i> THC. <i>8, 24 ;</i> XÉN. <i>Cyr. 8, 1, 30 ;</i> PLAT. <i>Phædr. 244</i> a, <i>etc. ; p. suite,</i> montrer des sentiments de réserve : ἐς Ἀφροδίτην, EUR. <i>I.A. 1159,</i> à l’égard d’Aphrodite, <i>càd</i>. être chaste ; être respectueux, XÉN. <i>Mem. 1, 1, 20 ; abs. joint à</i> ὁμονοεῖν, AND. <i>14, fin ; en parl. de soldats, joint à</i> εὐτακτεῖν, XÉN. <i>Mem. 3, 5, 21 ; au pass</i>. τὰ σεσωφρονημένα ἐν τῷ βίῳ, ESCHN. <i>28, 21,</i> habitudes de vie sages, simples, modestes.<br><span><b><span class=\"arrow\"></span></b> <i>Poét</i>. σαοφρονέω, OPP. <i>H. 3, 446,</i> ANTH. <i>5, 302</i>.<br><span><b>Étym</b>. σώφρων ; <i>cf</i>. σαοφρονέω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">σωφρονεω - σωφρονέω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n6 fois dans 6 versets de 6 livres bibliques (NT)\n<ul>\n<li>Marc (1)</li>\n<li>Luc (1)</li>\n<li>Romains (1)</li>\n<li>2 Corinthiens (1)</li>\n<li>Tite (1)</li>\n<li>1 Pierre (1)</li>\n</ul>\n</td></tr>\n</table>","G4994":"<h1>sophronizo</h1>\n<p>Strong n° 4994 <i>Prononciation [so-fron-id'-zo]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>remettre quelqu'un dans ses sens</li>\n<li>modérer, contrôler, brider, discipliner</li>\n<li>contenir quelqu'un à ses devoirs</li>\n<li>réprimander, exhorter sérieusement</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>σωφρονίζω, A <i>tr. :</i><br>   I</b> rendre modéré, sensé, sage, EUR. <i>Tr. 350, etc</i>. ANT. <i>118, 16 ;</i><br><b>   II</b> <i>p. suite :</i><br><b>      1</b> donner une leçon, corriger, XÉN. <i>Cyr. 3, 1, 20 ; d’où</i> châtier, <i>acc</i>. DÉM. <i>798, 7 ; au pass</i>. THC. <i>6, 78, etc. ; d’où postér</i>. apprendre à être <i>ou</i> à devenir sage, NT. <i>Tit. 2, 4 ;</i><br><b>      2</b> réprimer, contenir, <i>acc</i>. XÉN. <i>Mem. 2, 1, 16, etc. ;</i> ANT. <i>118, 7, etc. ;</i> ἐς εὐτέλειαν, THC. <i>8, 1,</i> ramener (les dépenses) à la simplicité, réduire les dépenses ;<br><b>B</b> <i>intr. c</i>. σωφρονέω, JOS. <i>B.J. 4, 2, 5</i>.<br><span><b>Étym</b>. σώφρων.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">σωφρονιζω - σωφρονίζω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Tite (1)</li>\n</ul>\n</td></tr>\n</table>","G4995":"<h1>sophronismos</h1>\n<p>Strong n° 4995 <i>Prononciation [so-fron-is-mos']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>une réprimande ou un appel à un esprit sain, à la modération et au contrôle de soi</li>\n<li>auto-contrôle, modération, sobriété</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>σωφρονισμός, οῦ (ὁ)</b> action de rendre sage, d’amender, PLUT. <i>Cato mi. 19, M. 653</i> c ; APP. <i>Lib. 65</i>.<br><span><b>Étym</b>. σωφρονίζω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">σωφρονισμος - σωφρονισμός</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>2 Timothée (1)</li>\n</ul>\n</td></tr>\n</table>","G4996":"<h1>sophronos</h1>\n<p>Strong n° 4996 <i>Prononciation [so-fron'-oce]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>avec un esprit sain, sobrement, d'une manière tempérée, discrètement</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>σωφρόνως</b>, <i>adv</i>., avec modération, prudence, sagesse, HDT. <i>4, 77 ;</i> ESCHL. <i>Sept. 645, Eum. 44, etc. ; joint à</i> μετρίως, PLAT. <i>Rsp. 399</i> b ; <i>à</i> δικαίως, PLAT. <i>1 Alc. 134</i> d, <i>etc</i>.<br><span>•<i> Cp</i>. σωφρονέστερον, THC. <i>1, 84, etc. ou</i> σωφρονεστέρως, EUR. <i>I.A. 379</i>. <i>• Sup</i>. σωφρονέστατα, PLAT. <i>Leg. 728</i> e ; ISOCR. <i>142</i> c.<br><span><b>Étym</b>. σώφρων.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">σωφρονως - σωφρόνως</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adverbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Tite (1)</li>\n</ul>\n</td></tr>\n</table>","G4997":"<h1>sophrosune</h1>\n<p>Strong n° 4997 <i>Prononciation [so-fros-oo'-nay]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>solidité de l'esprit</li>\n<li>auto-contrôle, sobriété, modération, mesure, pudeur</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>σωφροσύνη, ης (ἡ)</b> <span>[ῠ]</span> <i>litt</i>. état sain de l’esprit <i>ou</i> du cœur (<i>v</i>. σώφρων), <i>d’où :</i><br><b>   I</b> bon sens, prudence, sagesse, OD. <i>23, 13 ;</i> THGN. <i>379, 702, 1138 ; p. opp. à</i> μανία, XÉN. <i>Mem. 1, 1, 16 ;</i><br><b>   II</b> <i>p. suite :</i><br><b>      1</b> modération dans les désirs, tempérance, PLAT. <i>Conv. 196</i> e ; AR. <i>Nub. 962, Pl. 563, etc. ;</i><br><b>      2</b> modestie, simplicité, THC. <i>1, 84 ; 8, 64 ;</i> PLAT. <i>Phæd. 68</i> c, <i>Rsp. 430</i> e ; ARSTT. <i>Nic. 3, 10, etc</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Dor</i>. σωφροσύνα, EPICH. (STOB. <i>Fl. 58, 7) ; épq</i>. σαοφροσύνη, OD. <i>l. c</i>.<br><span><b>Étym</b>. σώφρων.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">σωφροσυνη - σωφροσύνη</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 2 livres bibliques (NT)\n<ul>\n<li>Actes (1)</li>\n<li>1 Timothée (2)</li>\n</ul>\n</td></tr>\n</table>","G4998":"<h1>sophron</h1>\n<p>Strong n° 4998 <i>Prononciation [so'-frone]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>d'un esprit solide, sain, dans son sens</li>\n<li>fléchissant ses désirs et impulsions, tempéré, modéré</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>σώ·φρων, ων, ον</b>, <i>gén</i>. <b>ονος</b>, <i>litt</i>. sain d’esprit <i>ou</i> de cœur, PLAT. <i>Crat. 411</i> e ; ARSTT. <i>Nic. 6, 5, 6 ; d’où :</i><br><b>   I</b> sensé, prudent, sage, <i>en parl. de pers</i>. IL. <i>21, 462 ;</i> OD. <i>4, 158 ; p. opp. à</i> ἄφρων, THGN. <i>431, 454, 497 ; à</i> νήπιος, THGN. <i>483 ; à</i> ἀνόητος, HDT. <i>1, 4 ; en parl. de choses (parole,</i> THGN. <i>754 ;</i> EUR. <i>I.A. 1024, etc</i>.) ; τὸ σῶφρον, THC. <i>1, 37, etc</i>. le bon sens, la sagesse ;<br><b>   II</b> modéré dans ses désirs, tempérant, SOPH. <i>Aj. 132 ;</i> PLAT. <i>Def. 415</i> d, <i>Rsp. 430</i> e ; <i>joint à</i> ἐγκρατὴς ἑαυτοῦ, PLAT. <i>Gorg. 491</i> d ; <i>particul. :</i><br><b>      1</b> chaste, pudique, ESCHL. <i>Ch. 140 ;</i> AND. <i>30, 43 ; en parl. de choses (mariage,</i> EUR. <i>Or. 558 ; couche,</i> EUR. <i>El. 1099, etc</i>.) ; τὸ σῶφρον, la tempérance, la chasteté, SOPH. <i>fr. 705 ;</i> EUR. <i>Hipp. 431, etc. ;</i><br><b>      2</b> sobre, frugal, EUR. <i>fr. 885 ;</i> PLAT. <i>Ep. 336</i> c ;<br><b>      3</b> modéré, THC. <i>3, 82 ;</i><br><b>      4</b> réservé, simple, modeste, PLAT. <i>Leg. 733</i> e.<br><span>•<i> Cp</i>. σωφρονέστερος, HDT. <i>3, 71 ;</i> THC. <i>5, 111, etc. ;</i> <i>• Sup</i>. -έστατος, HPC. <i>84</i> a ; THC. <i>3, 62</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Épq</i>. σαόφρων, HOM. <i>ll. cc</i>.<br><span><b>Étym</b>. σῶς, φρῆν.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">σωφρων - σώφρων</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n4 fois dans 4 versets de 2 livres bibliques (NT)\n<ul>\n<li>1 Timothée (1)</li>\n<li>Tite (3)</li>\n</ul>\n</td></tr>\n</table>","G4999":"<h1>Tabernai</h1>\n<p>Strong n° 4999 <i>Prononciation [tab-er'-nahee]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>tavernes</li>\n<li>Trois Tavernes, le nom d'un lieu d'étape, sur la voie Appienne entre Rome et le Forum d'Appius ; à 15 km de celui-ci et à 45 km de Rome</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Ταβερναι - Ταβέρναι</font>\n<br><br>origine : Latin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin pluriel</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>"};
